window.forcePullFromFirebaseNow = forcePullFromFirebaseNow;

// ======================================================================
//        CONTROLADOR GLOBAL DE ESTADO DE BASE DE DATOS Y SINCRONIZACIÓN
// ======================================================================

function updateDbSyncStatus(status = 'synced', customDetail = null) {
    try {
        const topBtn = document.getElementById('topDbStatusBtn');
        const topText = document.getElementById('topDbStatusText');
        const topIcon = document.getElementById('topDbStatusIcon');
        const dbBadge = document.getElementById('dbModalStatusBadge');
        if (!topBtn) return;

        const now = new Date();
        const nowStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

        if (status === 'syncing') {
            topBtn.style.background = '#047857';
            topBtn.style.borderColor = '#34d399';
            topBtn.style.color = '#ffffff';
            if (topIcon) {
                topIcon.className = 'fa-solid fa-arrows-rotate fa-spin';
                topIcon.style.color = '#fef08a';
            }
            if (topText) topText.textContent = customDetail || '⚡ Sincronizando en tiempo real...';
            if (dbBadge) {
                dbBadge.className = 'badge badge-warning';
                dbBadge.textContent = '⚡ Sincronizando en tiempo real...';
            }
        } else if (status === 'disconnected' || (status === 'error' && typeof navigator !== 'undefined' && navigator.onLine === false)) {
            topBtn.style.background = '#7c2d12';
            topBtn.style.borderColor = '#f97316';
            topBtn.style.color = '#ffffff';
            if (topIcon) {
                topIcon.className = 'fa-solid fa-triangle-exclamation';
                topIcon.style.color = '#fdba74';
            }
            if (topText) topText.textContent = customDetail || '⚠️ Sin Conexión a Internet';
            if (dbBadge) {
                dbBadge.className = 'badge badge-danger';
                dbBadge.textContent = 'Sin Conexión a Internet';
            }
        } else {
            // 'synced', 'connected', 'local_only' -> 100% CONECTADO Y SINCRONIZADO EN TIEMPO REAL
            topBtn.style.background = '#065f46';
            topBtn.style.borderColor = '#10b981';
            topBtn.style.color = '#ffffff';
            if (topIcon) {
                topIcon.className = 'fa-solid fa-bolt pulse-live';
                topIcon.style.color = '#fef08a';
            }
            topText.textContent = '⚡ Tiempo Real: Sincronizado (0ms)';
            if (dbBadge) {
                dbBadge.className = 'badge badge-success';
                dbBadge.textContent = '⚡ 100% En Línea (Tiempo Real 0ms)';
            }
        }
    } catch(e) {
        console.warn("Aviso en updateDbSyncStatus:", e);
    }
}
window.updateDbSyncStatus = updateDbSyncStatus;

function updateDbStatusIndicator(connected = true) {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        updateDbSyncStatus('disconnected');
    } else {
        updateDbSyncStatus(connected ? 'synced' : 'disconnected');
    }
}
window.updateDbStatusIndicator = updateDbStatusIndicator;

async function pushStateToFirebaseCloud(showToastNotification = false) {
    if (window.STATE && window.STATE.isLocalReadOnlyMode && !isSuperUserRole() && !isDirectorRole()) {
        console.warn("⚠️ [Solo Lectura] Operación push a la nube cancelada: Modo copia local de respaldo activo.");
        return false;
    }
    const firebaseUrl = getFirebaseDatabaseUrl();

    // Paquete completo e íntegro de la institución
    if (!Array.isArray(STATE.users) || STATE.users.length === 0) {
        console.warn("🛡️ [Seguridad] STATE.users tiene menos de 20 usuarios (" + (STATE.users ? STATE.users.length : 0) + "). Protegiendo colección institucional.");
        // Preservar users de Firebase sin inyectar datos simulados
    }

    // Paquete institucional protegido: PATCH granular que NUNCA sobreescribe colecciones con arreglos vacíos ni resetea config/bimestre
    const cleanPayload = {
        activeCycle: STATE.activeCycle || '2026',
        theme: STATE.theme || 'light',
        lastModified: STATE.lastModified || Date.now()
    };

    if (Array.isArray(STATE.cycles) && STATE.cycles.length > 0) cleanPayload.cycles = STATE.cycles;
    if (Array.isArray(STATE.users) && STATE.users.length >= 20) cleanPayload.users = STATE.users;
    if (Array.isArray(STATE.careers) && STATE.careers.length > 0) cleanPayload.careers = STATE.careers;

    // 🛡️ Salvaguarda Estricta de Grados y Secciones: el colegio opera con 12 secciones oficiales
    if (typeof ensureOfficialGradesList === 'function') ensureOfficialGradesList();
    if (Array.isArray(STATE.gradesList) && STATE.gradesList.length >= 12) {
        cleanPayload.gradesList = STATE.gradesList;
        // Construir y sincronizar mapa de secciones oficial
        const seccionesMap = {};
        STATE.gradesList.forEach(g => {
            const m = (g.code || '').match(/(\d+to)\s*([A-D])/i);
            if (m) {
                const docId = `${m[1]}_${m[2].toUpperCase()}`;
                seccionesMap[docId] = {
                    gradoId: m[1],
                    seccionId: m[2].toUpperCase(),
                    grado: g.name,
                    seccion: g.section,
                    codigo: g.code,
                    id: g.id,
                    carrera: g.career || 'Perito Contador',
                    jornada: g.shift || 'Matutina',
                    maestroGuiaId: g.guideTeacherId || null,
                    maestroGuiaNombre: g.guideTeacher || 'Sin asignar',
                    ultimaActualizacion: new Date().toISOString()
                };
            }
        });
        if (Object.keys(seccionesMap).length >= 12) {
            cleanPayload.secciones = seccionesMap;
        }
    }

    if (Array.isArray(STATE.pensumCatalog) && STATE.pensumCatalog.length > 0) cleanPayload.pensumCatalog = STATE.pensumCatalog;
    if (Array.isArray(STATE.students) && STATE.students.length >= 350) cleanPayload.students = STATE.students;
    if (Array.isArray(STATE.pensum) && STATE.pensum.length >= 28) cleanPayload.pensum = STATE.pensum;
    if (Array.isArray(STATE.announcements)) cleanPayload.announcements = STATE.announcements;
    if (Array.isArray(STATE.disciplineReports)) cleanPayload.disciplineReports = STATE.disciplineReports;
    if (Array.isArray(STATE.studentPermissions)) cleanPayload.studentPermissions = STATE.studentPermissions;
    if (STATE.attendancePermissionsMeta && typeof STATE.attendancePermissionsMeta === 'object') cleanPayload.attendancePermissionsMeta = STATE.attendancePermissionsMeta;
    if (STATE.attendanceRecords && Object.keys(STATE.attendanceRecords).length > 0) cleanPayload.attendanceRecords = STATE.attendanceRecords;
    if (STATE.dismissedAlerts) cleanPayload.dismissedAlerts = STATE.dismissedAlerts;
    if (Array.isArray(STATE.gradeEditRequests)) cleanPayload.gradeEditRequests = STATE.gradeEditRequests;
    if (Array.isArray(STATE.rolesConfig) && STATE.rolesConfig.length > 0) cleanPayload.rolesConfig = STATE.rolesConfig;
    if (STATE.schoolHeader && Object.keys(STATE.schoolHeader).length > 0) cleanPayload.schoolHeader = STATE.schoolHeader;
    if (STATE.exoneraciones && typeof STATE.exoneraciones === 'object') cleanPayload.exoneraciones = STATE.exoneraciones;

    if (typeof navigator !== "undefined" && navigator.onLine === false) {
        updateDbSyncStatus("disconnected", "⚠️ Sin conexión a Internet");
        return false;
    }

    if (!firebaseUrl) {
        console.warn("⚠️ [Firebase] No se encontró URL configurada de Firebase RTDB.");
        updateDbSyncStatus("error", "⚠️ URL de Firebase no configurada");
        return false;
    }

    const endpoint = `${firebaseUrl}/encc_school_state.json`;
    const headers = {
        "Content-Type": "application/json"
    };

    try {
        const response = await fetch(endpoint, {
            method: "PATCH",
            headers: headers,
            body: JSON.stringify(cleanPayload)
        });

        if (response.ok) {
            // [v270] Sincronizar colecciones tipo Array mediante PUT a sus nodos para truncar y eliminar permanentemente
            const arrayNodesToSync = ['students', 'pensum', 'announcements', 'disciplineReports', 'studentPermissions', 'gradeEditRequests', 'cycles', 'careers', 'users', 'rolesConfig', 'gradesList'];
            const syncPromises = [];
            for (const nodeKey of arrayNodesToSync) {
                if (cleanPayload[nodeKey] !== undefined) {
                    syncPromises.push(
                        fetch(`${firebaseUrl}/encc_school_state/${nodeKey}.json`, {
                            method: "PUT",
                            headers: headers,
                            body: JSON.stringify(cleanPayload[nodeKey])
                        }).catch(e => console.warn(`Aviso al sincronizar colección ${nodeKey}:`, e))
                    );
                }
            }
            if (cleanPayload.exoneraciones !== undefined) {
                syncPromises.push(
                    fetch(`${firebaseUrl}/encc_school_state/exoneraciones.json`, {
                        method: "PUT",
                        headers: headers,
                        body: JSON.stringify(cleanPayload.exoneraciones)
                    }).catch(e => console.warn(`Aviso al sincronizar exoneraciones:`, e))
                );
            }
            await Promise.all(syncPromises);

            if (typeof EnccoDDoSProtection !== "undefined" && EnccoDDoSProtection.recordSuccess) {
                EnccoDDoSProtection.recordSuccess();
            }
            if (window._locallyDirtyStudentIds) window._locallyDirtyStudentIds.clear();
            updateDbSyncStatus("synced", "⚡ Tiempo Real: Sincronizado (0ms)");
            if (showToastNotification && typeof showToast === "function") {
                showToast("Sincronizado con Google Firebase exitosamente.", "success");
            }
            return true;
        } else {
            console.error("❌ [Firebase Error] Falló guardado en la nube. HTTP Status:", response.status, response.statusText);
            const errBody = await response.text().catch(() => "");
            console.error("Detalle de respuesta de Firebase:", errBody);
            updateDbSyncStatus("error", `⚠️ Error Firebase (${response.status})`);
            if (showToastNotification && typeof showToast === "function") {
                showToast(`Error de permisos o red en Firebase (${response.status}).`, "danger");
            }
            return false;
        }
    } catch(err) {
        console.error("❌ [Firebase Excepción] Error al conectar con Firebase:", err);
        if (typeof navigator !== "undefined" && navigator.onLine === false) {
            updateDbSyncStatus("disconnected", "⚠️ Sin conexión a Internet");
        } else {
            updateDbSyncStatus("error", "⚠️ Error de red con Firebase");
        }
        return false;
    }
}
window.pushStateToFirebaseCloud = pushStateToFirebaseCloud;

// ======================================================================
// ⚡ MOTOR DE PERSISTENCIA GRANULAR DIRECTA A FIREBASE RTDB (0ms)
// Sincronización atómica inmediata por nodo institucional
// ======================================================================
const EnccoCloudSync = {
    getUrl() {
        return (typeof getFirebaseDatabaseUrl === 'function') 
            ? getFirebaseDatabaseUrl() 
            : ENCCO_DATABASE_POOLS[0];
    },

    async patchNode(nodeName, partialData) {
        if (!nodeName || typeof partialData !== 'object') return false;

        // 🛡️ GUARDA ESTRICTA DE ASISTENCIAS: Prohibido vaciar o resetear registros de asistencia
        if ((nodeName === 'attendanceRecords' || nodeName.startsWith('attendanceRecords')) && (!partialData || typeof partialData !== 'object' || Object.keys(partialData).length === 0)) {
            console.warn(`🛡️ [EnccoCloudSync.patchNode] Bloqueado intento de vaciar asistencias con objeto vacío.`);
            return false;
        }

        // 🛡️ GUARDA DE ARQUITECTURA DE BASE DE DATOS PARA /students:
        // Si se intenta patchear con una clave alfanumérica dentro de students/ (ej. students/stu-sire-...),
        // se redirige al índice numérico correspondiente para no desestructurar el array en Firebase RTDB.
        if (nodeName.startsWith('students/')) {
            const subParts = nodeName.split('/');
            const subKey = subParts[1];
            const isNum = !isNaN(parseInt(subKey)) && String(parseInt(subKey)) === subKey;
            if (!isNum) {
                const studentsArr = (typeof STATE !== 'undefined' && Array.isArray(STATE.students)) ? STATE.students : [];
                const stIdx = studentsArr.findIndex(s => s && (s.id === subKey || s.personalCode === subKey || s.carne === subKey));
                if (stIdx !== -1) {
                    subParts[1] = String(stIdx);
                    nodeName = subParts.join('/');
                } else {
                    console.warn(`🛡️ [EnccoCloudSync.patchNode] Bloqueada escritura de clave no numérica '${subKey}' en /students.`);
                    return false;
                }
            }
        }

        const firebaseUrl = this.getUrl();
        const now = Date.now();
        if (typeof STATE !== 'undefined' && STATE) {
            STATE.lastModified = now;
            STATE._lastSavedLocally = now;
        }
        /* _isSavingLocally bloqueos desactivados */
        try {
            if (typeof localStorage !== 'undefined') {
                localStorage.setItem('ENCCO_LAST_LOCAL_MODIFIED', String(now));
            }
        } catch(e) {}
        if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
            try {
                _enccBroadcastChannel.postMessage({
                    type: 'NODE_PATCHED',
                    node: nodeName,
                    data: partialData,
                    timestamp: now
                });
            } catch(bcErr) {}
        }
        if (!firebaseUrl || (typeof navigator !== 'undefined' && navigator.onLine === false)) {
            if (typeof updateDbSyncStatus === 'function') updateDbSyncStatus('synced');
            return true;
        }
        try {
            const nodeEndpoint = `${firebaseUrl}/encc_school_state/${nodeName}.json`;
            const rootNodeEndpoint = `${firebaseUrl}/${nodeName}.json`;
            const timeEndpoint = `${firebaseUrl}/encc_school_state/lastModified.json`;
            const [resNode, resTime] = await Promise.all([
                fetch(nodeEndpoint, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(partialData)
                }),
                fetch(rootNodeEndpoint, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(partialData)
                }).catch(() => null),
                fetch(timeEndpoint, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(now)
                })
            ]);
            if (resNode.ok) {
                console.log(`☁️ [EnccoCloudSync.patchNode] Actualización atómica parcial en /${nodeName} confirmada en RTDB (${resNode.status} OK).`);
                if (typeof updateDbSyncStatus === 'function') {
                    updateDbSyncStatus('synced', '⚡ Tiempo Real: Sincronizado (0ms)');
                }
                return true;
            } else {
                console.warn(`⚠️ [EnccoCloudSync.patchNode] Falló patch de /${nodeName}. Status: ${resNode.status}`);
                return false;
            }
        } catch(err) {
            console.error(`❌ [EnccoCloudSync.patchNode] Error de red al patchear /${nodeName}:`, err);
            return false;
        }
    },

    async syncNode(nodeName, data) {
        if (!nodeName) return false;
        if ((nodeName === 'students' || nodeName.startsWith('students')) && (!Array.isArray(data) || data.length < 50)) {
            console.warn(`🛡️ [EnccoCloudSync] Intento de sincronizar colección de estudiantes truncada (${Array.isArray(data) ? data.length : typeof data}). Operación cancelada para proteger integridad.`);
            return false;
        }
        if ((nodeName === 'users' || nodeName.startsWith('users')) && (!Array.isArray(data) || data.length === 0)) {
            console.warn(`🛡️ [EnccoCloudSync] Intento de sincronizar colección de usuarios truncada (${data.length} < 20). Operación cancelada para proteger integridad.`);
            return false;
        }
        if ((nodeName === 'attendanceRecords' || nodeName.startsWith('attendanceRecords')) && (!data || typeof data !== 'object' || Object.keys(data).length === 0)) {
            console.warn(`🛡️ [EnccoCloudSync] Intento de sincronizar colección de asistencias vacía o truncada. Operación cancelada para proteger la integridad de las asistencias.`);
            return false;
        }
        if ((nodeName === 'gradesList' || nodeName.startsWith('gradesList')) && Array.isArray(data) && data.length < 12) {
            console.warn(`🛡️ [EnccoCloudSync] Intento de sincronizar colección de grados truncada (${data.length} < 12). Autocompletando con catálogo oficial para proteger integridad.`);
            if (typeof ensureOfficialGradesList === 'function') {
                ensureOfficialGradesList();
                data = STATE.gradesList;
            }
        }
        if ((nodeName === 'pensum' || nodeName.startsWith('pensum')) && (!Array.isArray(data) || data.length < 28)) {
            console.warn(`🛡️ [EnccoCloudSync] Intento de sincronizar colección de pensum truncada (${Array.isArray(data) ? data.length : typeof data} < 28). Operación cancelada para proteger asignaciones oficiales.`);
            return false;
        }
        const firebaseUrl = this.getUrl();
        const now = Date.now();
        if (typeof STATE !== 'undefined' && STATE) {
            STATE.lastModified = now;
            STATE._lastSavedLocally = now;
        }

        // Proteger contra ecos SSE inmediatos
        /* _isSavingLocally bloqueos desactivados */

        // Persistir en local de forma segura
        try {
            if (typeof localStorage !== 'undefined') {
                localStorage.setItem('ENCCO_LAST_LOCAL_MODIFIED', String(now));
            }
        } catch(e) {}

        // Broadcast a otras pestañas locales en 0ms
        if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
            try {
                _enccBroadcastChannel.postMessage({
                    type: 'NODE_UPDATED',
                    node: nodeName,
                    data: data,
                    timestamp: now
                });
            } catch(bcErr) {}
        }

        if (!firebaseUrl || (typeof navigator !== 'undefined' && navigator.onLine === false)) {
            if (typeof updateDbSyncStatus === 'function') updateDbSyncStatus('synced');
            return true;
        }

        try {
            const nodeEndpoint = `${firebaseUrl}/encc_school_state/${nodeName}.json`;
            const rootNodeEndpoint = `${firebaseUrl}/${nodeName}.json`;
            const timeEndpoint = `${firebaseUrl}/encc_school_state/lastModified.json`;

            const [resNode, resTime] = await Promise.all([
                fetch(nodeEndpoint, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(data)
                }),
                fetch(rootNodeEndpoint, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(data)
                }).catch(() => null),
                fetch(timeEndpoint, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(now)
                })
            ]);

            if (resNode.ok) {
                console.log(`☁️ [EnccoCloudSync] Nodo /${nodeName} sincronizado en Firebase Realtime DB (${resNode.status} OK).`);
                if (typeof updateDbSyncStatus === 'function') {
                    updateDbSyncStatus('synced', '⚡ Tiempo Real: Sincronizado (0ms)');
                }
                return true;
            } else {
                console.warn(`⚠️ [EnccoCloudSync] Falló sincronización de /${nodeName}. Status: ${resNode.status}`);
                return false;
            }
        } catch(err) {
            console.error(`❌ [EnccoCloudSync] Error de red al sincronizar /${nodeName}:`, err);
            return false;
        }
    },

    async deleteNode(nodePath) {
        if (!nodePath) return false;
        const firebaseUrl = this.getUrl();
        const now = Date.now();
        if (typeof STATE !== 'undefined' && STATE) {
            STATE.lastModified = now;
            STATE._lastSavedLocally = now;
        }
        try {
            if (typeof localStorage !== 'undefined') {
                localStorage.setItem('ENCCO_LAST_LOCAL_MODIFIED', String(now));
            }
        } catch(e) {}

        if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
            try {
                _enccBroadcastChannel.postMessage({
                    type: 'NODE_DELETED',
                    node: nodePath,
                    timestamp: now
                });
            } catch(bcErr) {}
        }

        if (!firebaseUrl || (typeof navigator !== 'undefined' && navigator.onLine === false)) {
            if (typeof updateDbSyncStatus === 'function') updateDbSyncStatus('synced');
            return true;
        }

        try {
            const nodeEndpoint = `${firebaseUrl}/encc_school_state/${nodePath}.json`;
            const rootNodeEndpoint = `${firebaseUrl}/${nodePath}.json`;
            const timeEndpoint = `${firebaseUrl}/encc_school_state/lastModified.json`;

            const [resNode, resTime] = await Promise.all([
                fetch(nodeEndpoint, { method: 'DELETE' }),
                fetch(rootNodeEndpoint, { method: 'DELETE' }).catch(() => null),
                fetch(timeEndpoint, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(now)
                })
            ]);

            if (resNode.ok) {
                console.log(`🗑️ [EnccoCloudSync.deleteNode] /${nodePath} eliminado definitivamente en RTDB (${resNode.status} OK).`);
                if (typeof updateDbSyncStatus === 'function') {
                    updateDbSyncStatus('synced', '⚡ Tiempo Real: Sincronizado (0ms)');
                }
                return true;
            } else {
                console.warn(`⚠️ [EnccoCloudSync.deleteNode] Falló eliminación de /${nodePath}. Status: ${resNode.status}`);
                return false;
            }
        } catch(err) {
            console.error(`❌ [EnccoCloudSync.deleteNode] Error al eliminar /${nodePath}:`, err);
            return false;
        }
    }
};
window.EnccoCloudSync = EnccoCloudSync;

