function loadRoleIntoPermissionsPanel(roleKey) {
    normalizeRolesConfig();
    const r = (STATE.rolesConfig || []).find(x => x.key === roleKey) || STATE.rolesConfig[0];
    if (!r) return;

    _selectedRoleKeyForEditing = r.key;
    const canEdit = isDirectorOrSuperAdmin();

    const keyInput = document.getElementById('activeRoleKey');
    const nameInput = document.getElementById('activeRoleName');
    const descInput = document.getElementById('activeRoleDesc');
    const colorInput = document.getElementById('activeRoleColor');

    const SYSTEM_ROLE_KEYS = (typeof window.SYSTEM_ROLE_KEYS !== 'undefined') 
        ? window.SYSTEM_ROLE_KEYS 
        : ['admin', 'director', 'secretaria', 'profesor_auxiliar', 'docente', 'estudiante'];
    const isSystemRole = (r.isSystem || SYSTEM_ROLE_KEYS.includes(r.key));
    const isLocked = isSystemRole || !canEdit;

    if (keyInput) { 
        keyInput.value = r.key; 
        keyInput.readOnly = isLocked; 
        keyInput.style.backgroundColor = isLocked ? '#f1f5f9' : '#ffffff';
        keyInput.style.cursor = isLocked ? 'not-allowed' : 'text';
    }
    if (nameInput) {
        nameInput.value = r.name; 
        nameInput.readOnly = isLocked; 
        nameInput.style.backgroundColor = isLocked ? '#f1f5f9' : '#ffffff';
        nameInput.style.cursor = isLocked ? 'not-allowed' : 'text';
    }
    if (descInput) {
        descInput.value = r.description || ''; 
        descInput.readOnly = isLocked; 
        descInput.style.backgroundColor = isLocked ? '#f1f5f9' : '#ffffff';
        descInput.style.cursor = isLocked ? 'not-allowed' : 'text';
    }
    if (colorInput) {
        colorInput.value = r.color || '#0284c7'; 
        colorInput.disabled = isLocked; 
        colorInput.style.cursor = isLocked ? 'not-allowed' : 'pointer';
    }

    renderActiveRolePermissionsGrid(r.permissions || []);

    const delBtn = document.getElementById('btnDeleteActiveRole');
    if (delBtn) {
        if (isSystemRole || !canEdit) {
            delBtn.style.display = 'none';
        } else {
            delBtn.style.display = 'inline-flex';
            delBtn.setAttribute('onclick', `deleteRole('${r.key}')`);
        }
    }

    // Adaptar controles y botones de guardado según facultades del usuario
    const saveBtns = document.querySelectorAll('button[onclick*="saveActiveRolePermissions"]');
    saveBtns.forEach(btn => {
        btn.style.display = canEdit ? 'inline-flex' : 'none';
    });

    const bulkBtns = document.querySelectorAll('button[onclick^="setAllPermissionsLevel"]');
    bulkBtns.forEach(btn => {
        btn.style.display = canEdit ? 'inline-flex' : 'none';
    });

    const newRoleBtn = document.getElementById('btnCreateNewRoleHeader');
    if (newRoleBtn) {
        newRoleBtn.style.display = canEdit ? 'inline-flex' : 'none';
    }
}
window.loadRoleIntoPermissionsPanel = loadRoleIntoPermissionsPanel;



let _isSavingActiveRolePermissions = false;
async function saveActiveRolePermissions(e) {
    const evt = e || (typeof window !== 'undefined' ? window.event : null);
    if (evt) {
        if (evt._enccoHandled) return;
        evt._enccoHandled = true;
    }
    if (_isSavingActiveRolePermissions) return;
    _isSavingActiveRolePermissions = true;

    try {
        if (!isDirectorOrSuperAdmin()) {
            showToast('Acceso Restringido: La edición y configuración de permisos está reservada exclusivamente a la Dirección General.', 'warning');
            return;
        }

    const keyInput = document.getElementById('activeRoleKey');
    const nameInput = document.getElementById('activeRoleName');
    const descInput = document.getElementById('activeRoleDesc');
    const colorInput = document.getElementById('activeRoleColor');

    const key = keyInput ? keyInput.value.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_') : '';
    const name = nameInput ? nameInput.value.trim() : '';
    const desc = descInput ? descInput.value.trim() : '';
    const color = colorInput ? colorInput.value : '#0284c7';

    if (!key || !name) {
        showToast('Debe ingresar la clave y el nombre del rol.', 'warning');
        return;
    }

    const permissionLevels = {};
    const permissions = [];

    SYSTEM_MODULES_LIST.forEach(mod => {
        if (key === 'admin' || key === 'director' || key === 'super_usuario') {
            permissionLevels[mod.key] = 'edit';
            permissions.push(mod.key, mod.key + '_edit', mod.key + '_view');
        } else {
            const checkedRadio = document.querySelector(`input[name="permLevel_${mod.key}"]:checked`);
            const level = checkedRadio ? checkedRadio.value : 'none';
            permissionLevels[mod.key] = level;

            if (level === 'edit') {
                permissions.push(mod.key, mod.key + '_edit', mod.key + '_view');
            } else if (level === 'view') {
                permissions.push(mod.key, mod.key + '_view');
            }
        }
    });
    const SYSTEM_ROLE_KEYS = (typeof window.SYSTEM_ROLE_KEYS !== 'undefined') 
        ? window.SYSTEM_ROLE_KEYS 
        : ['admin', 'director', 'secretaria', 'profesor_auxiliar', 'docente', 'estudiante'];
    const isSystemRole = (key === 'admin' || SYSTEM_ROLE_KEYS.includes(key));

        const existingIdx = STATE.rolesConfig.findIndex(r => r.key === key);
        if (existingIdx !== -1) {
            if (isSystemRole) {
                STATE.rolesConfig[existingIdx].isSystem = true;
                STATE.rolesConfig[existingIdx].permissions = permissions;
                STATE.rolesConfig[existingIdx].permissionLevels = permissionLevels;
                if (desc) STATE.rolesConfig[existingIdx].description = desc;
            } else {
                STATE.rolesConfig[existingIdx].name = name;
                STATE.rolesConfig[existingIdx].description = desc;
                STATE.rolesConfig[existingIdx].color = color;
                STATE.rolesConfig[existingIdx].permissions = permissions;
                STATE.rolesConfig[existingIdx].permissionLevels = permissionLevels;
            }
        } else {
            STATE.rolesConfig.push({
                key: key,
                name: name,
                description: desc,
                color: color,
                isSystem: isSystemRole,
                permissions: permissions,
                permissionLevels: permissionLevels
            });
        }

        normalizeRolesConfig();
        _selectedRoleKeyForEditing = key;

        const roleObjInState = STATE.rolesConfig.find(r => r.key === key) || {
            key: key,
            name: name,
            description: desc,
            color: color,
            isSystem: isSystemRole,
            permissions: permissions,
            permissionLevels: permissionLevels
        };

        // CONFIRMACIÓN DE ESCRITURA ATÓMICA EN FIREBASE (AISLAMIENTO TOTAL DE ROLES)
        const nowTime = Date.now();
        const roleObj = {
            ...roleObjInState,
            lastModified: nowTime
        };

        // 🚀 RESPUESTA INSTANTÁNEA EN LA INTERFAZ (Actualización optimista a 0ms)
        STATE.lastModified = nowTime;
        saveStateToLocalStorage();
        applyUserRole(STATE.currentRole);
        renderRolesManagementView();
        showToast(`Permisos del rol "${roleObjInState.name}" guardados exitosamente.`, 'success');

        // 🌟 Persistencia atómica en Firestore y RTDB en segundo plano
        (async () => {
            if (window.FirebaseModular && window.FirebaseModular.db) {
                try {
                    const { db, doc, writeBatch, setDoc } = window.FirebaseModular;
                    const rolRef = doc(db, 'roles', key);
                    const roleDocRef = doc(db, 'rolesConfig', key);
                    const configDocRef = doc(db, 'config', 'rolesConfig');

                    const rolPayload = {
                        id: key,
                        key: key,
                        nombre: roleObjInState.name,
                        name: roleObjInState.name,
                        descripcion: roleObjInState.description,
                        description: roleObjInState.description,
                        color: roleObjInState.color,
                        permisos: permissions,
                        permissions: permissions,
                        ultimaModificacion: new Date().toISOString(),
                        lastModified: nowTime
                    };

                    if (typeof writeBatch === 'function') {
                        const batch = writeBatch(db);
                        batch.set(roleDocRef, roleObj, { merge: true });
                        batch.set(rolRef, rolPayload, { merge: true });
                        // Persistir todos los roles del sistema en rolesConfig para asegurar que Firestore tenga todos los docs
                        (STATE.rolesConfig || []).forEach(r => {
                            if (r && r.key) {
                                batch.set(doc(db, 'rolesConfig', r.key), r, { merge: true });
                            }
                        });
                        batch.set(configDocRef, { list: STATE.rolesConfig, roles: STATE.rolesConfig, lastModified: nowTime }, { merge: true });
                        await withTimeout(batch.commit(), 6000, 'Tiempo de espera en batch de roles en Firestore');
                    } else if (typeof setDoc === 'function') {
                        const promises = [
                            setDoc(roleDocRef, roleObj, { merge: true }),
                            setDoc(rolRef, rolPayload, { merge: true }),
                            setDoc(configDocRef, { list: STATE.rolesConfig, roles: STATE.rolesConfig, lastModified: nowTime }, { merge: true })
                        ];
                        (STATE.rolesConfig || []).forEach(r => {
                            if (r && r.key && r.key !== key) {
                                promises.push(setDoc(doc(db, 'rolesConfig', r.key), r, { merge: true }));
                            }
                        });
                        await Promise.all(promises);
                    }
                } catch(fsErr) {
                    console.warn("Aviso al persistir roles en Firestore:", fsErr);
                }
            }

            try {
                const rtdbPromises = [];
                if (typeof EnccoCloudSync !== 'undefined') {
                    if (typeof EnccoCloudSync.patchNode === 'function') {
                        rtdbPromises.push(EnccoCloudSync.patchNode(`roles/${key}`, roleObj));
                    }
                    if (typeof EnccoCloudSync.syncNode === 'function') {
                        rtdbPromises.push(EnccoCloudSync.syncNode('rolesConfig', STATE.rolesConfig));
                    }
                }
                if (rtdbPromises.length > 0) {
                    await withTimeout(Promise.all(rtdbPromises), 6000, 'Tiempo de espera en Realtime Database agotado.');
                }
            } catch(rtdbErr) {
                console.warn("Aviso en RTDB al guardar rol activo:", rtdbErr);
            }
        })();
    } catch(err) {
        console.error("❌ Error al guardar roles en Firebase:", err);
        showToast(`Error al guardar roles: ${err.message || err}`, 'danger');
    } finally {
        setTimeout(() => {
            _isSavingActiveRolePermissions = false;
        }, 800);
    }
}
window.saveActiveRolePermissions = saveActiveRolePermissions;

// ======================================================================
// 🛡️ MOTOR UNIVERSAL DE AUDITORÍA Y TRAZABILIDAD (STATE.auditLog)
// ======================================================================
if (!window.STATE) window.STATE = {};
if (!window.STATE.auditLog) {
    try {
        const savedLog = localStorage.getItem('ENCCO_AUDIT_LOG_SNAPSHOT');
        window.STATE.auditLog = savedLog ? JSON.parse(savedLog) : [];
    } catch(e) {
        window.STATE.auditLog = [];
    }
}

let _auditLogSaveTimer = null;
function scheduleAuditLogSaveDebounced() {
    if (_auditLogSaveTimer) return;
    _auditLogSaveTimer = setTimeout(() => {
        _auditLogSaveTimer = null;
        try {
            localStorage.setItem('ENCCO_AUDIT_LOG_SNAPSHOT', JSON.stringify((STATE.auditLog || []).slice(0, 300)));
        } catch(e) {}
    }, 4000);
}

function recordAuditLog(action, category, details, targetId = '') {
    if (!STATE.auditLog) STATE.auditLog = [];
    const now = new Date();
    const currentUser = STATE.currentUser || {};
    const logEntry = {
        id: 'aud_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
        timestamp: now.toISOString(),
        formattedTime: now.toLocaleString('es-GT', { dateStyle: 'short', timeStyle: 'medium' }),
        userId: currentUser.id || 'system',
        userName: currentUser.name || (STATE.currentRole === 'director' ? 'Dirección General' : (STATE.currentRole === 'secretaria' ? 'Secretaría Académica' : 'Usuario')),
        userRole: STATE.currentRole || 'general',
        action: action, // ej. 'GRADE_SAVE', 'ATTENDANCE_OVERRIDE', 'BACKUP_EXPORT', 'STUDENT_UPDATE'
        category: category, // 'Calificaciones', 'Asistencia', 'Estudiantes', 'Seguridad', 'Sistema'
        details: typeof details === 'object' ? JSON.stringify(details) : String(details),
        targetId: targetId
    };
    STATE.auditLog.unshift(logEntry);
    if (STATE.auditLog.length > 2000) {
        STATE.auditLog = STATE.auditLog.slice(0, 2000);
    }
    scheduleAuditLogSaveDebounced();
    return logEntry;
}
window.recordAuditLog = recordAuditLog;

