function normalizeRolesConfig() {
    const defaultRoles = initDefaultRolesConfig();

    if (STATE.rolesConfig && !Array.isArray(STATE.rolesConfig) && typeof STATE.rolesConfig === 'object') {
        STATE.rolesConfig = Object.keys(STATE.rolesConfig).map(k => ({
            ...STATE.rolesConfig[k],
            key: STATE.rolesConfig[k].key || k
        }));
    }

    if (!Array.isArray(STATE.rolesConfig) || STATE.rolesConfig.length === 0) {
        STATE.rolesConfig = defaultRoles.map(r => ({ ...r }));
    }

    // 1. Garantizar que TODOS los 6 roles oficiales del sistema existan de manera permanente
    defaultRoles.forEach(defRole => {
        const existing = STATE.rolesConfig.find(r => r && (r.key === defRole.key || r.id === defRole.key));
        if (!existing) {
            // El rol oficial faltaba: restaurarlo inmediatamente
            STATE.rolesConfig.push({ ...defRole, isSystem: true });
        } else {
            // El rol oficial existe: blindar sus propiedades estructurales permanentes
            existing.key = defRole.key;
            existing.isSystem = true;
            if (!existing.name) existing.name = defRole.name;
            if (!existing.description) existing.description = defRole.description;
            if (!existing.color) existing.color = defRole.color;
        }
    });

    // 2. Ordenar roles: los 6 oficiales primero en su orden canónico, seguidos de los personalizados
    const systemOrder = { 'admin': 1, 'director': 2, 'secretaria': 3, 'profesor_auxiliar': 4, 'docente': 5, 'estudiante': 6 };
    STATE.rolesConfig.sort((a, b) => {
        const orderA = systemOrder[a.key] || 99;
        const orderB = systemOrder[b.key] || 99;
        if (orderA !== orderB) return orderA - orderB;
        return (a.name || '').localeCompare(b.name || '');
    });

    // 3. Normalizar permisos y matrices de 3 niveles para cada rol
    STATE.rolesConfig.forEach(roleObj => {
        if (SYSTEM_ROLE_KEYS.includes(roleObj.key)) {
            roleObj.isSystem = true;
        }

        if (!Array.isArray(roleObj.permissions)) {
            const defMatch = defaultRoles.find(d => d.key === roleObj.key);
            roleObj.permissions = defMatch ? [...defMatch.permissions] : [];
        }

        if (!roleObj.permissionLevels || typeof roleObj.permissionLevels !== 'object') {
            roleObj.permissionLevels = {};
        }

        // Asegurar que el docente tenga valores iniciales solo si aún no están definidos en permissionLevels
        if (roleObj.key === 'docente') {
            if (!roleObj.permissionLevels) roleObj.permissionLevels = {};
            const docenteDefaults = {
                'students': 'view',
                'guide-teachers': 'view',
                'reports': 'view',
                'honor-roll': 'view',
                'grade-stats': 'view',
                'dashboard': 'view',
                'gradebook': 'edit',
                'attendance': 'edit',
                'discipline': 'edit',
                'exoneraciones-log': 'view',
                'permissions-history': 'view',
                'users': 'view'
            };
            Object.keys(docenteDefaults).forEach(p => {
                if (typeof roleObj.permissionLevels[p] === 'undefined') {
                    // Si nunca se ha configurado el nivel, usar el default y sincronizar permissions
                    roleObj.permissionLevels[p] = docenteDefaults[p];
                    if (!roleObj.permissions.includes(p)) roleObj.permissions.push(p);
                }
            });
        }

        // 🛡️ ACCESO TOTAL A BITÁCORA Y CENTRO DE CONTROL: Dirección, Auxiliatura y Secretaría (solo si no configurado)
        if (['director', 'direccion', 'secretaria', 'profesor_auxiliar', 'auxiliar', 'auxiliatura'].includes(roleObj.key)) {
            if (!roleObj.permissionLevels) roleObj.permissionLevels = {};
            if (typeof roleObj.permissionLevels['auxiliatura-log'] === 'undefined') {
                roleObj.permissionLevels['auxiliatura-log'] = 'edit';
                if (!roleObj.permissions.includes('auxiliatura-log')) roleObj.permissions.push('auxiliatura-log');
            }
            if (typeof roleObj.permissionLevels['auxiliatura-center'] === 'undefined') {
                roleObj.permissionLevels['auxiliatura-center'] = 'edit';
                if (!roleObj.permissions.includes('auxiliatura-center')) roleObj.permissions.push('auxiliatura-center');
            }
            if (roleObj.key === 'profesor_auxiliar') {
                if (typeof roleObj.permissionLevels['exam-schedules'] === 'undefined') {
                    roleObj.permissionLevels['exam-schedules'] = 'edit';
                    if (!roleObj.permissions.includes('exam-schedules')) roleObj.permissions.push('exam-schedules');
                }
                if (typeof roleObj.permissionLevels['users'] === 'undefined') {
                    roleObj.permissionLevels['users'] = 'view';
                    if (!roleObj.permissions.includes('users')) roleObj.permissions.push('users', 'users_view');
                }
            }
        }

        SYSTEM_MODULES_LIST.forEach(m => {
            if (roleObj.key === 'admin' || roleObj.key === 'director' || roleObj.key === 'super_usuario') {
                roleObj.permissionLevels[m.key] = 'edit';
                if (!roleObj.permissions.includes(m.key)) roleObj.permissions.push(m.key);
                if (!roleObj.permissions.includes(m.key + '_edit')) roleObj.permissions.push(m.key + '_edit');
                if (!roleObj.permissions.includes(m.key + '_view')) roleObj.permissions.push(m.key + '_view');
            } else if (typeof roleObj.permissionLevels[m.key] === 'undefined') {
                // Si aún no se ha definido el nivel explícito para este módulo, derivarlo de permissions
                if (roleObj.permissions.includes(m.key + '_edit')) {
                    roleObj.permissionLevels[m.key] = 'edit';
                } else if (roleObj.permissions.includes(m.key + '_view')) {
                    roleObj.permissionLevels[m.key] = 'view';
                } else if (roleObj.permissions.includes(m.key)) {
                    // Si el módulo base está incluido, si es docente en módulos de solo lectura es view por defecto
                    if (roleObj.key === 'docente' && (m.key === 'guide-teachers' || m.key === 'students' || m.key === 'reports' || m.key === 'honor-roll' || m.key === 'grade-stats' || m.key === 'users')) {
                        roleObj.permissionLevels[m.key] = 'view';
                    } else if (roleObj.key === 'estudiante') {
                        roleObj.permissionLevels[m.key] = 'view';
                    } else {
                        roleObj.permissionLevels[m.key] = 'edit';
                    }
                } else {
                    roleObj.permissionLevels[m.key] = 'none';
                }
            }

            // Consistencia estricta: si el módulo está bloqueado ('none'), removerlo de permissions para que no haya desincronización
            if (roleObj.key !== 'admin' && roleObj.permissionLevels[m.key] === 'none') {
                roleObj.permissions = roleObj.permissions.filter(p => p !== m.key && p !== m.key + '_edit' && p !== m.key + '_view');
            }
        });
    });
}
window.normalizeRolesConfig = normalizeRolesConfig;



function renderRolePermissionsCheckboxes(activePerms = []) {
    const grid = document.getElementById('rolePermissionsCheckboxGrid');
    if (!grid) return;

    grid.innerHTML = SYSTEM_MODULES_LIST.map(mod => {
        const isChecked = Array.isArray(activePerms) && activePerms.includes(mod.key);
        return `
            <label style="display:flex; align-items:flex-start; gap:10px; padding:10px 12px; background:${isChecked ? '#f0fdf4' : '#ffffff'}; border:1.5px solid ${isChecked ? '#86efac' : '#e2e8f0'}; border-radius:8px; cursor:pointer; transition:all 0.15s ease;">
                <input type="checkbox" name="rolePermissionCheckbox" class="chk-permiso" value="${mod.key}" ${isChecked ? 'checked' : ''} onchange="this.parentElement.style.background=this.checked?'#f0fdf4':'#ffffff'; this.parentElement.style.borderColor=this.checked?'#86efac':'#e2e8f0';" style="margin-top:3px; width:17px; height:17px; accent-color:#16a34a; cursor:pointer;">
                <div style="flex:1;">
                    <div style="font-weight:700; color:#1e293b; font-size:0.88rem; display:flex; align-items:center; gap:6px;">
                        <i class="fa-solid ${mod.icon}" style="color:#0284c7; width:16px;"></i> ${mod.name}
                    </div>
                    <div style="font-size:0.75rem; color:#64748b; margin-top:2px; line-height:1.25;">
                        ${mod.desc}
                    </div>
                </div>
            </label>
        `;
    }).join('');
}
window.renderRolePermissionsCheckboxes = renderRolePermissionsCheckboxes;

