/**
 * Guarda y actualiza de forma atómica los permisos y datos de un rol en Firebase Firestore y Realtime DB.
 * Garantiza desbloqueo absoluto de la UI en el bloque finally.
 */
async function guardarPermisosRol(e) {
    if (e && e.preventDefault) e.preventDefault();

    const currentRoleKey = STATE.currentRole || (STATE.currentUser && STATE.currentUser.role);
    const isAuthorized = currentRoleKey === 'admin' || currentRoleKey === 'director' || currentRoleKey === 'super_usuario' || (STATE.currentUser && STATE.currentUser.role === 'admin');
    if (!isAuthorized) {
        if (typeof showToast === 'function') {
            showToast('Solo el Super Administrador del Sistema puede guardar permisos.', 'warning');
        }
        return;
    }

    const keyInput = document.getElementById('roleModalKey') || document.getElementById('roleFormKey');
    const nameInput = document.getElementById('roleModalName') || document.getElementById('roleFormName');
    const descInput = document.getElementById('roleModalDescription') || document.getElementById('roleFormDescription');
    const colorInput = document.getElementById('roleModalColor') || document.getElementById('roleFormColor');

    const rolIdSeleccionado = keyInput ? keyInput.value.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_') : '';
    const key = rolIdSeleccionado;
    const name = nameInput ? nameInput.value.trim() : '';
    const desc = descInput ? descInput.value.trim() : '';
    const color = colorInput ? colorInput.value : '#0284c7';

    if (!rolIdSeleccionado || !name) {
        if (typeof showToast === 'function') {
            showToast('Ingrese la clave identificadora y el nombre del rol.', 'warning');
        }
        return;
    }

    // 1. Captura Dinámica de Checkboxes seleccionados (.chk-permiso:checked)
    const checkedNodes = document.querySelectorAll('.chk-permiso:checked, input[name="rolePermissionCheckbox"]:checked');
    const modulosSeleccionados = Array.from(new Set(Array.from(checkedNodes).map(cb => (cb.value || '').trim()))).filter(Boolean);
    const permissions = [...modulosSeleccionados];

    // Los roles admin, director y super_usuario SIEMPRE conservan todos los permisos del sistema
    if ((key === 'admin' || key === 'director' || key === 'super_usuario') && typeof SYSTEM_MODULES_LIST !== 'undefined' && permissions.length < SYSTEM_MODULES_LIST.length) {
        SYSTEM_MODULES_LIST.forEach(m => {
            if (!permissions.includes(m.key)) permissions.push(m.key);
        });
    }

    normalizeRolesConfig();

    // 2. Bloqueo visual con spinner y referencia a elementos
    const btnGuardar = document.getElementById('btnGuardarPermisos') || 
                       document.getElementById('roleSubmitBtn') || 
                       document.querySelector('#roleModal form button[type="submit"]') || 
                       document.querySelector('#roleModal button.btn-primary');
    const origBtnHtml = btnGuardar ? btnGuardar.innerHTML : '<i class="fa-solid fa-floppy-disk"></i> Guardar Configuración de Rol';
    
    if (btnGuardar) {
        btnGuardar.disabled = true;
        btnGuardar.classList.add('disabled');
        btnGuardar.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    try {
        const SYSTEM_ROLE_KEYS = (typeof window.SYSTEM_ROLE_KEYS !== 'undefined') 
            ? window.SYSTEM_ROLE_KEYS 
            : ['admin', 'director', 'secretaria', 'profesor_auxiliar', 'docente', 'estudiante'];
        const isSystemRole = (key === 'admin' || SYSTEM_ROLE_KEYS.includes(key));

        const existingIdx = STATE.rolesConfig.findIndex(r => r.key === key);
        let roleObj = null;

        const permissionLevels = {};
        if (typeof SYSTEM_MODULES_LIST !== 'undefined') {
            SYSTEM_MODULES_LIST.forEach(m => {
                if (permissions.includes(m.key)) {
                    permissionLevels[m.key] = 'edit';
                } else {
                    permissionLevels[m.key] = 'none';
                }
            });
        }

        if (existingIdx !== -1) {
            if (isSystemRole) {
                STATE.rolesConfig[existingIdx].isSystem = true;
                STATE.rolesConfig[existingIdx].permissions = permissions;
                STATE.rolesConfig[existingIdx].permissionLevels = permissionLevels;
                if (desc) STATE.rolesConfig[existingIdx].description = desc;
            } else {
                STATE.rolesConfig[existingIdx].name = name;
                STATE.rolesConfig[existingIdx].description = desc;
                STATE.rolesConfig[existingIdx].color = color;
                STATE.rolesConfig[existingIdx].permissions = permissions;
                STATE.rolesConfig[existingIdx].permissionLevels = permissionLevels;
            }
            roleObj = STATE.rolesConfig[existingIdx];
        } else {
            roleObj = {
                key: key,
                name: name,
                description: desc,
                color: color,
                isSystem: isSystemRole,
                permissions: permissions,
                permissionLevels: permissionLevels
            };
            STATE.rolesConfig.push(roleObj);
        }

        normalizeRolesConfig();

        const now = Date.now();
        const nowIso = new Date().toISOString();
        STATE.lastModified = now;
        STATE._lastSavedLocally = now;

        const roleAtomicPayload = {
            id: key,
            key: key,
            nombre: name,
            name: name,
            descripcion: desc,
            description: desc,
            color: color,
            permisos: permissions,
            permissions: permissions,
            permissionLevels: permissionLevels,
            isSystem: !!roleObj.isSystem,
            ultimaModificacion: nowIso,
            lastModified: now
        };

        // 🚀 RESPUESTA INSTANTÁNEA EN LA INTERFAZ (Actualización optimista a 0ms)
        STATE.lastModified = now;
        if (typeof saveStateToLocalStorage === 'function') saveStateToLocalStorage();

        if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
            try {
                _enccBroadcastChannel.postMessage({
                    type: 'SYNC_STATE_UPDATE',
                    state: STATE,
                    timestamp: now
                });
            } catch(bcErr) {}
        }

        if (typeof applyUserRole === 'function') applyUserRole(STATE.currentRole);
        if (typeof renderDynamicSidebarRBAC === 'function') renderDynamicSidebarRBAC(STATE.currentRole);
        if (window.EnccoAuthStore && typeof window.EnccoAuthStore.applyReactivePermissions === 'function') {
            window.EnccoAuthStore.applyReactivePermissions();
        }
        if (typeof renderRolesTable === 'function') renderRolesTable();
        if (typeof renderRolesManagementView === 'function') renderRolesManagementView();
        
        closeRoleModal();

        const msgSuccess = existingIdx !== -1 
            ? `Permisos del rol "${name}" guardados exitosamente.` 
            : `Rol "${name}" creado exitosamente.`;
        if (typeof showToast === 'function') {
            showToast(msgSuccess, "success");
        }

        // 🌟 Persistencia atómica directa y garantizada en Firestore y Realtime Database
        if (window.FirebaseModular && window.FirebaseModular.db) {
            const { db, doc, setDoc } = window.FirebaseModular;
            try {
                const rolRef = doc(db, "roles", rolIdSeleccionado);
                const roleDocRef = doc(db, "rolesConfig", rolIdSeleccionado);
                const configDocRef = doc(db, "config", "rolesConfig");

                const fsActions = [
                    setDoc(rolRef, {
                        id: key,
                        key: key,
                        nombre: name,
                        name: name,
                        descripcion: desc,
                        description: desc,
                        color: color,
                        permisos: permissions,
                        permissions: permissions,
                        ultimaModificacion: nowIso,
                        lastModified: now
                    }, { merge: true }),
                    setDoc(roleDocRef, roleAtomicPayload, { merge: true }),
                    setDoc(configDocRef, {
                        roles: STATE.rolesConfig,
                        list: STATE.rolesConfig,
                        lastModified: now,
                        ultimaModificacion: nowIso
                    }, { merge: true })
                ];

                (STATE.rolesConfig || []).forEach(r => {
                    if (r && r.key && r.key !== key) {
                        fsActions.push(setDoc(doc(db, "rolesConfig", r.key), r, { merge: true }));
                    }
                });

                await withTimeout(Promise.all(fsActions), 6000, 'Tiempo de espera agotado al conectar con Google Cloud Firestore.');
                console.log(`🔥 [Firestore] Rol "${name}" (${key}) persistido atómicamente con setDoc({ merge: true }).`);
            } catch(fsErr) {
                console.warn("Aviso al persistir rol en Firestore (continuando con RTDB):", fsErr);
            }
        }

        try {
            const rtdbPromises = [];
            if (typeof EnccoCloudSync !== 'undefined') {
                if (typeof EnccoCloudSync.patchNode === 'function') {
                    rtdbPromises.push(EnccoCloudSync.patchNode(`roles/${key}`, roleAtomicPayload));
                }
                if (typeof EnccoCloudSync.syncNode === 'function') {
                    rtdbPromises.push(EnccoCloudSync.syncNode('rolesConfig', STATE.rolesConfig));
                }
            }

            if (rtdbPromises.length > 0) {
                await withTimeout(Promise.all(rtdbPromises), 6000, 'Tiempo de espera en Realtime Database agotado.');
                console.log(`✅ [RTDB] Roles y permisos sincronizados exitosamente en Firebase.`);
            } else {
                const fUrl = (typeof getFirebaseDatabaseUrl === 'function') ? getFirebaseDatabaseUrl() : null;
                if (fUrl) {
                    const controller = new AbortController();
                    const fetchTimeout = setTimeout(() => controller.abort(), 5000);
                    try {
                        await fetch(`${fUrl}/encc_school_state/rolesConfig.json`, {
                            method: 'PUT',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify(STATE.rolesConfig),
                            signal: controller.signal
                        });
                        clearTimeout(fetchTimeout);
                    } catch(fetchErr) {
                        clearTimeout(fetchTimeout);
                    }
                }
            }
        } catch (rtdbErr) {
            console.warn("Aviso en Realtime Database al guardar rol:", rtdbErr);
        }
    } catch(err) {
        console.error("❌ [Firebase Error] Falló el guardado de rol:", err);
        if (typeof showToast === 'function') {
            showToast(`Error al guardar en Firebase: ${err.message || err}`, "danger");
        }
    } finally {
        // 🌟 7. Garantía Anti-Bloqueo Absoluta: restaurar botón siempre
        if (btnGuardar) {
            btnGuardar.disabled = false;
            btnGuardar.removeAttribute('disabled');
            btnGuardar.classList.remove('disabled');
            btnGuardar.innerHTML = origBtnHtml;
        }
    }
}
window.guardarPermisosRol = guardarPermisosRol;

async function saveRoleForm(e) {
    return await guardarPermisosRol(e);
}
window.saveRoleForm = saveRoleForm;

// Aliases oficiales para interoperabilidad y auditoría
window.mostrarNotificacion = function(msg, type = 'info') {
    if (typeof showToast === 'function') return showToast(msg, type);
    console.log(`[Notificación] (${type}): ${msg}`);
};
window.cerrarModalExistente = function(modalId = 'roleModal') {
    if (typeof closeRoleModal === 'function') {
        closeRoleModal();
    } else if (typeof closeModalProperly === 'function') {
        closeModalProperly(modalId);
    } else if (typeof hideModalById === 'function') {
        hideModalById(modalId);
    }
};
window.refrescarTablaRoles = function(filterVal = '') {
    if (typeof renderRolesTable === 'function') renderRolesTable(filterVal);
    if (typeof renderRolesManagementView === 'function') renderRolesManagementView();
};

function renderRolesTable(filterVal = '') {
    const tbody = document.getElementById('rolesTableBody') || document.querySelector('#view-roles tbody');
    if (!tbody) return;

    normalizeRolesConfig();

    const q = (filterVal || '').toLowerCase().trim();
    const list = (STATE.rolesConfig || []).filter(r => {
        if (!q) return true;
        return (r.name || '').toLowerCase().includes(q) || (r.key || '').toLowerCase().includes(q) || (r.description || '').toLowerCase().includes(q);
    });

    tbody.innerHTML = list.map((r, idx) => {
        const assignedUsers = (STATE.users || []).filter(u => u.role === r.key);
        const permCount = Array.isArray(r.permissions) ? r.permissions.length : 0;
        const totalModules = SYSTEM_MODULES_LIST.length;
        const SYSTEM_ROLE_KEYS = (typeof window.SYSTEM_ROLE_KEYS !== 'undefined') 
            ? window.SYSTEM_ROLE_KEYS 
            : ['admin', 'director', 'secretaria', 'profesor_auxiliar', 'docente', 'estudiante'];
        const isSystemRole = (r.isSystem || SYSTEM_ROLE_KEYS.includes(r.key));

        // Badges de permisos principales
        const permBadges = (r.permissions || []).slice(0, 5).map(pk => {
            const mod = SYSTEM_MODULES_LIST.find(m => m.key === pk);
            const label = mod ? mod.name.split(' ')[0] : pk;
            return `<span class="badge" style="background:#f1f5f9; color:#334155; border:1px solid #cbd5e1; font-size:0.70rem; padding:2px 5px; margin:1px;">${label}</span>`;
        }).join('');

        const moreBadge = permCount > 5 ? `<span class="badge" style="background:#e0f2fe; color:#0369a1; font-size:0.70rem; font-weight:700;">+${permCount - 5} más</span>` : '';

        return `
            <tr>
                <td>
                    <div style="display:flex; align-items:center; gap:8px;">
                        <span class="user-role-badge" style="background:${r.color || '#0284c7'}; color:#fff; font-weight:800; font-size:0.75rem; padding:3px 8px; border-radius:6px; text-transform:uppercase;">
                            ${r.name}
                        </span>
                        <code style="font-size:0.72rem; color:#64748b;">${r.key}</code>
                    </div>
                </td>
                <td style="font-size:0.84rem; color:#475569;">${r.description || 'Sin descripción'}</td>
                <td style="text-align:center;">
                    <div style="display:flex; flex-direction:column; align-items:center; gap:3px;">
                        <span class="badge ${permCount === totalModules ? 'badge-success' : 'badge-primary'}" style="font-weight:800; font-size:0.78rem;">
                            ${permCount} / ${totalModules} Módulos
                        </span>
                        <div style="display:flex; flex-wrap:wrap; justify-content:center; gap:2px; max-width:200px;">
                            ${permBadges} ${moreBadge}
                        </div>
                    </div>
                </td>
                <td style="text-align:center;">
                    <span class="badge badge-secondary" style="font-weight:700; font-size:0.80rem;">
                        <i class="fa-solid fa-users"></i> ${assignedUsers.length} Usuarios
                    </span>
                </td>
                <td style="text-align:center;">
                    <div style="display:inline-flex; gap:6px; flex-wrap:wrap; justify-content:center; align-items:center;">
                        <button type="button" class="btn btn-primary btn-xs" onclick="selectRoleAndScroll('${r.key}')" title="Configurar Matriz Detallada de Permisos (Modificar / Solo Ver / Bloquear)" style="font-weight:700; padding:5px 10px; display:inline-flex; align-items:center; gap:5px; background:#0284c7; border-color:#0284c7; color:#fff; border-radius:6px;">
                            <i class="fa-solid fa-sliders"></i> Permisos
                        </button>
                        ${(!isSystemRole && isDirectorOrSuperAdmin()) ? `
                        <button type="button" class="btn btn-outline-primary btn-xs" onclick="openRoleModal('${r.key}')" title="Editar Nombre, Descripción, Color y Módulos del Rol" style="font-weight:700; padding:5px 10px; display:inline-flex; align-items:center; gap:5px; border-radius:6px;">
                            <i class="fa-solid fa-pen-to-square"></i> Editar
                        </button>
                        <button type="button" class="btn btn-outline-danger btn-xs" onclick="deleteRole('${r.key}')" title="Eliminar Rol Personalizado" style="font-weight:700; padding:5px 10px; display:inline-flex; align-items:center; gap:5px; border-radius:6px; color:#dc2626; border-color:#fca5a5;">
                            <i class="fa-solid fa-trash-can"></i> Eliminar
                        </button>
                        ` : (!isSystemRole ? `
                        <span class="badge" style="background:#f8fafc; color:#64748b; border:1px solid #e2e8f0; font-size:0.75rem; padding:4px 8px; border-radius:6px;">
                            <i class="fa-solid fa-shield"></i> Personalizado
                        </span>
                        ` : `
                        <span class="badge" style="background:#f1f5f9; color:#64748b; border:1px solid #cbd5e1; font-size:0.75rem; padding:4px 8px; border-radius:6px;" title="Rol oficial permanente del sistema — solo se pueden configurar sus permisos">
                            <i class="fa-solid fa-lock"></i> Permanente
                        </span>
                        `)}</div>
                </td>
            </tr>
        `;
    }).join('');
}
window.renderRolesTable = renderRolesTable;

async function deleteRole(roleKey) {
    if (!isDirectorOrSuperAdmin()) {
        showToast('Acceso Restringido: Solo la Dirección General tiene autorización para eliminar roles.', 'warning');
        return;
    }

    const SYSTEM_ROLE_KEYS = (typeof window.SYSTEM_ROLE_KEYS !== 'undefined') 
        ? window.SYSTEM_ROLE_KEYS 
        : ['admin', 'director', 'secretaria', 'profesor_auxiliar', 'docente', 'estudiante'];

    if (SYSTEM_ROLE_KEYS.includes(roleKey)) {
        showToast('Los roles oficiales del sistema son permanentes y no pueden ser eliminados. Solo puede configurar sus permisos.', 'warning');
        return;
    }

    const roleObj = (STATE.rolesConfig || []).find(r => r.key === roleKey);
    if (roleObj && roleObj.isSystem) {
        showToast('Este rol del sistema está protegido contra eliminación.', 'warning');
        return;
    }

    const roleName = roleObj ? roleObj.name : roleKey;

    const assignedUsers = (STATE.users || []).filter(u => u.role === roleKey);
    if (assignedUsers.length > 0) {
        const confirmed = (window.EnccoDialog && typeof window.EnccoDialog.confirm === 'function')
            ? await window.EnccoDialog.confirm({
                title: 'Eliminar Rol con Usuarios Asignados',
                message: `El rol "${roleName}" (${roleKey}) tiene actualmente ${assignedUsers.length} usuario(s) asignado(s).\n\nSi continúa, el rol será eliminado y los usuarios asignados serán transferidos automáticamente al rol "docente".\n\n¿Desea eliminar el rol y reasignar los usuarios?`,
                type: 'warning',
                confirmText: 'Eliminar y Reasignar',
                cancelText: 'Cancelar'
            })
            : false;
        if (!confirmed) {
            return;
        }
        assignedUsers.forEach(u => {
            u.role = 'docente';
        });
    } else {
        const confirmed = (window.EnccoDialog && typeof window.EnccoDialog.confirm === 'function')
            ? await window.EnccoDialog.confirm({
                title: 'Eliminar Rol Institucional',
                message: `¿Está seguro de que desea eliminar permanentemente el rol "${roleName}" (${roleKey})?\n\nEsta acción no se puede deshacer.`,
                type: 'danger',
                confirmText: 'Eliminar Rol',
                cancelText: 'Cancelar'
            })
            : false;
        if (!confirmed) {
            return;
        }
    }

    STATE.rolesConfig = (STATE.rolesConfig || []).filter(r => r.key !== roleKey);
    normalizeRolesConfig();
    const nowTime = Date.now();
    STATE.lastModified = nowTime;
    saveStateToLocalStorage();

    try {
        if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
            _enccBroadcastChannel.postMessage({ type: 'SYNC_STATE_UPDATE', state: STATE, timestamp: nowTime });
        }
    } catch(e) {}

    if (typeof _selectedRoleKeyForEditing !== 'undefined' && _selectedRoleKeyForEditing === roleKey) {
        _selectedRoleKeyForEditing = (STATE.rolesConfig && STATE.rolesConfig[0]) ? STATE.rolesConfig[0].key : 'admin';
    }

    // 🚀 RESPUESTA INSTANTÁNEA EN LA INTERFAZ (Actualización optimista a 0ms)
    renderRoleSelectorTabs();
    loadRoleIntoPermissionsPanel((typeof _selectedRoleKeyForEditing !== 'undefined') ? _selectedRoleKeyForEditing : 'admin');
    renderRolesTable();
    if (typeof updateUserRoleSelectOptions === 'function') updateUserRoleSelectOptions();
    applyUserRole(STATE.currentRole);
    showToast(`El rol "${roleName}" ha sido eliminado exitosamente.`, 'info');

    // 🌟 Persistencia atómica en Firestore y RTDB en segundo plano
    (async () => {
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, deleteDoc, setDoc, writeBatch } = window.FirebaseModular;
                if (typeof deleteDoc === 'function') {
                    deleteDoc(doc(db, 'rolesConfig', roleKey)).catch(e => {});
                    deleteDoc(doc(db, 'roles', roleKey)).catch(e => {});
                }
                const configRef = doc(db, 'config', 'rolesConfig');
                if (typeof setDoc === 'function') {
                    setDoc(configRef, { list: STATE.rolesConfig, lastModified: nowTime }, { merge: true }).catch(e => {});
                }

                if (assignedUsers.length > 0) {
                    if (typeof writeBatch === 'function') {
                        const batch = writeBatch(db);
                        for (const u of assignedUsers) {
                            batch.set(doc(db, 'users', u.id), { role: 'docente', lastModified: nowTime }, { merge: true });
                        }
                        await batch.commit();
                    } else if (typeof setDoc === 'function') {
                        await Promise.all(assignedUsers.map(u => setDoc(doc(db, 'users', u.id), { role: 'docente', lastModified: nowTime }, { merge: true })));
                    }
                }
            } catch(e) {
                console.warn("Aviso al eliminar rol en Firestore:", e);
            }
        }

        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            try {
                EnccoCloudSync.syncNode('rolesConfig', STATE.rolesConfig);
                if (assignedUsers.length > 0) {
                    EnccoCloudSync.syncNode('users', STATE.users);
                }
            } catch(rtdbErr) {
                console.warn("Aviso al sincronizar roles en RTDB:", rtdbErr);
            }
        }
    })();
}
window.deleteRole = deleteRole;


