// ======================================================================
// ☁️ [v183] SINCRONIZADOR DIRECTO Y GRANULAR DE USUARIOS CON FIREBASE (0ms)
// ======================================================================
async function syncUsersToDatabaseImmediate(showToastNotification = true) {
    // ⚡ [v185] Bloquear SSE durante guardado de usuarios
    /* _isSavingLocally bloqueos desactivados */
    const firebaseUrl = getFirebaseDatabaseUrl();
    const now = Date.now();
    STATE.lastModified = now;
    if (typeof localStorage !== 'undefined') {
        try { localStorage.setItem('ENCCO_LAST_LOCAL_MODIFIED', String(now)); } catch(e) {}
    }
    
    // 1. Persistir inmediatamente en localStorage
    if (typeof saveStateToLocalStorage === 'function') {
        saveStateToLocalStorage();
    }

    if (!firebaseUrl || (typeof navigator !== 'undefined' && navigator.onLine === false)) {
        if (typeof updateDbSyncStatus === 'function') updateDbSyncStatus('synced');
        return true;
    }

    try {
        // 2. Subida directa, atómica y granular a /encc_school_state/users.json
        const cleanUsers = (STATE.users || []).map(u => ({
            id: u.id,
            name: u.name || '',
            username: u.username || '',
            email: u.email || '',
            telefono: u.telefono || '',
            password: u.password || 'C@rolina1',
            role: u.role || 'docente',
            title: u.title || '',
            renglon: u.renglon || '011',
            gender: u.gender || 'Masculino',
            active: u.active !== false,
            classes: u.classes || ''
        }));

        if (!Array.isArray(cleanUsers) || cleanUsers.length === 0) {
            console.warn(`🛡️ [Seguridad] syncUsersToDatabaseImmediate: Cantidad de usuarios sospechosamente baja (${cleanUsers ? cleanUsers.length : 0} < 20). Abortando subida a Firebase.`);
            return false;
        }

        const userEndpoint = `${firebaseUrl}/encc_school_state/users.json`;
        const timeEndpoint = `${firebaseUrl}/encc_school_state/lastModified.json`;

        const [userRes, timeRes] = await Promise.all([
            fetch(userEndpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(cleanUsers)
            }),
            fetch(timeEndpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(now)
            })
        ]);

        if (userRes.ok) {
            console.log("☁️ [Firebase] Colección de usuarios subida y sincronizada exitosamente en tiempo real (200 OK).");
            if (typeof updateDbSyncStatus === 'function') {
                updateDbSyncStatus('synced', '⚡ Tiempo Real: Sincronizado (0ms)');
            }
            if (showToastNotification && typeof showToast === 'function') {
                showToast("Cambios guardados y sincronizados en la Base de Datos en la nube.", "success");
            }
            // Notificar a otras pestañas
            if (typeof _enccBroadcastChannel !== 'undefined' && _enccBroadcastChannel) {
                try { _enccBroadcastChannel.postMessage({ type: 'USERS_UPDATED', users: cleanUsers, timestamp: now }); } catch(bcErr) {}
            }
            // Desactivar bandera de guardado local tras confirmación de usuarios
            setTimeout(() => {
                if (typeof _isSavingLocally !== "undefined") {
                    if (_isSavingLocallyTimeout) clearTimeout(_isSavingLocallyTimeout);
                    _isSavingLocallyTimeout = setTimeout(() => { _isSavingLocally = false; }, 3000);
                }
            }, 500);
            return true;
        } else {
            console.warn("⚠️ [Firebase] Aviso en PUT de usuarios status:", userRes.status);
            return false;
        }
    } catch(err) {
        console.warn("⚠️ [Firebase] Excepción al sincronizar usuarios con la nube:", err);
        return false;
    }
}
window.syncUsersToDatabaseImmediate = syncUsersToDatabaseImmediate;
async function saveUserForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();

    // Verificación de permisos administrativos (admin, director, secretaria)
    if (!isSuperUserRole() && !isDirectorRole() && typeof checkEnrolmentPermissions === 'function' && !checkEnrolmentPermissions()) {
        if (typeof showToast === 'function') showToast('Acceso denegado: Modificación de cuentas restringida a personal autorizado.', 'danger');
        return;
    }

    const idInput = document.getElementById('userFormId');
    const nameInput = document.getElementById('userFormName');
    const emailInput = document.getElementById('userFormEmail');
    const phoneInput = document.getElementById('userFormPhone');
    const passwordInput = document.getElementById('userFormPassword');
    const roleSelect = document.getElementById('userFormRole');
    const titleInput = document.getElementById('userFormTitle');
    const renglonSelect = document.getElementById('userFormRenglon');
    const genderSelect = document.getElementById('userFormGender');

    const userId = idInput ? idInput.value.trim() : '';
    const name = nameInput ? nameInput.value.trim() : '';
    const email = emailInput ? emailInput.value.trim() : '';
    const telefono = phoneInput ? phoneInput.value.trim() : '';
    const password = passwordInput ? passwordInput.value.trim() : 'C@rolina1';
    const role = roleSelect ? roleSelect.value : 'docente';
    const title = titleInput ? titleInput.value.trim() : 'PEM / Catedrático Titular';
    const renglon = renglonSelect ? renglonSelect.value : '011';
    const gender = genderSelect ? genderSelect.value : 'Masculino';

    const titleEl = document.getElementById('userModalTitle');
    const isEditing = Boolean(userId) || (titleEl && titleEl.textContent && titleEl.textContent.includes('Editar'));

    // 🚨 2. Verificación de Referencia e ID de Documento en Firebase
    if (isEditing) {
        if (!userId || userId === 'undefined' || userId === 'null') {
            console.error("Error: ID del usuario no encontrado o indefinido.");
            if (typeof Swal !== 'undefined' && Swal.fire) {
                Swal.fire({
                    icon: 'error',
                    title: 'ID no encontrado',
                    text: 'Error: ID del usuario no encontrado o indefinido.'
                });
            } else {
                showToast("Error: ID del usuario no encontrado o indefinido.", "danger");
            }
            return;
        }
    }

    if (!name) {
        if (typeof Swal !== 'undefined' && Swal.fire) {
            Swal.fire({
                icon: 'warning',
                title: 'Nombre Requerido',
                text: 'El nombre del usuario o docente es obligatorio.'
            });
        } else {
            showToast('El nombre del usuario o docente es obligatorio.', 'warning');
        }
        return;
    }

    if (!Array.isArray(STATE.users) || STATE.users.length === 0) {
        const initD = (typeof getInitialData === 'function') ? getInitialData() : {};
        STATE.users = (Array.isArray(initD.users) && initD.users.length >= 20) ? initD.users : [];
    }

    const submitBtn = document.getElementById('userFormSubmitBtn') || 
                      document.querySelector('#userModal form button[type="submit"]') || 
                      document.querySelector('#userModal button[onclick*="UserForm"]');
    const origBtnHtml = submitBtn ? (submitBtn.getAttribute('data-orig-html') || submitBtn.innerHTML) : '<i class="fa-solid fa-floppy-disk"></i> Guardar Usuario';
    if (submitBtn && !submitBtn.getAttribute('data-orig-html')) {
        submitBtn.setAttribute('data-orig-html', origBtnHtml);
    }

    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    try {
        let savedUserObj = null;

        if (userId) {
            // Edición de usuario existente
            const idx = STATE.users.findIndex(u => u.id === userId);
            if (idx !== -1) {
                const oldName = STATE.users[idx].name;
                STATE.users[idx].name = name;
                STATE.users[idx].email = email;
                STATE.users[idx].telefono = telefono;
                STATE.users[idx].password = password;
                STATE.users[idx].role = role;
                STATE.users[idx].title = title;
                STATE.users[idx].renglon = renglon;
                STATE.users[idx].gender = gender;
                savedUserObj = STATE.users[idx];

                // Cascada en cátedras
                (STATE.pensum || []).forEach(a => {
                    if (a.teacherId === userId || a.teacher === oldName) {
                        a.teacher = name;
                        a.teacherId = userId;
                    }
                });

                // Cascada en docentes guías
                (STATE.gradesList || []).forEach(g => {
                    if (g.guideTeacherId === userId || g.guideTeacher === oldName) {
                        g.guideTeacher = name;
                        g.guideTeacherId = userId;
                    }
                });
            } else {
                savedUserObj = {
                    id: userId,
                    name: name,
                    username: name.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 12) || 'user' + Date.now(),
                    email: email || `${name.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 12)}@comercio.edu.gt`,
                    telefono: telefono,
                    password: password,
                    role: role,
                    title: title,
                    renglon: renglon,
                    gender: gender,
                    active: true,
                    classes: ''
                };
                STATE.users.push(savedUserObj);
            }

            if (STATE.currentUser && (STATE.currentUser.id === userId || STATE.currentUser.id === savedUserObj.id)) {
                STATE.currentUser = { ...savedUserObj };
                STATE.currentRole = role;
                try {
                    sessionStorage.setItem('ENCCO_AUTH_USER', JSON.stringify(STATE.currentUser));
                    sessionStorage.setItem('ENCCO_AUTH_ROLE', role);
                    localStorage.removeItem('ENCCO_AUTH_USER');
                    localStorage.removeItem('ENCCO_AUTH_ROLE');
                } catch(err) {}
                if (typeof applyUserRole === 'function') applyUserRole(STATE.currentRole || "admin");
            }
        } else {
            // Creación de nuevo usuario
            const usernameBase = name.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 12) || 'user' + Date.now();
            savedUserObj = {
                id: 'usr-' + Date.now() + '-' + Math.floor(Math.random()*1000),
                name: name,
                username: usernameBase,
                email: email || `${usernameBase}@comercio.edu.gt`,
                telefono: telefono,
                password: password,
                role: role,
                title: title,
                renglon: renglon,
                gender: gender,
                active: true,
                classes: ''
            };
            STATE.users.push(savedUserObj);
        }

        if (typeof deduplicateUsersCollection === 'function') {
            STATE.users = deduplicateUsersCollection(STATE.users);
        }

        const nowTime = Date.now();
        STATE.lastModified = nowTime;
        saveStateToLocalStorage();

        // 🚀 RESPUESTA INSTANTÁNEA EN LA INTERFAZ (Actualización optimista a 0ms)
        closeUserModal();
        if (typeof renderUsersTable === 'function') renderUsersTable();
        if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
        if (typeof renderPensumCatalogTable === 'function') renderPensumCatalogTable();
        if (typeof renderTeacherGradeProgressTable === 'function') renderTeacherGradeProgressTable();
        if (typeof updateClassAssignmentSelects === 'function') updateClassAssignmentSelects();

        try {
            if (typeof synchronizeGlobalDynamicUI === 'function') synchronizeGlobalDynamicUI();
        } catch(uiErr) {}

        showToast(`Usuario "${name}" guardado exitosamente.`, "success");

        // 🌟 Persistencia atómica en Firestore con setDoc { merge: true } y RTDB en segundo plano
        (async () => {
            if (window.FirebaseModular && window.FirebaseModular.db) {
                try {
                    const { db, doc, setDoc, deleteDoc } = window.FirebaseModular;
                    const userDocRef = doc(db, 'users', savedUserObj.id);
                    const userPayload = { ...savedUserObj, lastModified: nowTime };

                    if (typeof setDoc === 'function') {
                        await withTimeout(setDoc(userDocRef, userPayload, { merge: true }), 8000, 'Tiempo de espera en Firestore agotado.');
                    }

                    if (savedUserObj.role === 'docente') {
                        const docDocRef = doc(db, 'docentes', savedUserObj.id);
                        if (typeof setDoc === 'function') {
                            await withTimeout(setDoc(docDocRef, userPayload, { merge: true }), 8000, 'Tiempo de espera al guardar docente en Firestore agotado.');
                        }
                    } else if (typeof deleteDoc === 'function' || (window.FirebaseModular && typeof window.FirebaseModular.deleteDoc === 'function')) {
                        const delFn = (typeof deleteDoc === 'function') ? deleteDoc : window.FirebaseModular.deleteDoc;
                        try {
                            await delFn(doc(db, 'docentes', savedUserObj.id));
                        } catch(delErr) {}
                    }
                } catch(fsErr) {
                    console.warn("Aviso al persistir usuario en Firestore (continuando con RTDB):", fsErr);
                }
            }

            if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
                try {
                    await withTimeout(EnccoCloudSync.syncNode('users', STATE.users), 8000, 'Tiempo de espera agotado en Firebase Realtime Database.');
                } catch(rtdbErr) {
                    console.warn("Aviso al sincronizar usuarios en RTDB:", rtdbErr);
                }
            } else if (typeof syncUsersToDatabaseImmediate === 'function') {
                try {
                    await withTimeout(syncUsersToDatabaseImmediate(false), 8000, 'Tiempo de espera agotado al sincronizar usuarios con Firebase.');
                } catch(rtdbErr) {
                    console.warn("Aviso al sincronizar usuarios con Firebase:", rtdbErr);
                }
            }
        })();
    } catch(err) {
        console.error("❌ Error al guardar usuario en Firebase:", err);
        const errMsg = err && err.message ? err.message : String(err);
        if (typeof Swal !== 'undefined' && Swal.fire) {
            Swal.fire({
                icon: 'error',
                title: 'Error al Guardar en Firebase',
                text: errMsg,
                confirmButtonColor: '#15803d'
            });
        } else {
            showToast(`Error al guardar en Firebase: ${errMsg}`, "danger");
        }
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html') || origBtnHtml || '<i class="fa-solid fa-floppy-disk"></i> Guardar Usuario';
        }
    }
}
window.saveUserForm = saveUserForm;


