function getAdditionalNomina2026Details(student, subjectName, bimestre) {
    if (!student || typeof OFFICIAL_NOMINAS_2026_ADDITIONAL_MAP === 'undefined') return null;
    const cleanStr = s => (s || '').toLowerCase()
        .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-z0-9]/g, '');

    let sId = student.id;
    if (!sId || !OFFICIAL_NOMINAS_2026_ADDITIONAL_MAP[sId]) {
        const pCode = student.personalCode;
        const carne = student.carne;
        const sNameClean = cleanStr(student.name);
        const match = (STATE.students || []).find(s => 
            (s.id && OFFICIAL_NOMINAS_2026_ADDITIONAL_MAP[s.id]) &&
            ((pCode && s.personalCode === pCode) ||
             (carne && s.carne === carne) ||
             (sNameClean && cleanStr(s.name) === sNameClean) ||
             (sNameClean && cleanStr((s.lastName || '') + (s.firstName || '')) === sNameClean))
        );
        if (match) sId = match.id;
    }

    if (!sId || !OFFICIAL_NOMINAS_2026_ADDITIONAL_MAP[sId]) return null;
    const record = OFFICIAL_NOMINAS_2026_ADDITIONAL_MAP[sId];

    let subData = record[subjectName];
    if (!subData) {
        const targetClean = cleanStr(subjectName);
        for (const k of Object.keys(record)) {
            const cK = cleanStr(k);
            if (cK === targetClean || (cK.length > 5 && (cK.includes(targetClean) || targetClean.includes(cK)))) {
                subData = record[k];
                break;
            }
        }
    }
    if (subData && subData[String(bimestre)]) {
        return subData[String(bimestre)];
    }
    return null;
}
