function resolveOfficialCanonicalSubject(rawName, gradeNum) {
    if (!rawName) return null;
    const cleanStr = s => (s || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, '');
    const cTarget = cleanStr(rawName);
    const candidates = OFFICIAL_CANONICAL_COURSES[gradeNum] || [];

    for (const c of candidates) {
        if (cleanStr(c.name) === cTarget) return c.name;
    }
    for (const c of candidates) {
        for (const al of c.aliases) {
            if (cleanStr(al) === cTarget) return c.name;
        }
    }
    for (const c of candidates) {
        if (cTarget.length >= 4 && (cleanStr(c.name).includes(cTarget) || cTarget.includes(cleanStr(c.name)))) {
            return c.name;
        }
        for (const al of c.aliases) {
            if (cTarget.length >= 4 && (cleanStr(al).includes(cTarget) || cTarget.includes(cleanStr(al)))) {
                return c.name;
            }
        }
    }
    return null;
}

function isLegacyPredefinedActivityName(name) {
    if (!name || typeof name !== 'string') return false;
    const clean = name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
    if (!clean) return false;
    // Solo encabezados estrictamente obsoletos del modelo antiguo de 2025:
    // Nunca incluir palabras comunes y legítimas como 'proyecto', 'clases', 'tarea', etc.
    return clean === 'folder capacitate' ||
           clean === 'folder' ||
           clean === 'pruebat' ||
           clean === 'aniversario encco' ||
           clean === 'aniversario' ||
           clean === 'aniv' ||
           clean === 'data king' ||
           clean === 'dtk' ||
           clean === 'examen zona';
}
window.isLegacyPredefinedActivityName = isLegacyPredefinedActivityName;

function stateHasGradesInActivity(st, pensumId, unitNum, actIdx) {
    const targetState = st || (typeof STATE !== 'undefined' ? STATE : null);
    if (!targetState || !Array.isArray(targetState.students)) return false;
    let targetSubj = null;
    if (pensumId && Array.isArray(targetState.pensum)) {
        const p = targetState.pensum.find(x => x.id === pensumId || x.pensumId === pensumId);
        if (p) targetSubj = p.subject;
    }
    const b = parseInt(unitNum) || 1;
    return targetState.students.some(s => {
        if (!s || !s.gradebookDetails) return false;
        if (targetSubj) {
            const u = s.gradebookDetails[targetSubj] && s.gradebookDetails[targetSubj][b];
            return u && Array.isArray(u.activities) && u.activities[actIdx] > 0;
        }
        return Object.values(s.gradebookDetails).some(bims => {
            const u = bims && bims[b];
            return u && Array.isArray(u.activities) && u.activities[actIdx] > 0;
        });
    });
}
window.stateHasGradesInActivity = stateHasGradesInActivity;

function sanitizeGradingConfigsInState(st) {
    if (!st || typeof st !== 'object') return;
    const sanitizeSingleConfig = (cfg, pensumId, unitNum) => {
        if (!cfg || typeof cfg !== 'object') return;
        // Si la configuración ya fue guardada/editada por el usuario o importada (tiene updatedAt o updatedBy), NUNCA sobrescribir nombres ni ponderaciones
        if (cfg.updatedAt || cfg.updatedBy) return;
        const acts = Array.isArray(cfg.activities)
            ? cfg.activities
            : (cfg.activities && typeof cfg.activities === 'object' ? Object.values(cfg.activities) : null);
        if (Array.isArray(acts)) {
            let hadLegacy = false;
            acts.forEach((act, idx) => {
                if (act && act.name && isLegacyPredefinedActivityName(act.name)) {
                    act.name = `Act. ${idx + 1}`;
                    const hasNotes = stateHasGradesInActivity(st, pensumId, unitNum, idx);
                    if (!hasNotes) {
                        act.max = 0;
                        act.maxPoints = 0;
                    }
                    hadLegacy = true;
                }
            });
            if (hadLegacy && cfg.zonaMax === 60 && cfg.examMax === 40) {
                cfg.zonaMax = 40;
                cfg.examMax = 60;
            }
        }
    };

    if (st.gradingConfigs && typeof st.gradingConfigs === 'object') {
        Object.keys(st.gradingConfigs).forEach(k => {
            const cfg = st.gradingConfigs[k];
            if (cfg && typeof cfg === 'object') {
                if (Array.isArray(cfg.activities)) {
                    // Extract pensumId and unit from key like 'pen-cnb-009_b3'
                    const parts = k.split('_');
                    const pensumId = parts[0];
                    const uNum = parts[1] ? parts[1].replace(/\D/g, '') : null;
                    sanitizeSingleConfig(cfg, pensumId, uNum);
                } else {
                    Object.keys(cfg).forEach(subK => {
                        if (cfg[subK] && typeof cfg[subK] === 'object' && Array.isArray(cfg[subK].activities)) {
                            const uNum = subK.replace(/\D/g, '');
                            sanitizeSingleConfig(cfg[subK], k, uNum);
                        }
                    });
                }
            }
        });
    }
    if (Array.isArray(st.pensum)) {
        st.pensum.forEach(p => {
            if (p && p.gradingConfig && typeof p.gradingConfig === 'object') {
                Object.keys(p.gradingConfig).forEach(bk => {
                    const uNum = bk.replace(/\D/g, '');
                    sanitizeSingleConfig(p.gradingConfig[bk], p.id, uNum);
                });
            }
        });
    }
}
window.sanitizeGradingConfigsInState = sanitizeGradingConfigsInState;

function normalizeSchoolAcademicData(targetState) {
    const sState = targetState || (typeof STATE !== 'undefined' ? STATE : null);
    if (!sState) return;

    let modified = false;

    // 0. Normalizar ponderaciones por defecto: Eliminar encabezados obsoletos (Folder, Pruebat, Clases, Proyecto, Aniversario)
    // Encabezados deben ser Act. 1 .. Act. 10 y tener valor 0, preservando al 100% las notas de los alumnos
    sanitizeGradingConfigsInState(sState);

    // 1. Normalizar asignaciones de cátedras en pensum
    (sState.pensum || []).forEach(p => {
        const rawGrade = `${p.grade || ''} ${p.gradeCode || ''}`.toUpperCase();
        let gradeNum = 4;
        if (rawGrade.includes('6') || rawGrade.includes('SEXTO')) gradeNum = 6;
        else if (rawGrade.includes('5') || rawGrade.includes('QUINTO')) gradeNum = 5;

        const canonical = resolveOfficialCanonicalSubject(p.subject, gradeNum);
        if (canonical && canonical !== p.subject) {
            p.subject = canonical;
            modified = true;
        }
    });

    // 2. Normalizar materias y notas de cada estudiante
    (sState.students || []).forEach(s => {
        const rawGrade = (s.grade || s.gradeLabel || s.gradeCode || '').toUpperCase();
        let gradeNum = 4;
        if (rawGrade.includes('6') || rawGrade.includes('SEXTO')) gradeNum = 6;
        else if (rawGrade.includes('5') || rawGrade.includes('QUINTO')) gradeNum = 5;

        const expectedCourses = OFFICIAL_CANONICAL_COURSES[gradeNum];
        if (!expectedCourses) return;

        const oldGrades = s.grades || {};
        const oldDetails = s.gradebookDetails || {};

        const cleanGrades = {};
        const cleanDetails = {};

        expectedCourses.forEach(c => {
            cleanGrades[c.name] = [0, 0, 0, 0];
            cleanDetails[c.name] = {};
        });

        // Migrar notas a nombres oficiales
        Object.keys(oldGrades).forEach(oldKey => {
            const canonical = resolveOfficialCanonicalSubject(oldKey, gradeNum);
            if (canonical && cleanGrades[canonical]) {
                const rawBGrades = Array.isArray(oldGrades[oldKey]) ? oldGrades[oldKey] : [0, 0, 0, 0];
                for (let b = 0; b < 4; b++) {
                    const sc = parseInt(rawBGrades[b]) || 0;
                    if (sc > cleanGrades[canonical][b]) {
                        cleanGrades[canonical][b] = sc;
                    }
                }
            }
        });

        // Migrar gradebookDetails a nombres oficiales
        Object.keys(oldDetails).forEach(oldKey => {
            const canonical = resolveOfficialCanonicalSubject(oldKey, gradeNum);
            if (canonical && cleanDetails[canonical]) {
                const bDetails = oldDetails[oldKey];
                if (bDetails && typeof bDetails === 'object') {
                    for (let b = 1; b <= 4; b++) {
                        const u = String(b);
                        if (bDetails[u]) {
                            if (!cleanDetails[canonical][u]) {
                                cleanDetails[canonical][u] = JSON.parse(JSON.stringify(bDetails[u]));
                            } else {
                                const oldTot = (parseInt(bDetails[u].zona) || 0) + (parseInt(bDetails[u].exam) || 0);
                                const curTot = (parseInt(cleanDetails[canonical][u].zona) || 0) + (parseInt(cleanDetails[canonical][u].exam) || 0);
                                if (oldTot > curTot) {
                                    cleanDetails[canonical][u] = JSON.parse(JSON.stringify(bDetails[u]));
                                }
                            }
                        }
                    }
                }
            }
        });

        s.grades = cleanGrades;
        s.gradebookDetails = cleanDetails;
    });

    return modified;
}
window.normalizeSchoolAcademicData = normalizeSchoolAcademicData;
window.resolveOfficialCanonicalSubject = resolveOfficialCanonicalSubject;

