function completeLoginWithRole(selectedRole, userObj = null) {
    if (typeof closeAllActiveModals === 'function') closeAllActiveModals();
    const user = userObj || STATE.pendingLoginUser || STATE.currentUser;
    if (!user) return;

    STATE.isLoggedIn = true;
    STATE.currentUser = user;
    STATE.currentRole = selectedRole;
    STATE.pendingLoginUser = null;

    // Restaurar visibilidad para futuros accesos
    const credsForm = document.getElementById('loginCredentialsForm');
    const choiceBox = document.getElementById('loginRoleChoiceBox');
    if (choiceBox) choiceBox.style.display = 'none';
    if (credsForm) credsForm.style.display = 'block';

    const gateAlert = document.getElementById('gateLoginAlert');
    if (gateAlert) gateAlert.style.display = 'none';

    const portal = document.getElementById('portalSection');
    if (portal) portal.style.display = 'none';

    const gate = document.getElementById('mandatoryLoginGate');
    if (gate) {
        gate.classList.remove('active');
        gate.style.display = 'none';
    }

    const appLayout = document.getElementById('appMainLayout');
    if (appLayout) appLayout.style.display = 'flex';

    const topBar = document.getElementById('topRoleBar');
    if (topBar) topBar.style.display = 'block';

    const roleTitleMap = { 
        admin: 'Super Administrador', 
        director: 'Dirección del Plantel', 
        secretaria: 'Secretaría Académica', 
        profesor_auxiliar: 'Profesor Auxiliar y Disciplinario',
        docente: 'Catedrático / Docente' 
    };
    const roleTitle = roleTitleMap[selectedRole] || (selectedRole === 'docente' ? 'Docente' : (user.title || user.role));
    
    const loggedDisplay = document.getElementById('loggedUserDisplay');
    if (loggedDisplay) loggedDisplay.textContent = `${user.name} (${roleTitle})`;

    switchRole(selectedRole);
    navigateTo('dashboard');

    showToast(`¡Bienvenido(a), ${user.name}! Acceso como ${roleTitle}.`, "success");
}



