function openGradebookAuditForTeacher(teacherId) {
    navigateTo('gradebook');
    setTimeout(() => {
        if (typeof renderDirectorTeacherAuditPanel === 'function') {
            renderDirectorTeacherAuditPanel();
        }
        const row = document.getElementById('teacherRow_' + teacherId);
        if (row) {
            row.scrollIntoView({ behavior: 'smooth', block: 'center' });
            row.style.background = '#fef08a';
            setTimeout(() => { row.style.background = ''; }, 2500);
        }
    }, 150);
}
window.openGradebookAuditForTeacher = openGradebookAuditForTeacher;

function openGradebookForCourse(courseId) {
    try {
        sessionStorage.setItem('ENCCO_SELECTED_GRADEBOOK_COURSE', courseId);
        localStorage.setItem('ENCCO_SELECTED_GRADEBOOK_COURSE', courseId);
        const p = (STATE.pensum || []).find(x => x.id === courseId);
        if (p && p.grade) {
            sessionStorage.setItem('ENCCO_SELECTED_GRADEBOOK_GRADE', p.grade);
            localStorage.setItem('ENCCO_SELECTED_GRADEBOOK_GRADE', p.grade);
            STATE.selectedGradebookGrade = p.grade;
        }
    } catch(e) {}
    STATE.selectedGradebookCourseId = courseId;
    navigateTo('gradebook');
    const select = document.getElementById('teacherCourseSelect');
    if (select) {
        select.value = courseId;
        loadTeacherGradebook();
    }
}

function openAttendanceForGrade(grade, section) {
    navigateTo('attendance');
    populateAttendanceSelects(false);
    const gradeSel = document.getElementById('attendanceGradeSelect');
    if (gradeSel) {
        const targetSec = getCleanSectionLetter(section);
        let targetNum = 0;
        const rawG = (grade || '').toUpperCase();
        if (rawG.includes('6') || rawG.includes('SEXTO') || rawG.includes('6TO')) targetNum = 6;
        else if (rawG.includes('5') || rawG.includes('QUINTO') || rawG.includes('5TO')) targetNum = 5;
        else if (rawG.includes('4') || rawG.includes('CUARTO') || rawG.includes('4TO')) targetNum = 4;

        for (let i = 0; i < gradeSel.options.length; i++) {
            const opt = gradeSel.options[i];
            const optVal = opt.value || '';
            const optText = opt.text || '';
            const optSec = getCleanSectionLetter(optText || optVal);
            const optNum = (optText + ' ' + optVal).includes('6') ? 6 : ((optText + ' ' + optVal).includes('5') ? 5 : ((optText + ' ' + optVal).includes('4') ? 4 : 0));

            if (optVal === grade || (optText.includes(grade) && optText.includes(section)) || (targetNum > 0 && targetNum === optNum && targetSec && targetSec === optSec)) {
                gradeSel.selectedIndex = i;
                break;
            }
        }
        onAttendanceGradeChange();
        loadAttendanceList();
    }
}

let _currentPrintCourseId = null;
let _currentPrintCourseMeta = null;

function openCoursePrintModal(courseId, grade = '', section = '', subject = '') {
    let targetCourse = (STATE.pensum || []).find(p => p.id === courseId);
    if (!targetCourse && (grade || subject)) {
        targetCourse = (STATE.pensum || []).find(p => {
            const matchGrade = (p.grade === grade || (p.gradeCode && p.gradeCode.includes(grade)));
            const matchSec = (!section || p.section === section);
            const matchSub = (!subject || p.subject === subject || p.name === subject);
            return matchGrade && matchSec && matchSub;
        });
    }

    _currentPrintCourseId = targetCourse ? targetCourse.id : courseId;

    const subName = targetCourse ? targetCourse.subject : (subject || 'Cátedra');
    const gName = targetCourse ? targetCourse.grade : (grade || 'Grado');
    const rawSec = targetCourse ? (targetCourse.section || section) : (section || 'A');
    const secClean = (rawSec || '').toLowerCase().startsWith('secci') ? rawSec : `Sección ${rawSec || 'A'}`;
    const tName = targetCourse ? (targetCourse.teacher || (STATE.currentUser ? STATE.currentUser.name : 'Catedrático')) : (STATE.currentUser ? STATE.currentUser.name : 'Catedrático');
    const stCount = getStudentCountByGradeAndSection(gName, gName, rawSec);

    _currentPrintCourseMeta = {
        courseId: _currentPrintCourseId,
        grade: gName,
        section: rawSec,
        subject: subName,
        teacher: tName,
        targetCourse: targetCourse
    };

    const subEl = document.getElementById('coursePrintSubjectName');
    const metaEl = document.getElementById('coursePrintMetaInfo');
    const countEl = document.getElementById('coursePrintStudentCount');
    const bimSelect = document.getElementById('coursePrintBimestreSelect');
    const monthSelect = document.getElementById('coursePrintMonthSelect');

    if (subEl) subEl.textContent = subName;
    if (metaEl) metaEl.innerHTML = `<i class="fa-solid fa-graduation-cap"></i> ${gName} — ${secClean} &nbsp;|&nbsp; <i class="fa-solid fa-chalkboard-user"></i> Catedrático: <strong>${tName}</strong>`;
    if (countEl) countEl.innerHTML = `<i class="fa-solid fa-users"></i> ${stCount} Estudiantes`;
    if (bimSelect) {
        const activeGradebookBim = document.getElementById('gradebookBimestreSelect')?.value;
        const defaultBim = activeGradebookBim || (STATE.config?.activeBimestre ? String(STATE.config.activeBimestre) : '1');
        bimSelect.value = defaultBim.toString();
    }
    if (monthSelect) {
        const currMonth = new Date().getMonth() + 1;
        monthSelect.value = String(currMonth);
    }

    showModalById('coursePrintModal');
}
