function renderStudentProfileGrades(student) {
    const tbody = document.getElementById('profGradesTableBody');
    const summaryBox = document.getElementById('profGradesSummaryBox');
    if (!tbody) return;

    const gradeObj = (STATE.gradesList || []).find(g => 
        (g.code && g.code === student.grade) ||
        (g.name === student.grade && (!student.section || g.section === student.section)) ||
        (g.code && student.gradeCode && g.code === student.gradeCode) ||
        ((g.name + ' - ' + g.section) === student.grade)
    );
    const pensumCourses = (STATE.pensum || []).filter(p => 
        p.gradeCode === student.grade || 
        (student.gradeCode && p.gradeCode === student.gradeCode) ||
        (gradeObj && p.grade === gradeObj.name && p.section === gradeObj.section) ||
        (p.grade === student.grade && (!student.section || p.section === student.section))
    );
    
    // Obtener todas las materias configuradas
    let subjects = pensumCourses.length > 0 ? pensumCourses.map(p => p.subject) : (Object.keys(student.grades || {}));
    subjects = [...new Set(subjects)];

    if (subjects.length === 0) {
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding:25px; color:var(--text-muted);">No hay asignaturas registradas para este grado y sección en el pensum.</td></tr>`;
        if (summaryBox) summaryBox.innerHTML = '<span>Sin calificaciones registradas.</span>';
        return;
    }

    let totalAvgSum = 0;
    let subjectCount = 0;
    let passedCount = 0;
    let failedCount = 0;

    tbody.innerHTML = subjects.map(sub => {
        const gradesObj = (typeof getReportCardSubjectGrades === 'function') 
            ? getReportCardSubjectGrades(student, sub) 
            : null;

        const isSpecial = gradesObj ? gradesObj.isSpecialUnique : (typeof isMateriaEspecialGraduacion === 'function' && isMateriaEspecialGraduacion(sub));
        const rawGradeStr = (student.grade || student.gradeLabel || student.gradeCode || '').toUpperCase();
        const is6to = rawGradeStr.includes('6') || rawGradeStr.includes('SEXTO') || rawGradeStr.includes('6TO');

        const g1 = gradesObj ? gradesObj.b1 : ((student.grades && student.grades[sub]) ? student.grades[sub][0] || 0 : 0);
        const g2 = gradesObj ? gradesObj.b2 : ((student.grades && student.grades[sub]) ? student.grades[sub][1] || 0 : 0);
        const g3 = gradesObj ? gradesObj.b3 : ((student.grades && student.grades[sub]) ? student.grades[sub][2] || 0 : 0);
        const g4 = gradesObj ? gradesObj.b4 : ((student.grades && student.grades[sub]) ? student.grades[sub][3] || 0 : 0);

        const isExon1 = gradesObj ? gradesObj.isExon1 : ((typeof isSubjectBimestreExonerated === 'function') ? isSubjectBimestreExonerated(student, sub, 1) : false);
        const isExon2 = gradesObj ? gradesObj.isExon2 : ((typeof isSubjectBimestreExonerated === 'function') ? isSubjectBimestreExonerated(student, sub, 2) : false);
        const isExon3 = gradesObj ? gradesObj.isExon3 : ((typeof isSubjectBimestreExonerated === 'function') ? isSubjectBimestreExonerated(student, sub, 3) : false);
        const isExon4 = gradesObj ? gradesObj.isExon4 : ((typeof isSubjectBimestreExonerated === 'function') ? isSubjectBimestreExonerated(student, sub, 4) : false);

        const isFullyExon = gradesObj ? gradesObj.isFullyExon : (isExon1 && isExon2 && isExon3 && isExon4);
        const finalAvg = gradesObj ? gradesObj.avg : (isSpecial ? g4 : 0);

        if (finalAvg > 0) {
            totalAvgSum += finalAvg;
            subjectCount++;
            if (finalAvg >= 60) passedCount++;
            else failedCount++;
        }

        const isFail = (finalAvg > 0 && finalAvg < 60);

        const formatGradeCell = (val, isExon, isSpecialUnset) => {
            if (isSpecialUnset) {
                return '<span style="color:#94a3b8;">—</span>';
            }
            if (isExon) {
                return '<span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; font-size:0.75rem; padding:2px 6px; border-radius:4px;" title="Materia Exonerada en este bimestre"><i class="fa-solid fa-shield-check"></i> Exon.</span>';
            }
            return val > 0 ? val : '<span style="color:#94a3b8;">—</span>';
        };

        let statusBadge = '';
        if (isFullyExon) {
            statusBadge = `<span class="badge" style="font-size:0.78rem; background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd;"><i class="fa-solid fa-shield-check"></i> Exonerada</span>`;
        } else if (finalAvg >= 60) {
            statusBadge = `<span class="badge badge-success" style="font-size:0.78rem;">Aprobada</span>`;
        } else if (finalAvg > 0) {
            statusBadge = `<span class="badge badge-danger" style="font-size:0.78rem;">Reprobada</span>`;
        } else {
            statusBadge = `<span class="badge badge-secondary" style="font-size:0.78rem;">Pendiente</span>`;
        }

        const avgTitle = isSpecial 
            ? 'Nota única total de 4to Bimestre (Sin promedio)' 
            : (is6to ? 'Promedio sobre 3 unidades (tomando en cuenta exoneraciones)' : 'Promedio sobre 4 unidades (tomando en cuenta exoneraciones)');

        return `
            <tr>
                <td style="font-weight:700; text-align:left; padding:8px 12px; color:#1e293b;">
                    ${escapeHtml(sub)}
                    ${isSpecial ? ' <span class="badge" style="font-size:0.7rem; background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; margin-left:4px;">Nota Única B4</span>' : ''}
                </td>
                <td style="text-align:center; font-weight:600;">${formatGradeCell(g1, isExon1, isSpecial)}</td>
                <td style="text-align:center; font-weight:600;">${formatGradeCell(g2, isExon2, isSpecial)}</td>
                <td style="text-align:center; font-weight:600;">${formatGradeCell(g3, isExon3, isSpecial)}</td>
                <td style="text-align:center; font-weight:600;">${formatGradeCell(g4, isExon4, false)}</td>
                <td style="text-align:center; font-weight:800; font-size:0.95rem; ${isFail ? 'color:#b91c1c; background:#fee2e2;' : (finalAvg >= 60 ? 'color:#15803d; background:#dcfce7;' : (isFullyExon ? 'color:#0369a1; background:#f0f9ff;' : 'color:#0369a1;'))}" title="${avgTitle}">${finalAvg > 0 ? finalAvg : (isFullyExon ? 'Exon.' : '—')}</td>
                <td style="text-align:center;">
                    ${statusBadge}
                </td>
            </tr>
        `;
    }).join('');

    const generalAverage = subjectCount > 0 ? Math.round(totalAvgSum / subjectCount) : 0;
    if (summaryBox) {
        summaryBox.innerHTML = `
            <div>
                <strong>Promedio General Acumulado:</strong> 
                <span class="badge ${generalAverage >= 60 ? 'badge-success' : 'badge-warning'}" style="font-size:1rem; font-weight:800; padding:4px 12px; margin-left:6px;">
                    ${generalAverage} pts
                </span>
            </div>
            <div style="display:flex; gap:12px; font-weight:700;">
                <span style="color:#15803d;"><i class="fa-solid fa-circle-check"></i> ${passedCount} Aprobadas</span>
                <span style="color:#b91c1c;"><i class="fa-solid fa-circle-xmark"></i> ${failedCount} Reprobadas</span>
                <span style="color:#0369a1;"><i class="fa-solid fa-book"></i> ${subjects.length} Total Materias</span>
            </div>
        `;
    }
}

function printStudentReportCardFromProfile(studentId) {
    if (!hasRolePermission('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol actual no tiene autorización para acceder al Boletín de Calificaciones.", "warning");
        return;
    }
    if (!canRoleModify('reports', STATE.currentRole)) {
        showToast("Acceso Restringido: Su rol tiene permiso de solo consulta para el Boletín de Calificaciones.", "info");
        return;
    }

    if (!studentId) studentId = STATE.selectedStudentId;
    const s = (STATE.students || []).find(x => x.id === studentId);
    if (!s) {
        showToast("Estudiante no encontrado para imprimir boletín.", "warning");
        return;
    }

    // 🛡️ REGLA ESTRICTA INSTITUCIONAL: Para docentes, restringir estrictamente a estudiantes asignados
    if (STATE.currentRole === 'docente' && typeof isStudentAssignedToTeacher === 'function' && !isStudentAssignedToTeacher(s, STATE.currentUser)) {
        showToast("Acceso denegado: No puede imprimir el boletín de un estudiante no asignado a sus cátedras.", "error");
        return;
    }

    // 🛡️ REGLA INSTITUCIONAL: A los alumnos marcados como retirados NO se les imprimen tarjetas / boletines
    if (s.status === 'Retirado' || s.status === 'Inactivo') {
        showToast(`No se pueden imprimir tarjetas/boletines para estudiantes con estado "${s.status}".`, "warning");
        return;
    }

    const select = document.getElementById('reportStudentSelect');
    if (select) {
        select.value = studentId;
    }
    printStudentReportCardOfficial();
}



function toggleInactivationFields(val) {
    const box = document.getElementById('inactivationBox');
    if (!box) return;

    if (val === 'Retirado' || val === 'Ausente' || val === 'Inactivo') {
        box.style.display = 'block';
        const titleEl = document.getElementById('inactivationBoxTitle');
        const reasonLbl = document.getElementById('profRetireReasonLabel');
        const reasonInput = document.getElementById('profRetireReason');
        const extraRow = document.getElementById('retireExtraFieldsRow');

        if (val === 'Retirado') {
            if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-user-slash"></i> Registro de Retiro Formal de Expediente';
            if (reasonLbl) reasonLbl.textContent = 'Motivo del Retiro de Expediente (Obligatorio para Secretaría) *';
            if (reasonInput) reasonInput.placeholder = 'Ej: Traslado de domicilio familiar a la capital / Cambio de centro educativo';
            if (extraRow) extraRow.style.display = 'flex';
        } else if (val === 'Ausente') {
            if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-user-xmark"></i> Registro de Deserción o Inasistencia Prolongada (Ausente)';
            if (reasonLbl) reasonLbl.textContent = 'Motivo / Causa de la Ausencia o Deserción (Obligatorio para Secretaría) *';
            if (reasonInput) reasonInput.placeholder = 'Ej: Inasistencia injustificada mayor a 15 días hábiles / Deserción laboral';
            if (extraRow) extraRow.style.display = 'flex';
        }
    } else {
        box.style.display = 'none';
    }
}

function handlePhotoUpload(e) {
    const file = e.target.files[0];
    if (file) {
        if (typeof window.processImageFileToCarnetFormat === 'function') {
            showToast("Ajustando fotografía a la formalidad del carné...", "info");
            window.processImageFileToCarnetFormat(file)
                .then(dataUrl => {
                    document.getElementById('profilePhotoImg').src = dataUrl;
                    showToast("Fotografía del perfil formalmente ajustada.", "success");
                })
                .catch(err => {
                    console.warn("Fallo en optimización formal, aplicando directa:", err);
                    const reader = new FileReader();
                    reader.onload = function(evt) {
                        document.getElementById('profilePhotoImg').src = evt.target.result;
                    };
                    reader.readAsDataURL(file);
                });
        } else {
            const reader = new FileReader();
            reader.onload = function(evt) {
                document.getElementById('profilePhotoImg').src = evt.target.result;
            };
            reader.readAsDataURL(file);
        }
    }
}

async function saveStudentProfileForm(e) {
    if (e) {
        if (e._enccoHandled) return;
        e._enccoHandled = true;
        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();
    }
    if (!checkEnrolmentPermissions()) return;

    const student = (STATE.students || []).find(s => 
        s && (
            String(s.id) === String(STATE.selectedStudentId) || 
            (s.carne && s.carne === STATE.selectedStudentId) ||
            (s.personalCode && s.personalCode === STATE.selectedStudentId)
        )
    );
    if (!student || !student.id) {
        console.error("Error: ID del estudiante no identificado.");
        showToast("No se pudo identificar al estudiante seleccionado.", "danger");
        return;
    }

    const newStatus = document.getElementById('profStatusSelect')?.value || 'Activo';
    const reason = (document.getElementById('profRetireReason')?.value || '').trim();

    if (newStatus === 'Retirado' || newStatus === 'Ausente' || newStatus === 'Inactivo') {
        if (!reason) {
            showToast("Secretaría debe ingresar obligatoriamente el motivo del retiro o ausencia del estudiante.", "warning");
            document.getElementById('profRetireReason')?.focus();
            return;
        }
    }

    const submitBtn = document.querySelector('#studentProfileModal form button[type="submit"]') || document.querySelector('#studentProfileModal button.btn-primary');
    const origBtnHtml = submitBtn ? (submitBtn.getAttribute('data-orig-html') || submitBtn.innerHTML) : 'Guardar Información';
    if (submitBtn && !submitBtn.getAttribute('data-orig-html')) {
        submitBtn.setAttribute('data-orig-html', origBtnHtml);
    }
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    const pPhoto = document.getElementById('profilePhotoImg')?.src;
    if (pPhoto && !pPhoto.includes('ui-avatars.com')) {
        student.photo = pPhoto;
        student.photoUrl = pPhoto;
    }
    student.status = newStatus;

    const profGradeEl = document.getElementById('profGradeSelect');
    if (profGradeEl && profGradeEl.value) {
        const rawVal = profGradeEl.value.trim();
        const selOpt = profGradeEl.selectedOptions?.[0] || Array.from(profGradeEl.options || []).find(o => o.value === rawVal);
        let pGrade = '';
        let pSection = '';
        let pCode = '';

        if (selOpt && selOpt.dataset && (selOpt.dataset.grade || selOpt.dataset.section)) {
            pGrade = selOpt.dataset.grade || '';
            pSection = selOpt.dataset.section || '';
            pCode = selOpt.dataset.code || '';
        }

        if (!pGrade || !pSection) {
            if (rawVal.includes(' - ')) {
                const parts = rawVal.split(' - ');
                pGrade = parts[0].trim();
                pSection = parts.slice(1).join(' - ').trim();
            } else {
                pGrade = rawVal;
            }
        }

        const secLetter = typeof getCleanSectionLetter === 'function' ? getCleanSectionLetter(pSection || rawVal) : '';
        if (secLetter) {
            pSection = `Sección ${secLetter}`;
        }

        const matchedGrade = (STATE.gradesList || []).find(g => 
            (pCode && g.code === pCode) ||
            (`${g.name} - ${g.section}` === rawVal) ||
            (g.name === pGrade && (g.section === pSection || (typeof getCleanSectionLetter === 'function' && getCleanSectionLetter(g.section) === secLetter)))
        );

        if (matchedGrade) {
            pGrade = matchedGrade.name;
            pSection = matchedGrade.section;
            pCode = matchedGrade.code;
        }

        const cleanAssign = (typeof getStudentAssignment === 'function')
            ? getStudentAssignment({ grade: pGrade, section: pSection, gradeCode: pCode })
            : { grade: pGrade, section: pSection, gradeCode: pCode, fullLabel: `${pGrade} (${pSection})` };

        student.grade = cleanAssign.grade || pGrade;
        student.section = cleanAssign.section || pSection;
        student.gradeCode = cleanAssign.gradeCode || pCode || matchedGrade?.code || `${student.grade.split(' ')[0]} ${secLetter || 'A'}`;
        student.gradeLabel = cleanAssign.fullLabel || `${student.grade} (${student.section})`;
        student.career = matchedGrade?.career || student.career || 'Perito Contador';
    }
    student.address = document.getElementById('profAddressDisplay')?.value || '';
    student.phone = document.getElementById('profPhone')?.value || '';
    student.email = document.getElementById('profEmail')?.value || '';

    if (newStatus !== 'Activo') {
        student.retireReason = reason;
        student.retireRecipient = (document.getElementById('profRetireRecipient')?.value || '').trim();
        student.retireDate = document.getElementById('profRetireDate')?.value || new Date().toISOString().slice(0, 10);
    } else {
        student.retireReason = '';
        student.retireRecipient = '';
        student.retireDate = '';
    }

    try {
        student.editedByAuthority = true;
        student.lastModifiedByRole = STATE.currentRole || 'Secretaría';
        student.lastModifiedBy = (STATE.currentUser && (STATE.currentUser.name || STATE.currentUser.username)) || STATE.currentRole || 'Secretaría';
        student.active = (newStatus === 'Activo');
        student.lastModified = Date.now();
        // 🌟 A. Persistencia Atómica en Firestore (colección students con merge: true y sanitización anti-undefined)
        const modular = window.FirebaseModular;
        if (modular && modular.db && typeof modular.doc === 'function' && typeof modular.setDoc === 'function') {
            try {
                const { db, doc, setDoc } = modular;
                const stuRef = doc(db, 'students', student.id);
                const cleanStudent = (typeof sanitizePayloadForFirestore === 'function') 
                    ? sanitizePayloadForFirestore(student) 
                    : student;
                await withTimeout(setDoc(stuRef, cleanStudent, { merge: true }), 8000, 'Tiempo de espera en Firestore agotado.');
            } catch(fsErr) {
                console.warn("Aviso al guardar estudiante en Firestore:", fsErr);
            }
        }

        // 🌟 B. Sincronización atómica aislada en RTDB (SÓLO nodo 'students')
        let ok = false;
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            ok = await withTimeout(EnccoCloudSync.syncNode('students', STATE.students), 8000, 'Tiempo de espera en Realtime Database agotado.');
        } else {
            ok = true;
        }

        if (!ok) throw new Error("Firebase no confirmó la actualización del expediente del estudiante.");

        saveStateToLocalStorage();
        closeStudentProfileModal();
        if (typeof setStudentFiltersToMatch === 'function' && student.grade && student.section) {
            setStudentFiltersToMatch(student.grade, student.section, student.gradeCode);
        } else if (typeof renderStudentsTable === 'function') {
            renderStudentsTable();
        }
        showToast(`Expediente de ${formatStudentDisplayName(student, 'lastFirst')} actualizado y reasignado a ${student.grade} (${student.section}).`, "success");
    } catch(err) {
        console.error("❌ Error al guardar perfil del estudiante en Firebase:", err);
        showToast(`Error al guardar en Firebase: ${err.message || err}`, "danger");
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html') || origBtnHtml;
        }
    }
}

function closeStudentProfileModal() {
    const modal = document.getElementById('studentProfileModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

