function exportDataBackupJSON() {
    if (typeof canAccessBackupAndAudit === 'function' && !canAccessBackupAndAudit()) {
        if (typeof showToast === 'function') {
            showToast("Acceso denegado: Esta función está reservada para Dirección, Secretaría o Superusuario.", "warning");
        }
        return;
    }
    if (typeof exportSystemSafeBackup === 'function') {
        exportSystemSafeBackup('all');
    } else {
        const jsonStr = JSON.stringify(STATE, null, 2);
        const blob = new Blob([jsonStr], { type: 'application/json;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `ENCCO_Respaldo_BaseDatos_${new Date().toISOString().slice(0,10)}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        showToast("¡Copia de seguridad JSON descargada con éxito!", "success");
    }
}
window.exportDataBackupJSON = exportDataBackupJSON;

async function importDataBackupJSON(e) {
    if (typeof canAccessBackupAndAudit === 'function' && !canAccessBackupAndAudit()) {
        if (typeof showToast === 'function') {
            showToast("Acceso denegado: La restauración de respaldos está restringida a Dirección, Secretaría o Superusuario.", "error");
        }
        if (e && e.target) e.target.value = '';
        return;
    }
    const file = e.target.files[0];
    if (!file) return;

    const confirmed = (window.EnccoDialog && typeof window.EnccoDialog.confirm === 'function')
        ? await window.EnccoDialog.confirm({
            title: 'Restaurar Copia de Seguridad',
            message: '¿Está seguro de que desea restaurar los datos desde este archivo de respaldo?\n\nEsta acción integrará los registros de estudiantes, notas y configuraciones del respaldo.',
            type: 'warning',
            confirmText: 'Restaurar Respaldo',
            cancelText: 'Cancelar'
        })
        : true;

    if (!confirmed) {
        e.target.value = '';
        return;
    }

    const reader = new FileReader();
    reader.onload = function(evt) {
        try {
            const rawData = JSON.parse(evt.target.result);
            const data = rawData.stateSnapshot ? rawData.stateSnapshot : rawData;

            if (data.users || data.students || data.gradesList) {
                if (Array.isArray(data.users) && data.users.length >= 20) {
                    STATE.users = data.users;
                } else if (Array.isArray(data.users) && data.users.length > 0) {
                    console.warn("🛡️ [Seguridad] Respaldo JSON contiene menos de 20 usuarios. Se conserva la lista de usuarios existente.");
                }
                STATE.careers = data.careers || STATE.careers;
                STATE.cycles = data.cycles || STATE.cycles || [];
                STATE.activeCycle = data.activeCycle || STATE.activeCycle || '';
                if (Array.isArray(data.gradesList) && data.gradesList.length >= 12) {
                    STATE.gradesList = data.gradesList;
                } else if (Array.isArray(data.gradesList) && data.gradesList.length > 0) {
                    console.warn("🛡️ [Seguridad] Respaldo JSON contiene catálogo de secciones truncado. Se conservan las 12 secciones oficiales.");
                }
                STATE.pensumCatalog = data.pensumCatalog || STATE.pensumCatalog;
                if (Array.isArray(data.students) && data.students.length >= 350) {
                    STATE.students = (typeof deduplicateStudentsCollection === 'function') ? deduplicateStudentsCollection(data.students) : data.students;
                } else if (Array.isArray(data.students) && data.students.length > 0) {
                    console.warn("🛡️ [Seguridad] Respaldo JSON contiene menos de 350 estudiantes. Se conserva el padrón existente.");
                }
                if (Array.isArray(data.pensum) && data.pensum.length >= 28) {
                    STATE.pensum = data.pensum;
                } else if (Array.isArray(data.pensum) && data.pensum.length > 0) {
                    console.warn("🛡️ [Seguridad] Respaldo JSON contiene pensum truncado. Se conserva la asignación existente.");
                }
                STATE.announcements = data.announcements || STATE.announcements;
                STATE.disciplineReports = data.disciplineReports || STATE.disciplineReports;
                STATE.attendanceRecords = data.attendanceRecords || STATE.attendanceRecords || {};
                STATE.rolesConfig = data.rolesConfig || STATE.rolesConfig;
                STATE.studentPermissions = data.studentPermissions || STATE.studentPermissions || [];
                STATE.auxiliaturaLog = data.auxiliaturaLog || STATE.auxiliaturaLog || [];
                STATE.exoneraciones = data.exoneraciones || STATE.exoneraciones || [];
                STATE.examSchedules = data.examSchedules || STATE.examSchedules || {};

                if (Array.isArray(data.auditLog) && data.auditLog.length > 0) {
                    STATE.auditLog = [...(data.auditLog || []), ...(STATE.auditLog || [])].slice(0, 2000);
                }

                if (typeof recordAuditLog === 'function') {
                    recordAuditLog('BACKUP_RESTORE', 'Sistema', `Restauración de respaldo ejecutada. Padrón cargado: ${(STATE.students || []).length} estudiantes.`);
                }

                saveStateToLocalStorage();
                updateCycleSelects();
                updateCareerSelects();
                updateGradeSelects();
                renderCurrentView();

                if (typeof closeUniversalBackupModal === 'function') {
                    closeUniversalBackupModal();
                }

                showToast(`¡Base de datos restaurada correctamente! Se cargaron ${(STATE.students || []).length} estudiantes.`, "success", 6000);
            } else {
                showToast("El archivo JSON no tiene el formato de respaldo válido de ENCCO.", "danger");
            }
        } catch (err) {
            console.error("Error al importar respaldo:", err);
            showToast("Error al procesar el archivo JSON de respaldo.", "danger");
        }
    };
    reader.readAsText(file);
    e.target.value = '';
}

function populateReportStudentSelect() {
    if (!hasRolePermission('reports', STATE.currentRole)) {
        return;
    }

    const gradeFilter = document.getElementById('reportGradeFilter');
    const sectionFilter = document.getElementById('reportSectionFilter');

    // Cargar opciones de Grado y Sección disponibles ordenadas pedagógicamente
    let distinctGrades = [];
    let distinctSections = [];
    const isDocente = (STATE.currentRole === 'docente');

    if (isDocente && typeof getTeacherAssignedGradesList === 'function') {
        const myGradesList = getTeacherAssignedGradesList(STATE.currentUser);
        distinctGrades = Array.from(new Set(myGradesList.map(g => g.name))).sort((a, b) => {
            return (typeof getGradeWeight === 'function' ? getGradeWeight(a) - getGradeWeight(b) : 0) || a.localeCompare(b);
        });
        distinctSections = Array.from(new Set(myGradesList.map(g => g.section).filter(Boolean))).sort();
    } else {
        const allStudents = STATE.students || [];
        distinctGrades = Array.from(new Set(allStudents.map(s => s.grade).filter(Boolean))).sort((a, b) => {
            return (typeof getGradeWeight === 'function' ? getGradeWeight(a) - getGradeWeight(b) : 0) || a.localeCompare(b);
        });
        if (distinctGrades.length === 0) {
            distinctGrades = ['4to Perito Contador', '5to Perito Contador', '6to Perito Contador'];
        }
        distinctSections = ['Sección A', 'Sección B', 'Sección C', 'Sección D'];
    }

    if (gradeFilter) {
        let curGrade = gradeFilter.value;
        if (isDocente && !curGrade && distinctGrades.length === 1) curGrade = distinctGrades[0];
        gradeFilter.innerHTML = (isDocente ? '<option value="">-- Mis Grados Asignados --</option>' : '<option value="">-- Todos los Grados --</option>') + 
            distinctGrades.map(g => `<option value="${g}" ${g === curGrade ? 'selected' : ''}>${g}</option>`).join('');
        if (curGrade) gradeFilter.value = curGrade;
    }

    if (sectionFilter) {
        let curSection = sectionFilter.value;
        if (isDocente && !curSection && distinctSections.length === 1) curSection = distinctSections[0];
        sectionFilter.innerHTML = (isDocente ? '<option value="">-- Mis Secciones Asignadas --</option>' : '<option value="">-- Todas las Secciones --</option>') + 
            distinctSections.map(sec => `<option value="${sec}" ${sec === curSection ? 'selected' : ''}>${sec}</option>`).join('');
        if (curSection) sectionFilter.value = curSection;
    }
    filterAndPopulateReportStudents();
}
window.populateReportStudentSelect = populateReportStudentSelect;

