function openSectionStudentsModal(gradeCode) {
    STATE.activeSectionModalGrade = gradeCode;
    const gradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const title = document.getElementById('sectionStudentsGradeName');
    const subtitle = document.getElementById('sectionStudentsSubtitle');
    const badge = document.getElementById('sectionStudentsCountBadge');
    const tbody = document.getElementById('sectionStudentsTableBody');

    const students = (typeof getSortedGradebookStudents === 'function') ? 
        getSortedGradebookStudents(gradeCode, gradeObj) : 
        (STATE.students || []).filter(s => s.grade === gradeCode || (gradeObj && s.grade === gradeObj.name));

    students.sort((a, b) => {
        const nameA = formatStudentDisplayName(a, 'lastFirst');
        const nameB = formatStudentDisplayName(b, 'lastFirst');
        return nameA.localeCompare(nameB, 'es', { sensitivity: 'base' });
    });

    const secClean = (gradeObj?.section || '').toLowerCase().startsWith('secci') ? gradeObj.section : ('Sección ' + (gradeObj?.section || 'A'));
    if (title) title.textContent = gradeObj ? `${gradeObj.name} - ${secClean}` : gradeCode;
    if (subtitle) subtitle.textContent = `Carrera: ${gradeObj?.career || 'Perito Contador'} | Jornada: ${gradeObj?.shift || 'Matutina'}`;
    if (badge) badge.textContent = `${students.length} Estudiantes`;

    if (tbody) {
        tbody.innerHTML = students.map((s, idx) => `
            <tr>
                <td style="text-align:center;"><strong>${idx + 1}</strong></td>
                <td style="text-align:center;"><img src="${s.photo || 'https://ui-avatars.com/api/?name='+encodeURIComponent(formatStudentDisplayName(s, 'lastFirst'))}" style="width:28px; height:28px; border-radius:50%; object-fit:cover;"></td>
                <td><code>${escapeHtml(s.carne || s.personalCode || '---')}</code></td>
                <td><strong>${escapeHtml(formatStudentDisplayName(s, 'lastFirst'))}</strong></td>
                <td style="text-align:center;">${s.age || (typeof calculateStudentAge === 'function' ? calculateStudentAge(s.birthDate) : '—') || '—'}</td>
                <td>${s.tutorPhone || s.phone || 'Sin teléfono'}</td>
                <td><span class="badge ${s.status === 'Activo' ? 'badge-success' : 'badge-danger'}">${s.status || 'Activo'}</span></td>
            </tr>
        `).join('') || `<tr><td colspan="7" style="text-align:center; padding:20px; color:#64748b;">No hay estudiantes asignados a esta sección.</td></tr>`;
    }

    showModalById('sectionStudentsModal');
}
window.openSectionStudentsModal = openSectionStudentsModal;

// ==========================================================================
// 🎓 CIERRE DE CICLO ESCOLAR, PROMOCIÓN DE ESTUDIANTES Y APERTURA DE NUEVO CICLO
// (EXCLUSIVO DIRECCIÓN, SECRETARÍA Y ADMINISTRACIÓN)
// ==========================================================================

function checkPromotionPermissions() {
    const role = (STATE.currentRole || (STATE.currentUser && STATE.currentUser.role) || '').toLowerCase();
    const isSuperOrDir = (typeof isSuperUserRole === 'function' && isSuperUserRole(role)) || (typeof isDirectorRole === 'function' && isDirectorRole(role));
    if (isSuperOrDir) return true;
    if (role !== 'admin' && role !== 'director' && role !== 'direccion' && role !== 'secretaria' && role !== 'secretaria_general') {
        showToast("Acceso denegado: El cierre de ciclo y promoción es una potestad exclusiva de Dirección y Secretaría.", "danger");
        return false;
    }
    return true;
}

function openCyclePromotionModal(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!checkPromotionPermissions()) return;
    populatePromotionCycleSelects();
    renderPromotionStudentsTable();

    // 🔒 Botones exclusivos de Dirección y Admin
    const role = ((window.STATE && window.STATE.currentRole) || '').toLowerCase();
    const isDirector = (typeof isSuperUserRole === 'function' && isSuperUserRole(role)) ||
                       (typeof isDirectorRole === 'function' && isDirectorRole(role)) ||
                       role === 'director' || role === 'direccion' || role === 'admin';

    const backupBtn = document.getElementById('btnDownloadCycleBackup');
    if (backupBtn) backupBtn.style.display = isDirector ? 'inline-flex' : 'none';

    const printActBtn = document.getElementById('btnPrintPromotionAct');
    if (printActBtn) printActBtn.style.display = isDirector ? 'inline-flex' : 'none';

    showModalById('cyclePromotionModal');
}

// ==========================================================================
// 7B. ADMIN Y GESTIÓN COMPLETA DE CICLOS LECTIVOS ESCOLARES
// ==========================================================================


function openCycleModal(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!checkEnrolmentPermissions()) return;
    resetCycleForm();
    renderCycleList();
    showModalById('cycleModal');
}

function closeCycleModal() {
    const modal = document.getElementById('cycleModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function renderCycleList() {
    const box = document.getElementById('cycleListDisplay');
    if (!box) return;

    const cycles = STATE.cycles || [];
    if (cycles.length === 0) {
        box.innerHTML = `
            <div style="text-align:center; padding:16px; color:var(--text-muted); font-size:0.85rem;">
                <i class="fa-solid fa-calendar-xmark" style="font-size:1.4rem; display:block; margin-bottom:4px; color:var(--brand-orange);"></i>
                No hay ciclos lectivos ingresados aún. Use el formulario inferior para ingresar el primer ciclo escolar oficial.
            </div>
        `;
        return;
    }

    box.innerHTML = cycles.map(c => {
        const isCurrentActive = (c.name === STATE.activeCycle);
        return `
        <div style="display:flex; justify-content:space-between; align-items:center; background:var(--bg-main); padding:8px 12px; border-radius:var(--radius-sm); border:1px solid ${isCurrentActive ? 'var(--brand-green)' : 'var(--border-color)'};">
            <div>
                <strong><i class="fa-solid fa-calendar-check" style="color:${isCurrentActive ? 'var(--brand-green)' : 'var(--text-muted)'};"></i> Ciclo ${c.name}</strong>
                ${isCurrentActive ? '<span class="badge badge-success" style="font-size:0.7rem; margin-left:6px;">En Uso</span>' : ''}
                ${c.status === 'Activo' && !isCurrentActive ? '<span class="badge badge-primary" style="font-size:0.7rem; margin-left:6px;">Activo</span>' : ''}
                <br>
                <small style="color:var(--text-muted);">${c.description || 'Ciclo Escolar Oficial'}</small>
            </div>
            <div style="display:flex; gap:6px; align-items:center;">
                ${!isCurrentActive ? `
                    <button class="btn btn-accent btn-sm" onclick="setCycleActive('${c.id}')" title="Seleccionar y activar este ciclo"><i class="fa-solid fa-check"></i> Activar</button>
                ` : ''}
                <button class="btn btn-secondary btn-sm" onclick="openEditCycleModal('${c.id}')" title="Editar Ciclo"><i class="fa-solid fa-pen"></i></button>
                <button class="btn btn-secondary btn-sm" style="color:var(--danger);" onclick="deleteCycle('${c.id}')" title="Eliminar Ciclo"><i class="fa-solid fa-trash"></i></button>
            </div>
        </div>
    `}).join('');
}

function openEditCycleModal(cycleId) {
    if (!checkEnrolmentPermissions()) return;
    const c = (STATE.cycles || []).find(x => x.id === cycleId);
    if (!c) return;

    document.getElementById('cycleFormId').value = c.id;
    document.getElementById('cycleFormHeaderTitle').innerHTML = `<i class="fa-solid fa-pen-to-square"></i> Editar Ciclo "${c.name}"`;
    document.getElementById('newCycleName').value = c.name;
    document.getElementById('newCycleStatus').value = c.status || 'Activo';
    document.getElementById('newCycleDescription').value = c.description || '';
    document.getElementById('cancelCycleEditBtn').style.display = 'inline-block';
    document.getElementById('cycleSubmitBtn').innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Cambios';
}

function resetCycleForm() {
    document.getElementById('cycleFormId').value = '';
    document.getElementById('cycleFormHeaderTitle').innerHTML = '<i class="fa-solid fa-circle-plus"></i> Ingresar Nuevo Ciclo Lectivo';
    document.getElementById('newCycleName').value = '';
    document.getElementById('newCycleStatus').value = 'Activo';
    document.getElementById('newCycleDescription').value = '';
    document.getElementById('cancelCycleEditBtn').style.display = 'none';
    document.getElementById('cycleSubmitBtn').innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Ciclo Lectivo';
}

async function saveCycleForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    if (!checkEnrolmentPermissions()) return;
    const cycleId = document.getElementById('cycleFormId')?.value?.trim();
    const name = document.getElementById('newCycleName')?.value?.trim();
    const status = document.getElementById('newCycleStatus')?.value || 'Activo';
    const description = document.getElementById('newCycleDescription')?.value?.trim() || '';

    if (!name) {
        showToast("Ingrese el nombre del ciclo lectivo.", "warning");
        return;
    }

    if (!STATE.cycles) STATE.cycles = [];

    const isEditing = Boolean(cycleId);
    if (isEditing) {
        if (!cycleId || cycleId === 'undefined' || cycleId === 'null') {
            console.error("Error: ID del ciclo no encontrado o indefinido.");
            showToast("Error: ID del ciclo no encontrado o indefinido.", "danger");
            return;
        }
    }

    const submitBtn = document.getElementById('cycleSubmitBtn') || document.querySelector('#cycleModal form button[type="submit"]');
    const origBtnHtml = submitBtn ? (submitBtn.getAttribute('data-orig-html') || submitBtn.innerHTML) : 'Guardar Ciclo Lectivo';
    if (submitBtn && !submitBtn.getAttribute('data-orig-html')) {
        submitBtn.setAttribute('data-orig-html', origBtnHtml);
    }

    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    try {
        if (cycleId) {
            const c = STATE.cycles.find(x => x.id === cycleId);
            if (c) {
                const oldName = c.name;
                c.name = name;
                c.status = status;
                c.description = description;
                if (STATE.activeCycle === oldName) {
                    STATE.activeCycle = name;
                }
            } else {
                throw new Error(`Ciclo lectivo "${cycleId}" no encontrado.`);
            }
        } else {
            if (STATE.cycles.some(x => x.name.toLowerCase() === name.toLowerCase())) {
                showToast(`El ciclo "${name}" ya se encuentra registrado.`, "warning");
                return;
            }

            const newCycle = {
                id: 'cyc-' + Date.now(),
                name,
                status,
                description
            };
            STATE.cycles.push(newCycle);

            if (STATE.cycles.length === 1 || status === 'Activo') {
                STATE.activeCycle = name;
            }
        }

        const nowTime = Date.now();
        STATE.lastModified = nowTime;

        // 🌟 A. Persistencia Atómica en Firestore
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
                const targetC = cycleId ? STATE.cycles.find(x => x.id === cycleId) : STATE.cycles[STATE.cycles.length - 1];
                if (targetC) {
                    const cRef = doc(db, 'cycles', targetC.id);
                    const ciclosRef = doc(db, 'ciclos', targetC.id);
                    const cPayload = { ...targetC, lastModified: nowTime };
                    const fsAction = (typeof setDoc === 'function')
                    ? setDoc(cRef, cPayload, { merge: true })
                    : ((typeof updateDoc === 'function')
                        ? updateDoc(cRef, cPayload).catch(e => {
                            if (typeof setDoc === 'function') return setDoc(cRef, cPayload, { merge: true });
                            throw e;
                        })
                        : Promise.resolve());
                    await withTimeout(fsAction, 8000, 'Tiempo de espera en Firestore agotado.');
                    if (typeof setDoc === 'function') {
                        await setDoc(ciclosRef, cPayload, { merge: true });
                    }
                }
            } catch(fsErr) {
                console.warn("Aviso al guardar ciclo en Firestore:", fsErr);
            }
        }

        // 🌟 B. Sincronización en Realtime Database
        let ok = false;
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            const syncActions = [
                EnccoCloudSync.syncNode('cycles', STATE.cycles),
                EnccoCloudSync.syncNode('activeCycle', STATE.activeCycle)
            ];
            const results = await withTimeout(Promise.all(syncActions), 8000, 'Tiempo de espera en Realtime Database agotado.');
            ok = results[0] && results[1];
        } else {
            ok = true;
        }

        if (!ok) {
            throw new Error("El servidor de Firebase no confirmó la escritura de ciclos escolares.");
        }

        saveStateToLocalStorage();
        resetCycleForm();
        renderCyclesList();
        updateCycleSelects();
        closeCycleModal();
        hideModalById('cycleModal');

        showToast(`Ciclo escolar "${name}" guardado y confirmado en Firebase con éxito.`, "success");
    } catch(err) {
        console.error("❌ Error al guardar ciclo lectivo:", err);
        showToast(`Error al guardar en Firebase: ${err.message || err}`, "danger");
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html') || origBtnHtml;
        }
    }
}

function setCycleActive(cycleId) {
    const c = (STATE.cycles || []).find(x => x.id === cycleId);
    if (!c) return;
    STATE.activeCycle = c.name;
    saveStateToLocalStorage();
    renderCycleList();
    updateCycleSelects();
    showToast(`Ciclo escolar activo cambiado a: ${c.name}`, "info");
    renderCurrentView();
    if (typeof enforceViewReadOnlyMode === 'function') enforceViewReadOnlyMode(viewName);
}

async function deleteCycle(cycleId) {
    if (!checkEnrolmentPermissions()) return;
    const c = (STATE.cycles || []).find(x => x.id === cycleId);
    if (!c) return;

    const confirmed = (window.EnccoDialog && typeof window.EnccoDialog.confirm === 'function')
        ? await window.EnccoDialog.confirm({
            title: 'Eliminar Ciclo Escolar',
            message: `¿Está seguro de eliminar el ciclo escolar "${c.name}"?\n\nEsta acción modificará la configuración de los periodos lectivos.`,
            type: 'danger',
            confirmText: 'Eliminar Ciclo',
            cancelText: 'Cancelar'
        })
        : true;

    if (confirmed) {
        STATE.cycles = (STATE.cycles || []).filter(x => x.id !== cycleId);
        if (STATE.cycles.length === 0) {
            STATE.cycles = [{ id: 'cyc-2026', name: '2026', status: 'Activo' }];
        }
        if (STATE.activeCycle === c.name) {
            STATE.activeCycle = STATE.cycles[0] ? STATE.cycles[0].name : '2026';
        }
        try {
            const modular = window.FirebaseModular;
            if (modular && modular.db && typeof modular.doc === 'function' && typeof modular.deleteDoc === 'function') {
                modular.deleteDoc(modular.doc(modular.db, 'ciclos', cycleId)).catch(e => {});
            }
        } catch(fsErr) {}

        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.patchNode) {
            EnccoCloudSync.patchNode('cycles', STATE.cycles);
        }

        renderCycleList();
        updateCycleSelects();
        populateAttendanceSelects(false);
        updateUserAlertsUI();
        renderCurrentDashboardAlerts();
        showToast(`Ciclo escolar "${c.name}" eliminado del sistema.`, "info");
        renderCurrentView();
    }
}


function getTeacherOfficialName(courseOrTeacher) {
    if (!courseOrTeacher) return 'Sin asignar';
    const users = Array.isArray(STATE.users) ? STATE.users : [];
    if (typeof courseOrTeacher === 'object') {
        const c = courseOrTeacher;
        if (c.teacherId) {
            const u = users.find(x => x.id === c.teacherId);
            if (u && u.name) return u.name;
        }
        if (typeof isCourseAssignedToTeacher === 'function') {
            const u = users.find(x => isCourseAssignedToTeacher(c, x));
            if (u && u.name) return u.name;
        }
        return c.teacher || c.teacherName || 'Sin asignar';
    }
    const u = users.find(x => x.id === courseOrTeacher || x.name === courseOrTeacher);
    if (u && u.name) return u.name;
    if (typeof isCourseAssignedToTeacher === 'function') {
        const uMatch = users.find(x => isCourseAssignedToTeacher({ teacher: courseOrTeacher }, x));
        if (uMatch && uMatch.name) return uMatch.name;
    }
    return courseOrTeacher;
}
window.getTeacherOfficialName = getTeacherOfficialName;

function syncPensumTeachersWithUsers(saveToFirebase = false) {
    if (!Array.isArray(STATE.pensum) || !Array.isArray(STATE.users) || STATE.users.length === 0) return false;
    let modified = false;
    STATE.pensum.forEach(p => {
        const targetUser = STATE.users.find(u => u.role === 'docente' && ((p.teacherId && u.id === p.teacherId) || (typeof isCourseAssignedToTeacher === 'function' && isCourseAssignedToTeacher(p, u)))) ||
                           STATE.users.find(u => (p.teacherId && u.id === p.teacherId) || (typeof isCourseAssignedToTeacher === 'function' && isCourseAssignedToTeacher(p, u)));
        if (targetUser) {
            if (p.teacher !== targetUser.name) {
                p.teacher = targetUser.name;
                modified = true;
            }
            if (p.teacherName !== targetUser.name) {
                p.teacherName = targetUser.name;
                modified = true;
            }
            if (p.teacherId !== targetUser.id) {
                p.teacherId = targetUser.id;
                modified = true;
            }
        }
    });
    if (modified && saveToFirebase) {
        saveStateToLocalStorage();
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            EnccoCloudSync.syncNode('pensum', STATE.pensum);
        } else if (typeof pushStateToFirebaseCloud === 'function') {
            pushStateToFirebaseCloud(false);
        }
    }
    return modified;
}
window.syncPensumTeachersWithUsers = syncPensumTeachersWithUsers;

// 8. LIBRO DE CALIFICACIONES SEGÚN LA CLASE DEL DOCENTE O ADMINISTRADOR
// ==========================================================================
function populateTeacherCourseSelect(preferredCourseId = null) {
    const select = document.getElementById('teacherCourseSelect');
    if (!select) return;

    // 🔒 Preservar y fijar la clase y grado previamente seleccionados para evitar cambios no deseados
    const prevCourseId = preferredCourseId ||
        (select.value && select.value !== '' ? select.value : null) ||
        sessionStorage.getItem('ENCCO_SELECTED_GRADEBOOK_COURSE') ||
        localStorage.getItem('ENCCO_SELECTED_GRADEBOOK_COURSE') ||
        STATE.selectedGradebookCourseId;

    const prevGrade = sessionStorage.getItem('ENCCO_SELECTED_GRADEBOOK_GRADE') ||
        localStorage.getItem('ENCCO_SELECTED_GRADEBOOK_GRADE') ||
        STATE.selectedGradebookGrade;

    const currentUser = STATE.currentUser || STATE.users.find(u => u.role === 'docente') || STATE.users[0];
    const isDocente = (STATE.currentRole === 'docente');

    // Si STATE.pensum está incompleto o ausente, restaurar inmediatamente desde respaldo canónico
    if (!Array.isArray(STATE.pensum) || STATE.pensum.length < 28) {
        if (typeof ensureOfficialPensumAssignments === 'function') {
            ensureOfficialPensumAssignments();
        }
    }

    let html = '';
    const gradeOrder = ['4to Perito Contador', '5to Perito Contador', '6to Perito Contador'];

    if (isDocente && currentUser) {
        // Los maestros SOLO pueden ver las clases a las que están asignados
        const myClasses = (STATE.pensum || []).filter(p => isCourseAssignedToTeacher(p, currentUser));

        if (myClasses.length > 0) {
            // Agrupar ordenadamente por grado para mayor claridad
            const grouped = {};
            myClasses.forEach(p => {
                const g = p.grade || 'Otras Cátedras';
                if (!grouped[g]) grouped[g] = [];
                grouped[g].push(p);
            });

            const sortedGrades = Object.keys(grouped).sort((a, b) => {
                const wA = (typeof getGradeWeight === 'function') ? getGradeWeight(a) : 999;
                const wB = (typeof getGradeWeight === 'function') ? getGradeWeight(b) : 999;
                if (wA !== wB) return wA - wB;
                return a.localeCompare(b);
            });

            sortedGrades.forEach(g => {
                html += `<optgroup label="🎓 ${g} — Asignadas (${currentUser.name})">`;
                // Ordenar rigurosamente por Sección ('A', 'B', 'C') y luego por Asignatura
                grouped[g].sort((a, b) => {
                    const secA = (a.section || '').trim().toUpperCase();
                    const secB = (b.section || '').trim().toUpperCase();
                    if (secA !== secB) return secA.localeCompare(secB);
                    return (a.subject || '').localeCompare(b.subject || '');
                });
                grouped[g].forEach(p => {
                    html += `<option value="${p.id}">${p.subject} — ${p.grade} (${p.section}) [${p.career}]</option>`;
                });
                html += `</optgroup>`;
            });
        } else {
            html += `<optgroup label="⭐ Mis Clases Asignadas (${currentUser.name})"><option value="">-- Sin clases asignadas a su cuenta --</option></optgroup>`;
        }
    } else {
        // ADMIN / DIRECTOR / SECRETARIA / AUDITORÍA: Ver y editar cualquier cátedra agrupada ordenadamente por Grado
        const grouped = {};
        (STATE.pensum || []).forEach(p => {
            const g = p.grade || 'Otras Clases';
            if (!grouped[g]) grouped[g] = [];
            grouped[g].push(p);
        });

        const sortedGrades = Object.keys(grouped).sort((a, b) => {
            const wA = (typeof getGradeWeight === 'function') ? getGradeWeight(a) : 999;
            const wB = (typeof getGradeWeight === 'function') ? getGradeWeight(b) : 999;
            if (wA !== wB) return wA - wB;
            return a.localeCompare(b);
        });

        sortedGrades.forEach(g => {
            html += `<optgroup label="🎓 ${g} — Clases y Secciones Oficiales">`;
            // Ordenar rigurosamente por Sección ('A', 'B', 'C') y luego por Asignatura
            grouped[g].sort((a, b) => {
                const secA = (a.section || '').trim().toUpperCase();
                const secB = (b.section || '').trim().toUpperCase();
                if (secA !== secB) return secA.localeCompare(secB);
                return (a.subject || '').localeCompare(b.subject || '');
            });
            grouped[g].forEach(p => {
                html += `<option value="${p.id}">${p.subject} — ${p.grade} (${p.section}) — Catedrático: ${p.teacher} [${p.career}]</option>`;
            });
            html += `</optgroup>`;
        });
    }

    select.innerHTML = html;

    // 🔒 Restauración estricta y fijación del curso/grado seleccionado
    let targetVal = null;
    if (prevCourseId && Array.from(select.options).some(o => o.value === prevCourseId)) {
        targetVal = prevCourseId;
    } else if (prevGrade) {
        const matchOpt = Array.from(select.options).find(o => {
            const p = (STATE.pensum || []).find(x => x.id === o.value);
            return p && (p.grade === prevGrade || (p.gradeCode && p.gradeCode.includes(prevGrade)));
        });
        if (matchOpt) targetVal = matchOpt.value;
    }

    if (targetVal) {
        select.value = targetVal;
    } else if (select.options.length > 0 && !select.value) {
        select.selectedIndex = 0;
    }

    if (select.value) {
        try {
            sessionStorage.setItem('ENCCO_SELECTED_GRADEBOOK_COURSE', select.value);
            localStorage.setItem('ENCCO_SELECTED_GRADEBOOK_COURSE', select.value);
        } catch(e) {}
        STATE.selectedGradebookCourseId = select.value;
        const pObj = (STATE.pensum || []).find(p => p.id === select.value);
        if (pObj && pObj.grade) {
            try {
                sessionStorage.setItem('ENCCO_SELECTED_GRADEBOOK_GRADE', pObj.grade);
                localStorage.setItem('ENCCO_SELECTED_GRADEBOOK_GRADE', pObj.grade);
            } catch(e) {}
            STATE.selectedGradebookGrade = pObj.grade;
        }
    }
}

function populateGradebookBimestreSelect(forceOfficial = false) {
    const select = document.getElementById('gradebookBimestreSelect');
    const notice = document.getElementById('gradebookTeacherBimestreNotice');
    const noticeText = document.getElementById('gradebookTeacherBimestreNoticeText');
    if (!select) return;

    const activeB = parseInt(STATE.config?.activeBimestre) || 1;
    const activeUnits = Array.isArray(STATE.config?.activeUnits)
        ? STATE.config.activeUnits.map(Number)
        : [activeB];

    const bNames = {
        1: 'Unidad 1 / I Bimestre',
        2: 'Unidad 2 / II Bimestre',
        3: 'Unidad 3 / III Bimestre',
        4: 'Unidad 4 / IV Bimestre'
    };

    // Si se fuerza el bimestre oficial (ej: cambio remoto por Dirección) o no hay selección válida, usar activeB
    const savedBim = parseInt(sessionStorage.getItem('ENCCO_SELECTED_GRADEBOOK_BIMESTRE') || localStorage.getItem('ENCCO_SELECTED_GRADEBOOK_BIMESTRE'));
    const prevVal = select.value ? parseInt(select.value) : (savedBim || null);
    let selectedBim = activeB;
    if (!forceOfficial && prevVal && prevVal >= 1 && prevVal <= 4) {
        selectedBim = prevVal;
    }

    let optionsHtml = '';
    for (let u = 1; u <= 4; u++) {
        const isPrimary = (u === activeB);
        const isEditable = activeUnits.includes(u);
        let tag = '';
        if (isPrimary && isEditable) {
            tag = ' ⭐ (Oficial Principal - Habilitado)';
        } else if (isPrimary && !isEditable) {
            tag = ' 🔒 (Oficial Principal - Cerrado)';
        } else if (isEditable) {
            tag = ' ✅ (Habilitado para Modificar)';
        } else {
            tag = ' 🔒 (Cerrado)';
        }
        optionsHtml += `<option value="${u}">${bNames[u]}${tag}</option>\n`;
    }

    select.innerHTML = optionsHtml;
    select.value = selectedBim.toString();
    try {
        sessionStorage.setItem('ENCCO_SELECTED_GRADEBOOK_BIMESTRE', selectedBim.toString());
        localStorage.setItem('ENCCO_SELECTED_GRADEBOOK_BIMESTRE', selectedBim.toString());
    } catch(e) {}
    select.disabled = false;
    select.style.backgroundColor = '#ffffff';
    select.style.cursor = 'pointer';

    if (notice && noticeText) {
        notice.style.display = 'block';
        const isCurrentEditable = activeUnits.includes(selectedBim);
        if (selectedBim === activeB && isCurrentEditable) {
            notice.style.background = '#ecfdf5';
            notice.style.borderColor = '#a7f3d0';
            notice.style.color = '#065f46';
            noticeText.innerHTML = `<i class="fa-solid fa-circle-check"></i> <strong>Bimestre Principal:</strong> ${bNames[activeB] || ('Unidad ' + activeB)} (Habilitado por Dirección y Secretaría para ingreso de notas).`;
        } else if (selectedBim === activeB && !isCurrentEditable) {
            notice.style.background = '#fef3c7';
            notice.style.borderColor = '#fde68a';
            notice.style.color = '#92400e';
            const activeListStr = activeUnits.length > 0 ? activeUnits.map(u => bNames[u]).join(', ') : 'Ninguna';
            noticeText.innerHTML = `<i class="fa-solid fa-lock"></i> <strong>Bimestre Principal:</strong> ${bNames[activeB] || ('Unidad ' + activeB)} (Cerrado oficialmente para ingreso de notas. Unidades habilitadas: ${activeListStr}).`;
        } else if (isCurrentEditable) {
            notice.style.background = '#ecfdf5';
            notice.style.borderColor = '#a7f3d0';
            notice.style.color = '#065f46';
            noticeText.innerHTML = `<i class="fa-solid fa-circle-check"></i> <strong>Unidad Activa Habilitada:</strong> ${bNames[selectedBim] || ('Unidad ' + selectedBim)} (Habilitada por Dirección y Secretaría para ingreso y modificación de notas).`;
        } else {
            notice.style.background = '#fef3c7';
            notice.style.borderColor = '#fde68a';
            notice.style.color = '#92400e';
            const activeListStr = activeUnits.length > 0 ? activeUnits.map(u => bNames[u]).join(', ') : 'Ninguna';
            noticeText.innerHTML = `<i class="fa-solid fa-calendar-days"></i> <strong>Visualizando:</strong> ${bNames[selectedBim] || ('Unidad ' + selectedBim)} (Cerrado para edición directa. Unidades habilitadas: ${activeListStr}).`;
        }
    }

    renderTeacherGradeProgressTable();
}
window.populateGradebookBimestreSelect = populateGradebookBimestreSelect;

