let _attendanceCameraStream = null;
let _attendanceCameraFacing = 'environment'; // 'environment' (trasera) o 'user' (frontal)
let _attendanceBarcodeDetector = null;
let _attendanceScanAnimId = null;
let _attendanceLastScannedStudentCode = '';
let _attendanceLastScanTime = 0;
let _attendanceTodayScannedCount = 0;

function focusAttendanceBarcodeInput() {
    const input = document.getElementById('attendanceBarcodeInput');
    if (input) {
        input.focus();
        input.select();
    }
}

function handleAttendanceBarcodeInput(e) {
    if (e.key === 'Enter') {
        e.preventDefault();
        submitAttendanceManualBarcodeInput();
    }
}

function submitAttendanceManualBarcodeInput() {
    const input = document.getElementById('attendanceBarcodeInput');
    if (!input) return;
    const rawVal = input.value.trim();
    if (!rawVal) return;
    registerAttendanceByCode(rawVal);
    input.value = '';
    input.focus();
}

function submitAttendanceCameraManualInput() {
    const input = document.getElementById('attendanceCameraManualInput');
    if (!input) return;
    const rawVal = input.value.trim();
    if (!rawVal) return;
    registerAttendanceByCode(rawVal);
    input.value = '';
}

function playAttendanceBeep(isSuccess = true) {
    try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = new AudioCtx();
        if (isSuccess) {
            // Tono alegre de confirmación: Dos notas cortas (880Hz -> 1174.66Hz)
            const osc1 = ctx.createOscillator();
            const osc2 = ctx.createOscillator();
            const gain = ctx.createGain();
            osc1.type = 'sine';
            osc2.type = 'triangle';
            osc1.frequency.setValueAtTime(880, ctx.currentTime);
            osc2.frequency.setValueAtTime(1174.66, ctx.currentTime + 0.08);
            gain.gain.setValueAtTime(0.18, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.22);
            osc1.connect(gain);
            osc2.connect(gain);
            gain.connect(ctx.destination);
            osc1.start(ctx.currentTime);
            osc1.stop(ctx.currentTime + 0.08);
            osc2.start(ctx.currentTime + 0.08);
            osc2.stop(ctx.currentTime + 0.22);
        } else {
            // Tono de error/no encontrado: Tono grave corto (220Hz)
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(220, ctx.currentTime);
            gain.gain.setValueAtTime(0.2, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.25);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(ctx.currentTime);
            osc.stop(ctx.currentTime + 0.25);
        }
    } catch (e) {
        console.warn('Audio feedback warning:', e);
    }
}

function updateLastScannedBanner(student, status, detailsMsg) {
    const banner = document.getElementById('attendanceLastScannedBanner');
    const nameEl = document.getElementById('attendanceBannerStudentName');
    const detEl = document.getElementById('attendanceBannerStudentDetails');
    const badgeEl = document.getElementById('attendanceBannerStatusBadge');
    const timeEl = document.getElementById('attendanceBannerTime');
    const avatarEl = document.getElementById('attendanceBannerAvatar');

    const modalPill = document.getElementById('scannerLastScannedPill');
    const modalName = document.getElementById('scannerPillName');
    const modalDet = document.getElementById('scannerPillDetails');
    const modalAvatar = document.getElementById('scannerPillAvatar');

    const countNum = document.getElementById('attendanceScanCountNum');
    if (countNum) countNum.textContent = _attendanceTodayScannedCount;

    const now = new Date();
    const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

    if (status === 'success' && student) {
        const studentName = formatStudentDisplayName(student, 'lastFirst') || 'Estudiante';
        const gradeStr = student.grade || student.gradeLabel || student.gradeCode || 'Grado no esp.';
        const sectionStr = student.section || '';
        const carneStr = student.carne || student.personalCode || student.cui || '';

        if (banner) {
            banner.style.display = 'flex';
            banner.style.borderColor = '#86efac';
            banner.style.background = '#ffffff';
        }
        if (nameEl) nameEl.textContent = studentName;
        if (detEl) detEl.textContent = `${gradeStr} ${sectionStr ? 'Sec. ' + sectionStr : ''} | Carné: ${carneStr} | ${detailsMsg || 'Presente'}`;
        if (badgeEl) {
            badgeEl.className = 'badge';
            badgeEl.style.background = '#dcfce7';
            badgeEl.style.color = '#15803d';
            badgeEl.innerHTML = '<i class="fa-solid fa-check"></i> PRESENTE';
        }
        if (timeEl) timeEl.textContent = timeStr;
        if (avatarEl) {
            if (student.photo) {
                avatarEl.innerHTML = `<img src="${student.photo}" style="width:100%; height:100%; object-fit:cover;">`;
            } else {
                avatarEl.innerHTML = `<i class="fa-solid fa-user-check"></i>`;
            }
        }

        if (modalPill) modalPill.style.display = 'flex';
        if (modalName) modalName.textContent = studentName;
        if (modalDet) modalDet.textContent = `${gradeStr} ${sectionStr ? 'Sec. ' + sectionStr : ''} - ${timeStr}`;
        if (modalAvatar) {
            if (student.photo) {
                modalAvatar.innerHTML = `<img src="${student.photo}" style="width:100%; height:100%; object-fit:cover; border-radius:50%;">`;
            } else {
                modalAvatar.innerHTML = `<i class="fa-solid fa-check"></i>`;
            }
        }
    } else {
        if (banner) {
            banner.style.display = 'flex';
            banner.style.borderColor = '#fca5a5';
            banner.style.background = '#fff5f5';
        }
        if (nameEl) nameEl.textContent = 'Código no reconocido';
        if (detEl) detEl.textContent = detailsMsg || 'No se encontró un estudiante con el código escaneado.';
        if (badgeEl) {
            badgeEl.className = 'badge';
            badgeEl.style.background = '#fee2e2';
            badgeEl.style.color = '#b91c1c';
            badgeEl.innerHTML = '<i class="fa-solid fa-xmark"></i> NO REGISTRADO';
        }
        if (timeEl) timeEl.textContent = timeStr;
        if (avatarEl) avatarEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation" style="color:#ef4444;"></i>`;
    }
}

function registerAttendanceByCode(rawCode) {
    if (!rawCode) return false;
    let cleanCode = String(rawCode).trim();
    if (!cleanCode) return false;

    // Si viene de URL o texto enriquecido de QR, extraer parámetro o segmento clave
    if (cleanCode.includes('?')) {
        try {
            const url = new URL(cleanCode, (typeof window !== 'undefined' && window.location) ? window.location.origin : 'https://comerciojutiapa.edu.gt');
            const pCode = url.searchParams.get('carne') || url.searchParams.get('code') || url.searchParams.get('personalCode') || url.searchParams.get('id');
            if (pCode) cleanCode = pCode.trim();
        } catch(e) {}
    }

    const normTarget = cleanCode.toUpperCase().replace(/[\s\-_]/g, '');
    const rawTarget = cleanCode.toUpperCase();

    const students = STATE.students || [];
    const matchedStudent = students.find(s => {
        const pCode = (s.personalCode || '').toUpperCase();
        const carne = (s.carne || '').toUpperCase();
        const cui = (s.cui || '').toString().trim();
        const sid = (s.id || '').toString().trim();

        if (pCode === rawTarget || carne === rawTarget || cui === cleanCode || sid === cleanCode) return true;
        if (normTarget.length >= 3) {
            if (pCode.replace(/[\s\-_]/g, '') === normTarget) return true;
            if (carne.replace(/[\s\-_]/g, '') === normTarget) return true;
        }
        return false;
    });

    if (matchedStudent && (matchedStudent.status === 'Retirado' || matchedStudent.status === 'Inactivo')) {
        playAttendanceBeep(false);
        if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate([200]);
        const sDispName = (typeof formatStudentDisplayName === 'function') ? formatStudentDisplayName(matchedStudent, 'lastFirst') : `${matchedStudent.firstName || ''} ${matchedStudent.lastName || ''}`;
        updateLastScannedBanner(null, 'error', `Estudiante RETIRADO: ${sDispName}. No se permite registrar asistencia a alumnos retirados.`);
        if (typeof showToast === 'function') showToast(`⚠️ El estudiante ${sDispName} se encuentra RETIRADO. No se puede registrar asistencia.`, 'error');
        return false;
    }

    const student = (matchedStudent && (typeof isStudentActive !== 'function' || isStudentActive(matchedStudent))) ? matchedStudent : null;

    if (!student) {
        playAttendanceBeep(false);
        if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate([200]);
        updateLastScannedBanner(null, 'error', `Código "${rawCode}" no coincide con ningún estudiante activo.`);
        if (typeof showToast === 'function') showToast(`Código "${rawCode}" no encontrado.`, 'warning');
        return false;
    }

    // Identificar grado del estudiante
    const rawS = `${student.grade || ''} ${student.gradeCode || ''} ${student.gradeLabel || ''}`.toUpperCase();
    let sGradeNum = 0;
    if (rawS.includes('6') || rawS.includes('SEXTO') || rawS.includes('6TO')) sGradeNum = 6;
    else if (rawS.includes('5') || rawS.includes('QUINTO') || rawS.includes('5TO')) sGradeNum = 5;
    else if (rawS.includes('4') || rawS.includes('CUARTO') || rawS.includes('4TO')) sGradeNum = 4;
    const sSec = (typeof getCleanSectionLetter === 'function') ? getCleanSectionLetter(student.section || student.gradeCode || student.gradeLabel || rawS) : (student.section || '');

    // Encontrar el grado en gradesList
    let studentGradeCode = student.gradeCode || student.grade || '';
    const matchingGradeObj = (STATE.gradesList || []).find(g => {
        const rawG = `${g.code || ''} ${g.name || ''} ${g.section || ''}`.toUpperCase();
        let gNum = 0;
        if (rawG.includes('6') || rawG.includes('SEXTO') || rawG.includes('6TO')) gNum = 6;
        else if (rawG.includes('5') || rawG.includes('QUINTO') || rawG.includes('5TO')) gNum = 5;
        else if (rawG.includes('4') || rawG.includes('CUARTO') || rawG.includes('4TO')) gNum = 4;
        const gSec = (typeof getCleanSectionLetter === 'function') ? getCleanSectionLetter(g.section || g.code || g.name || rawG) : (g.section || '');
        return (sGradeNum > 0 && gNum === sGradeNum) && (sSec && gSec === sSec);
    });

    if (matchingGradeObj && matchingGradeObj.code) {
        studentGradeCode = matchingGradeObj.code;
    }

    const today = new Date();
    const todayDay = today.getDate();
    const todayMonth = today.getMonth() + 1;

    // Obtener elementos selectores actuales del DOM
    const gradeSelect = (typeof document !== 'undefined') ? document.getElementById('attendanceGradeSelect') : null;
    const monthSelect = (typeof document !== 'undefined') ? document.getElementById('attendanceMonthSelect') : null;
    const courseSelect = (typeof document !== 'undefined') ? document.getElementById('attendanceCourseSelect') : null;
    
    let activeGradeCode = (gradeSelect && gradeSelect.value) ? gradeSelect.value : studentGradeCode;
    let activeMonth = monthSelect ? (parseInt(monthSelect.value) || todayMonth) : todayMonth;
    let activeCourse = courseSelect ? courseSelect.value : 'GENERAL';

    const currentScanRole = (STATE.currentRole || (STATE.currentUser && STATE.currentUser.role) || '').toLowerCase();
    const isScanAuthority = ['admin', 'super_usuario', 'director', 'direccion', 'secretaria', 'profesor_auxiliar', 'auxiliar', 'auxiliatura'].includes(currentScanRole);
    const isScanDocente = (currentScanRole === 'docente');

    if (isScanDocente && !isScanAuthority) {
        const currentUser = STATE.currentUser || (STATE.users || [])[0];
        const myClasses = (STATE.pensum || []).filter(p => isCourseAssignedToTeacher(p, currentUser));
        if (!activeCourse || activeCourse === 'GENERAL' || !myClasses.some(p => p.id === activeCourse)) {
            const matchingClass = myClasses.find(p => {
                const pSec = getCleanSectionLetter(p.section || p.gradeCode || p.grade);
                const sSec = getCleanSectionLetter(student.section || student.gradeCode || student.grade);
                const pGrade = (p.grade || '').toLowerCase();
                const sGrade = (student.grade || '').toLowerCase();
                return ((pGrade.includes('4') && sGrade.includes('4')) || (pGrade.includes('5') && sGrade.includes('5')) || (pGrade.includes('6') && sGrade.includes('6'))) && (!pSec || !sSec || pSec === sSec);
            }) || myClasses[0];

            if (matchingClass) {
                activeCourse = matchingClass.id;
                if (courseSelect) courseSelect.value = activeCourse;
            }
        }
    }

    // Si el usuario tiene seleccionado otro grado y el estudiante pertenece a un grado registrado en el select
    if (gradeSelect && gradeSelect.value !== studentGradeCode && studentGradeCode) {
        for (let i = 0; i < gradeSelect.options.length; i++) {
            if (gradeSelect.options[i].value === studentGradeCode) {
                gradeSelect.selectedIndex = i;
                activeGradeCode = studentGradeCode;
                break;
            }
        }
    }

    if (!STATE.attendanceRecords) STATE.attendanceRecords = {};
    const recordKey = (typeof getAttendanceRecordKey === 'function') ? getAttendanceRecordKey(activeGradeCode, activeMonth, activeCourse) : `${activeGradeCode}_${activeMonth}_${activeCourse}`;
    if (!STATE.attendanceRecords[recordKey]) STATE.attendanceRecords[recordKey] = {};
    if (!STATE.attendanceRecords[recordKey][student.id]) STATE.attendanceRecords[recordKey][student.id] = {};

    // Marcar presente en el día de hoy (o día 1 si el mes seleccionado no es el actual)
    const targetDay = (activeMonth === todayMonth) ? todayDay : 1;

    // 🛡️ Regla de oro: No sobrescribir si el alumno tiene permiso justificado ('J') o falta injustificada blindada ('A')
    const curVal = STATE.attendanceRecords[recordKey][student.id][targetDay];
    const permObj = (typeof getStudentPermissionForDay === 'function')
        ? getStudentPermissionForDay(student.id, today.getFullYear(), activeMonth, targetDay)
        : null;

    const sFullName = formatStudentDisplayName(student, 'lastFirst') || 'Estudiante';

    if (permObj && isUnjustifiedPermission(permObj)) {
        STATE.attendanceRecords[recordKey][student.id][targetDay] = 'A';
        if (typeof saveAttendanceRecords === 'function') saveAttendanceRecords(false, null, recordKey);
        playAttendanceBeep(false);
        if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate([200]);
        updateLastScannedBanner(student, 'error', `🔒 Ausencia Injustificada Blindada 'A' (Día ${targetDay})`);
        if (typeof showToast === 'function') {
            showToast(`🔒 ${sFullName} tiene una Ausencia Injustificada Blindada ('A') registrada para el día ${targetDay}. Nadie puede cambiarla.`, 'error');
        }
    } else if (curVal === 'J' || permObj) {
        STATE.attendanceRecords[recordKey][student.id][targetDay] = 'J';
        if (typeof saveAttendanceRecords === 'function') saveAttendanceRecords(false, null, recordKey);
        playAttendanceBeep(true);
        if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate([70, 40, 70]);
        updateLastScannedBanner(student, 'warning', `🔒 Permiso Justificado Protegido (Día ${targetDay})`);
        if (typeof showToast === 'function') {
            showToast(`ℹ️ ${sFullName} cuenta con Justificación / Permiso Oficial activo para el día ${targetDay}. Se preserva el estado 'J'.`, 'info');
        }
    } else {
        STATE.attendanceRecords[recordKey][student.id][targetDay] = 'P';
        _attendanceTodayScannedCount++;

        // Guardado optimista instantáneo
        if (typeof saveAttendanceRecords === 'function') {
            saveAttendanceRecords(false, null, recordKey);
        }

        // Notificaciones sensoriales
        playAttendanceBeep(true);
        if (typeof navigator !== 'undefined' && navigator.vibrate) navigator.vibrate([70, 40, 70]);

        updateLastScannedBanner(student, 'success', `Presente marcado: Día ${targetDay}`);
        if (typeof showToast === 'function') showToast(`Asistencia registrada: ${sFullName}`, 'success');
    }

    // Refrescar grilla visual si estamos viendo este módulo
    if (typeof document !== 'undefined' && document.getElementById('view-attendance')) {
        if (typeof loadAttendanceList === 'function') loadAttendanceList();
        setTimeout(() => {
            const row = document.getElementById(`att-row-${student.id}`);
            if (row) {
                row.scrollIntoView({ behavior: 'smooth', block: 'center' });
                row.style.transition = 'background-color 0.4s ease';
                row.style.backgroundColor = '#dcfce7';
                setTimeout(() => {
                    row.style.backgroundColor = '';
                }, 2000);
            }
        }, 80);
    }

    return true;
}

async function openAttendanceCameraScanner() {
    const modal = document.getElementById('attendanceCameraModal');
    if (modal) modal.style.display = 'flex';

    const statusMsg = document.getElementById('attendanceCameraStatusMsg');
    const video = document.getElementById('attendanceScannerVideo');

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        if (statusMsg) statusMsg.textContent = 'Tu navegador no soporta cámara directa. Usa lector láser o ingreso manual.';
        if (typeof showToast === 'function') showToast('Navegador no soporta cámara directa.', 'warning');
        return;
    }

    if (statusMsg) statusMsg.textContent = 'Iniciando cámara trasera...';

    try {
        if (_attendanceCameraStream) {
            _attendanceCameraStream.getTracks().forEach(t => t.stop());
            _attendanceCameraStream = null;
        }

        const constraints = {
            audio: false,
            video: {
                facingMode: { ideal: _attendanceCameraFacing },
                width: { ideal: 1280 },
                height: { ideal: 720 }
            }
        };

        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        _attendanceCameraStream = stream;
        if (video) {
            video.srcObject = stream;
            await video.play();
        }

        if (statusMsg) statusMsg.textContent = 'Cámara lista. Apunte el carné hacia el recuadro verde.';

        _startAttendanceBarcodeLoop();
    } catch (err) {
        console.error('Error al abrir cámara para asistencia:', err);
        if (statusMsg) statusMsg.textContent = 'Permiso denegado o cámara no disponible. Ingrese el código manualmente.';
        if (typeof showToast === 'function') showToast('No se pudo acceder a la cámara. Revisa los permisos.', 'danger');
    }
}

function closeAttendanceCameraScanner() {
    if (_attendanceScanAnimId) {
        cancelAnimationFrame(_attendanceScanAnimId);
        _attendanceScanAnimId = null;
    }
    if (_attendanceCameraStream) {
        _attendanceCameraStream.getTracks().forEach(t => t.stop());
        _attendanceCameraStream = null;
    }
    const video = document.getElementById('attendanceScannerVideo');
    if (video) video.srcObject = null;

    const modal = document.getElementById('attendanceCameraModal');
    if (modal) modal.style.display = 'none';

    focusAttendanceBarcodeInput();
}

async function switchAttendanceCameraFacing() {
    _attendanceCameraFacing = (_attendanceCameraFacing === 'environment') ? 'user' : 'environment';
    const textEl = document.getElementById('attendanceCurrentFacingText');
    if (textEl) textEl.textContent = (_attendanceCameraFacing === 'environment') ? 'Trasera' : 'Frontal';
    await openAttendanceCameraScanner();
}

function _startAttendanceBarcodeLoop() {
    if (_attendanceScanAnimId) cancelAnimationFrame(_attendanceScanAnimId);

    const video = document.getElementById('attendanceScannerVideo');

    let detector = null;
    if (typeof window !== 'undefined' && 'BarcodeDetector' in window) {
        try {
            detector = new window.BarcodeDetector({
                formats: ['qr_code', 'code_128', 'code_39', 'ean_13', 'ean_8', 'codabar', 'upc_a', 'upc_e', 'data_matrix']
            });
        } catch(e) {
            console.warn('BarcodeDetector format init error:', e);
        }
    }

    async function scanFrame() {
        if (!_attendanceCameraStream || !video || video.readyState < 2) {
            _attendanceScanAnimId = requestAnimationFrame(scanFrame);
            return;
        }

        const now = Date.now();
        if (now - _attendanceLastScanTime > 150) {
            _attendanceLastScanTime = now;

            if (detector) {
                try {
                    const barcodes = await detector.detect(video);
                    if (barcodes && barcodes.length > 0) {
                        const rawCode = barcodes[0].rawValue;
                        if (rawCode && rawCode !== _attendanceLastScannedStudentCode) {
                            _attendanceLastScannedStudentCode = rawCode;
                            registerAttendanceByCode(rawCode);
                            setTimeout(() => {
                                if (_attendanceLastScannedStudentCode === rawCode) {
                                    _attendanceLastScannedStudentCode = '';
                                }
                            }, 2500);
                        }
                    }
                } catch(detErr) {
                    // Ignorar frames no legibles
                }
            }
        }

        _attendanceScanAnimId = requestAnimationFrame(scanFrame);
    }

    _attendanceScanAnimId = requestAnimationFrame(scanFrame);
}

if (typeof window !== 'undefined') {
    window.focusAttendanceBarcodeInput = focusAttendanceBarcodeInput;
    window.handleAttendanceBarcodeInput = handleAttendanceBarcodeInput;
    window.submitAttendanceManualBarcodeInput = submitAttendanceManualBarcodeInput;
    window.submitAttendanceCameraManualInput = submitAttendanceCameraManualInput;
    window.registerAttendanceByCode = registerAttendanceByCode;
    window.openAttendanceCameraScanner = openAttendanceCameraScanner;
    window.closeAttendanceCameraScanner = closeAttendanceCameraScanner;
    window.switchAttendanceCameraFacing = switchAttendanceCameraFacing;
    window.playAttendanceBeep = playAttendanceBeep;
    window.updateLastScannedBanner = updateLastScannedBanner;
}

function printAttendanceOfficialSheet(forcedIsBlank = null) {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');
    const teacherSelect = document.getElementById('attendanceTeacherSelect');

    const gradeCode = gradeSelect ? gradeSelect.value : '';
    const gradeText = gradeSelect && gradeSelect.selectedIndex >= 0 ? gradeSelect.options[gradeSelect.selectedIndex].text : 'Grado y Sección';
    const month = parseInt(monthSelect ? monthSelect.value : '8') || 8;
    const courseId = courseSelect ? courseSelect.value : 'GENERAL';

    const currentRole = (STATE.currentRole || (STATE.currentUser && STATE.currentUser.role) || '').toLowerCase();
    const isAuditRole = ['admin', 'super_usuario', 'director', 'direccion', 'secretaria', 'profesor_auxiliar', 'auxiliar', 'auxiliatura'].includes(currentRole);
    const isDocente = (currentRole === 'docente');

    if (isDocente && !isAuditRole) {
        const currentUser = STATE.currentUser || (STATE.users || [])[0];
        const myClasses = (STATE.pensum || []).filter(p => isCourseAssignedToTeacher(p, currentUser));
        if (!myClasses.some(p => p.id === courseId)) {
            if (typeof showToast === 'function') {
                showToast("🔒 Acceso Restringido: Solo puede imprimir la asistencia de sus cátedras asignadas.", "warning");
            }
            return;
        }
    }
    const year = 2026;
    const daysInMonth = new Date(year, month, 0).getDate();
    const dayNames = ['D', 'L', 'M', 'M', 'J', 'V', 'S'];

    const monthNames = {
        1: 'Enero', 2: 'Febrero', 3: 'Marzo', 4: 'Abril', 5: 'Mayo', 6: 'Junio',
        7: 'Julio', 8: 'Agosto', 9: 'Septiembre', 10: 'Octubre', 11: 'Noviembre', 12: 'Diciembre'
    };

    // Determinar asignatura y catedrático
    let subjectTitle = 'Control General de Asistencia (Jornada Diaria)';
    let teacherName = 'Docente Titular';

    if (courseId && courseId !== 'GENERAL') {
        const targetPensum = (STATE.pensum || []).find(p => p.id === courseId);
        if (targetPensum) {
            subjectTitle = `${targetPensum.subject} (${targetPensum.grade} "${targetPensum.section || 'A'}")`;
            teacherName = targetPensum.teacher || (STATE.currentUser ? STATE.currentUser.name : 'Catedrático');
        }
    } else if (teacherSelect && teacherSelect.value) {
        const teacherObj = (STATE.users || []).find(u => u.id === teacherSelect.value);
        if (teacherObj) teacherName = teacherObj.name;
    } else if (STATE.currentUser) {
        teacherName = STATE.currentUser.name;
    }

    // Filtrar estudiantes con coincidencia perfecta de grado y sección
    const qGradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const currentCourseObj = (courseId && courseId !== 'GENERAL') ? (STATE.pensum || []).find(p => p.id === courseId) : null;
    const students = getAttendanceStudents(gradeCode, currentCourseObj);

    if (students.length === 0) {
        showToast("No hay estudiantes registrados en este grado para generar la planilla de asistencia.", "warning");
        return;
    }

    const recordKey = getAttendanceRecordKey(gradeCode, month, courseId);
    const monthData = getConsolidatedAttendanceMonthData(gradeCode, month, courseId);

    const h = STATE.schoolHeader || { schoolName: 'Escuela Nacional de Ciencias Comerciales', code: 'ENCCO Jutiapa', location: 'Jutiapa' };
    const capDate = new Date().toLocaleDateString('es-GT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

    // Encabezado de días
    let thDaysHtml = '';
    for (let day = 1; day <= daysInMonth; day++) {
        const dObj = new Date(year, month - 1, day);
        const dayOfWeek = dayNames[dObj.getDay()];
        const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
        const weekendClass = isWeekend ? 'background:#e2e8f0; color:#64748b;' : '';
        thDaysHtml += `
            <th style="width:20px; text-align:center; font-size:7.5pt; border:1px solid #0f172a; padding:3px 1px; ${weekendClass}">
                <div>${dayOfWeek}</div>
                <div>${day}</div>
            </th>
        `;
    }

    let tbodyRows = '';
    let dayPresentTotals = new Array(daysInMonth + 1).fill(0);
    let dayAbsentTotals = new Array(daysInMonth + 1).fill(0);

    students.forEach((s, idx) => {
        const sRecords = monthData[s.id] || {};
        let pCount = 0, aCount = 0, jCount = 0, tCount = 0;
        let dayCells = '';
        const attBim = (typeof getBimestreFromMonth === 'function') ? getBimestreFromMonth(month) : 1;
        const isRet = (s.status === 'Retirado' || s.status === 'Inactivo') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(s, attBim) : true);
        const isAus = (s.status === 'Ausente') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(s, attBim) : true);
        const isExon = !isRet && !isAus && (typeof isStudentExonerated === 'function' ? isStudentExonerated(s, attBim) : false);
        const studentFullName = formatStudentDisplayName(s, 'lastFirst').toUpperCase();

        for (let day = 1; day <= daysInMonth; day++) {
            const dObj = new Date(year, month - 1, day);
            const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);

            if (isWeekend) {
                dayCells += `<td style="background:#e2e8f0; text-align:center; color:#94a3b8; font-size:8pt; border:1px solid #64748b;">-</td>`;
            } else if (isRet || isAus) {
                dayCells += `<td style="background:#f8fafc; text-align:center; color:#94a3b8; font-size:8pt; font-weight:bold; border:1px solid #64748b;">—</td>`;
            } else if (isExon) {
                dayCells += `<td style="background:#f0f9ff; text-align:center; color:#0369a1; font-size:8pt; font-weight:bold; border:1px solid #64748b;">—</td>`;
            } else if (forcedIsBlank === true) {
                dayCells += `<td style="background:#ffffff; color:#000000; text-align:center; font-weight:bold; font-size:8pt; border:1px solid #64748b;">&nbsp;</td>`;
            } else {
                let rawVal = sRecords[day];
                let val = (rawVal !== undefined && rawVal !== null && rawVal !== '') ? rawVal : '';

                let bg = '#ffffff';
                let fg = '#000000';
                if (val === 'P') { bg = '#dcfce7'; fg = '#15803d'; pCount++; dayPresentTotals[day]++; }
                else if (val === 'A') { bg = '#fee2e2'; fg = '#b91c1c'; aCount++; dayAbsentTotals[day]++; }
                else if (val === 'J') { bg = '#ffedd5'; fg = '#c2410c'; jCount++; }
                else if (val === 'T') { bg = '#e0f2fe'; fg = '#0369a1'; tCount++; }

                dayCells += `<td style="background:${bg}; color:${fg}; text-align:center; font-weight:bold; font-size:8pt; border:1px solid #64748b;">${val}</td>`;
            }
        }

        const totalLogged = (isRet || isAus || forcedIsBlank === true) ? 0 : (pCount + aCount + jCount + tCount);
        const pct = (!isRet && !isAus && forcedIsBlank !== true && totalLogged > 0) ? Math.round(((pCount + jCount + (tCount * 0.5)) / totalLogged) * 100) : 100;
        const retTag = isRet ? ' <span style="color:#b91c1c; font-weight:900; font-size:7.5pt;">[RETIRADO]</span>' : '';
        const ausTag = isAus ? ' <span style="color:#d97706; font-weight:900; font-size:7.5pt;">[AUSENTE]</span>' : '';
        const exonTag = isExon ? ` <span style="color:#0284c7; font-weight:900; font-size:7.5pt;">[EXONERADO B${attBim}]</span>` : '';

        const printRowBg = isRet ? 'background-color:#fef2f2; color:#64748b;' : (isAus ? 'background-color:#fffbeb; color:#92400e;' : (isExon ? 'background-color:#f0f9ff; color:#0369a1;' : (idx % 2 === 1 ? 'background-color:#f8fafc;' : '')));

        const statPDisplay = (isRet || isAus || forcedIsBlank === true) ? '—' : pCount;
        const statADisplay = (isRet || isAus || forcedIsBlank === true) ? '—' : aCount;
        const statJDisplay = (isRet || isAus || forcedIsBlank === true) ? '—' : jCount;
        const statTDisplay = (isRet || isAus || forcedIsBlank === true) ? '—' : tCount;
        const statPctDisplay = forcedIsBlank === true ? '—' : (isRet ? '<span style="color:#b91c1c; font-weight:800; font-size:7.5pt;">RET.</span>' : (isAus ? '<span style="color:#d97706; font-weight:800; font-size:7.5pt;">AUS.</span>' : (isExon ? '<span style="color:#0369a1; font-weight:800; font-size:7.5pt;">EXON.</span>' : pct + '%')));

        tbodyRows += `
            <tr style="${printRowBg}">
                <td style="text-align:center; font-weight:bold; border:1px solid #64748b; padding:4px 2px;">${idx + 1}</td>
                <td style="font-family:monospace; font-weight:bold; border:1px solid #64748b; padding:4px 4px; font-size:7.8pt;">${s.personalCode || s.cui || s.carne || 'S/C'}</td>
                <td style="font-weight:bold; border:1px solid #64748b; padding:4px 6px; white-space:nowrap; font-size:8.2pt;">${studentFullName}${retTag}${ausTag}${exonTag}</td>
                ${dayCells}
                <td style="text-align:center; font-weight:bold; color:#15803d; border:1px solid #64748b; font-size:8pt;">${statPDisplay}</td>
                <td style="text-align:center; font-weight:bold; color:#b91c1c; border:1px solid #64748b; font-size:8pt;">${statADisplay}</td>
                <td style="text-align:center; font-weight:bold; color:#c2410c; border:1px solid #64748b; font-size:8pt;">${statJDisplay}</td>
                <td style="text-align:center; font-weight:bold; color:#0369a1; border:1px solid #64748b; font-size:8pt;">${statTDisplay}</td>
                <td style="text-align:center; font-weight:bold; background:${isRet ? '#fee2e2' : (isAus ? '#fef3c7' : '#f1f5f9')}; border:1px solid #64748b; font-size:8.5pt;">${statPctDisplay}</td>
            </tr>
        `;
    });

    const grandSumP = dayPresentTotals.reduce((a, b) => a + b, 0);
    const grandSumA = dayAbsentTotals.reduce((a, b) => a + b, 0);

    const bannerDocTitle = forcedIsBlank === true
        ? 'PLANILLA OFICIAL DE ASISTENCIA (EN BLANCO)'
        : 'PLANILLA OFICIAL DE ASISTENCIA';

    const fullDocHtml = `
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <title>Planilla Oficial de Asistencia - ${gradeText}</title>
            <style>
                @page { size: 13in 8.5in landscape; margin: 6mm 8mm; }
                body { font-family: 'Segoe UI', Arial, sans-serif; color: #000; background: #fff; line-height: 1.2; font-size: 8pt; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
                
                .official-header { border: 1.5px solid #15803d; border-radius: 4px; overflow: hidden; margin-bottom: 8px; }
                .top-banner { background: #15803d !important; color: #fff; display: flex; align-items: center; justify-content: space-between; padding: 6px 14px; }
                .top-banner img { height: 38px; width: auto; }
                .top-banner h1 { margin: 0; font-size: 13pt; font-weight: 900; color: #fff; text-transform: uppercase; }
                .sub-tag { font-size: 8pt; font-weight: 700; color: #bbf7d0; }
                
                .meta-bar { background: #f0fdf4; border-top: 1px solid #166534; padding: 4px 14px; display: flex; justify-content: space-between; font-size: 8.5pt; font-weight: 700; color: #166534; }
                
                .stat-table { width: 100%; border-collapse: collapse; margin-top: 6px; border: 1.5px solid #0f172a; font-size: 8pt; }
                .stat-table th { background: #15803d !important; color: #ffffff !important; border: 1px solid #0f172a; padding: 4px 2px; text-align: center; font-weight: 900; }
                
                .signatures { margin-top: 24px; display: flex; justify-content: space-around; text-align: center; }
                .sig-box { width: 220px; border-top: 1.5px solid #000; padding-top: 3px; font-size: 8pt; font-weight: bold; }
            </style>
        </head>
        <body>
            <div class="official-header">
                <div class="top-banner">
                    <div style="display:flex; align-items:center; gap:10px;">
                        <img src="logo.png" alt="Logo ENCCO" onerror="this.src='portada-comercio-principal.webp'">
                        <div>
                            <h1>${h.schoolName || 'ESCUELA NACIONAL DE CIENCIAS COMERCIALES'}</h1>
                            <div class="sub-tag">JUTIAPA — FUNDADA EN 1970 | CICLO ESCOLAR ${STATE.activeCycle || '2026'}</div>
                        </div>
                    </div>
                    <div style="text-align:right;">
                        <div style="font-size:11pt; font-weight:900; text-transform:uppercase;">${bannerDocTitle}</div>
                        <div style="font-size:8pt; color:#bbf7d0;">MES: ${monthNames[month].toUpperCase()} ${year}</div>
                    </div>
                </div>
                <div class="meta-bar">
                    <div><strong>Grado y Sección:</strong> ${gradeText}</div>
                    <div><strong>Asignatura:</strong> ${subjectTitle}</div>
                    <div><strong>Catedrático:</strong> ${teacherName}</div>
                    <div><strong>Total Alumnos:</strong> ${students.length}</div>
                </div>
            </div>

            <table class="stat-table">
                <thead>
                    <tr>
                        <th style="width:25px;" rowspan="2">No.</th>
                        <th style="width:75px;" rowspan="2">Código Personal</th>
                        <th style="text-align:left; padding-left:6px;" rowspan="2">Apellidos y Nombres</th>
                        <th colspan="${daysInMonth}">DÍAS DEL MES DE ${monthNames[month].toUpperCase()}</th>
                        <th style="width:24px;" rowspan="2">P</th>
                        <th style="width:24px;" rowspan="2">A</th>
                        <th style="width:24px;" rowspan="2">J</th>
                        <th style="width:24px;" rowspan="2">T</th>
                        <th style="width:38px;" rowspan="2">% Asist</th>
                    </tr>
                    <tr>
                        ${thDaysHtml}
                    </tr>
                </thead>
                <tbody>
                    ${tbodyRows}
                    <tr style="background:#dcfce7; font-weight:900; font-size:8.5pt;">
                        <td colspan="3" style="text-align:right; padding-right:8px; border:1px solid #0f172a;">TOTAL ASISTENCIAS DIARIAS (P):</td>
                        ${dayPresentTotals.slice(1).map((tot, idx) => {
                            const dObj = new Date(year, month - 1, idx + 1);
                            const isWk = (dObj.getDay() === 0 || dObj.getDay() === 6);
                            return `<td style="text-align:center; border:1px solid #0f172a; ${isWk ? 'background:#cbd5e1;' : ''}">${isWk ? '-' : (forcedIsBlank === true ? '&nbsp;' : tot)}</td>`;
                        }).join('')}
                        <td style="text-align:center; background:#15803d; color:#fff; border:1px solid #0f172a;">${forcedIsBlank === true ? '—' : grandSumP}</td>
                        <td style="text-align:center; background:#b91c1c; color:#fff; border:1px solid #0f172a;">${forcedIsBlank === true ? '—' : grandSumA}</td>
                        <td colspan="3" style="text-align:center; background:#0f172a; color:#fff; border:1px solid #0f172a;">${students.length} Alumnos</td>
                    </tr>
                </tbody>
            </table>

            <div class="signatures">
                <div class="sig-box">
                    ${teacherName}<br>
                    Catedrático(a) Titular
                </div>
                <div class="sig-box">
                    Comisión de Asistencia y Disciplina<br>
                    Vo.Bo. Control de Plantel
                </div>
                <div class="sig-box">
                    Licda. Director(a) ENCCO<br>
                    Sello Oficial Institucional
                </div>
            </div>
        </body>
        </html>
    `;

    const printWin = (typeof window !== 'undefined' && window.open) ? window.open('', '_blank') : null;
    if (printWin) {
        printWin.document.write(fullDocHtml);
        printWin.document.close();
        setTimeout(() => {
            try {
                printWin.focus();
                printWin.print();
            } catch(e) {}
        }, 400);
    } else {
        renderAndShowPrintDocument(`Planilla Oficial de Asistencia - ${gradeText}`, fullDocHtml, 'landscape');
    }
}

function exportAttendanceOfficialExcel() {
    const gradeSelect = document.getElementById('attendanceGradeSelect');
    const monthSelect = document.getElementById('attendanceMonthSelect');
    const courseSelect = document.getElementById('attendanceCourseSelect');

    const gradeCode = gradeSelect ? gradeSelect.value : '';
    const gradeText = gradeSelect && gradeSelect.selectedIndex >= 0 ? gradeSelect.options[gradeSelect.selectedIndex].text : 'Grado';
    const month = parseInt(monthSelect ? monthSelect.value : '8') || 8;
    const courseId = courseSelect ? courseSelect.value : 'GENERAL';

    const currentRole = (STATE.currentRole || (STATE.currentUser && STATE.currentUser.role) || '').toLowerCase();
    const isAuditRole = ['admin', 'super_usuario', 'director', 'direccion', 'secretaria', 'profesor_auxiliar', 'auxiliar', 'auxiliatura'].includes(currentRole);
    const isDocente = (currentRole === 'docente');

    if (isDocente && !isAuditRole) {
        const currentUser = STATE.currentUser || (STATE.users || [])[0];
        const myClasses = (STATE.pensum || []).filter(p => isCourseAssignedToTeacher(p, currentUser));
        if (!myClasses.some(p => p.id === courseId)) {
            if (typeof showToast === 'function') {
                showToast("🔒 Acceso Restringido: Solo puede exportar la asistencia de sus cátedras asignadas.", "warning");
            }
            return;
        }
    }
    const year = 2026;
    const daysInMonth = new Date(year, month, 0).getDate();

    const qGradeObj = (STATE.gradesList || []).find(g => g.code === gradeCode || g.id === gradeCode || g.name === gradeCode);
    const currentCourseObj = (courseId && courseId !== 'GENERAL') ? (STATE.pensum || []).find(p => p.id === courseId) : null;
    const students = getAttendanceStudents(gradeCode, currentCourseObj);

    if (students.length === 0) {
        showToast("No hay estudiantes para exportar.", "warning");
        return;
    }

    const recordKey = getAttendanceRecordKey(gradeCode, month, courseId);
    const monthData = getConsolidatedAttendanceMonthData(gradeCode, month, courseId);

    let csv = `\uFEFFNo,Codigo_Personal,Apellidos y Nombres,`;
    for (let d = 1; d <= daysInMonth; d++) csv += `Dia_${d},`;
    csv += `Total_P,Total_A,Total_J,Total_T,Porcentaje_Asistencia\n`;

    const attBim = (typeof getBimestreFromMonth === 'function') ? getBimestreFromMonth(month) : 1;

    students.forEach((s, idx) => {
        const sRecords = monthData[s.id] || {};
        let p = 0, a = 0, j = 0, t = 0;
        const isRet = (s.status === 'Retirado' || s.status === 'Inactivo') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(s, attBim) : true);
        const isAus = (s.status === 'Ausente') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(s, attBim) : true);
        const isExon = !isRet && !isAus && (typeof isStudentExonerated === 'function' ? isStudentExonerated(s, attBim) : false);
        let sName = formatStudentDisplayName(s, 'lastFirst');
        if (isRet) sName += ' [RETIRADO]';
        else if (isAus) sName += ' [AUSENTE]';
        else if (isExon) sName += ` [EXONERADO B${attBim}]`;

        let line = `${idx + 1},"${s.personalCode || s.cui || s.carne || ''}","${sName}",`;

        for (let d = 1; d <= daysInMonth; d++) {
            const dObj = new Date(year, month - 1, d);
            const isWeekend = (dObj.getDay() === 0 || dObj.getDay() === 6);
            if (isWeekend) {
                line += `-,`;
            } else {
                let val = sRecords[d] || '';
                if (val === 'P') p++;
                else if (val === 'A') a++;
                else if (val === 'J') j++;
                else if (val === 'T') t++;
                line += `${val},`;
            }
        }
        const tot = p + a + j + t;
        const pct = tot > 0 ? Math.round(((p + j + (t * 0.5)) / tot) * 100) : 100;
        line += `${p},${a},${j},${t},${pct}%\n`;
        csv += line;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Asistencia_${gradeCode}_Mes_${month}_2026.csv`;
    link.click();
    showToast("Planilla descargada exitosamente en formato CSV / Excel.", "success");
}

function exportAttendanceToCSV() { exportAttendanceOfficialExcel(); }
function printAttendanceExcelSheet() { printAttendanceOfficialSheet(); }

