// ==========================================================================
// 11. LLAMADAS DE ATENCIÓN DISCIPLINARIAS (ADMIN PUEDE ELIMINAR CUALQUIER REPORTE)
// ==========================================================================

// ──────────────────────────────────────────────────────────────────────────
// ⚖️ CONTROLADOR INTEGRAL DE DISCIPLINA, REPORTES DOCENTES Y RESOLUCIONES
// ──────────────────────────────────────────────────────────────────────────

function checkDisciplineCreatePermission() {
    if (typeof isSuperUserRole === 'function' && isSuperUserRole()) return true;
    if (typeof isDirectorRole === 'function' && isDirectorRole()) return true;
    const role = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    // Docentes, auxiliares, directores y administradores pueden ingresar reportes
    return ['admin', 'director', 'super_usuario', 'superadmin', 'direccion', 'secretaria', 'profesor_auxiliar', 'docente'].includes(role);
}
window.checkDisciplineCreatePermission = checkDisciplineCreatePermission;

function checkDisciplineResolvePermission() {
    if (typeof isSuperUserRole === 'function' && isSuperUserRole()) return true;
    if (typeof isDirectorRole === 'function' && isDirectorRole()) return true;
    const role = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    // Auxiliar, director y admin pueden dictaminar y resolver faltas
    return ['admin', 'director', 'super_usuario', 'superadmin', 'direccion', 'profesor_auxiliar'].includes(role);
}
window.checkDisciplineResolvePermission = checkDisciplineResolvePermission;

function checkDisciplineDirectorPermission(targetRole = null) {
    if (typeof isSuperUserRole === 'function' && isSuperUserRole(targetRole)) return true;
    if (typeof isDirectorRole === 'function' && isDirectorRole(targetRole)) return true;
    const rawRole = targetRole || 
                    (window.EnccoAuthStore && typeof window.EnccoAuthStore.getRole === 'function' ? window.EnccoAuthStore.getRole() : null) ||
                    (window.STATE ? STATE.currentRole : null) || 
                    (window.STATE && STATE.currentUser ? STATE.currentUser.role : null) ||
                    (typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('ENCCO_AUTH_ROLE') : null) ||
                    (typeof localStorage !== 'undefined' ? localStorage.getItem('ENCCO_AUTH_ROLE') : null) ||
                    'docente';
    const role = String(rawRole).trim().toLowerCase();

    // 1. Roles institucionales con facultad ejecutiva de Dirección y Administración
    if (['admin', 'super_usuario', 'director', 'directora', 'direccion'].includes(role)) {
        return true;
    }

    // 2. Verificar rol en el usuario autenticado actual
    if (window.STATE && STATE.currentUser && STATE.currentUser.role) {
        const uRole = String(STATE.currentUser.role).trim().toLowerCase();
        if (['admin', 'super_usuario', 'director', 'directora', 'direccion'].includes(uRole)) {
            return true;
        }
    }

    // 3. Verificación mediante el sistema de Roles y Permisos (RBAC)
    if (typeof hasRolePermission === 'function') {
        if (hasRolePermission('discipline_delete', role) || hasRolePermission('discipline_admin', role)) {
            return true;
        }
    }

    if (typeof canRoleModify === 'function' && canRoleModify('discipline', role)) {
        // Excluir específicamente auxiliares y docentes de la facultad de eliminar registros disciplinarios
        if (role !== 'profesor_auxiliar' && role !== 'docente' && role !== 'estudiante') {
            return true;
        }
    }

    return false;
}
window.checkDisciplineDirectorPermission = checkDisciplineDirectorPermission;

// ==========================================================================
// ⚠️ GESTOR DINÁMICO DE REPORTES DISCIPLINARIOS Y LLAMADAS DE ATENCIÓN (V75)
// ==========================================================================

function populateDisciplineGradeFilter() {
    const gradeSelect = document.getElementById('discGradeFilter');
    if (!gradeSelect) return;

    const isDocente = (STATE.currentRole === 'docente');
    let gradesList = [];
    if (isDocente && typeof getTeacherAssignedGradesList === 'function') {
        gradesList = getTeacherAssignedGradesList(STATE.currentUser);
    } else {
        gradesList = Array.isArray(STATE.gradesList) && STATE.gradesList.length > 0 
            ? STATE.gradesList 
            : [
                { code: '4to Perito Contador', name: '4to Perito Contador' },
                { code: '5to Perito Contador', name: '5to Perito Contador' },
                { code: '6to Perito Contador', name: '6to Perito Contador' }
            ];
    }

    const currentVal = gradeSelect.value || 'ALL';
    let optionsHtml = isDocente ? '<option value="ALL">-- Mis Grados Asignados --</option>' : '<option value="ALL">-- Todos los Grados --</option>';
    gradesList.forEach(g => {
        const val = g.name || g.code;
        const secLabel = g.section ? ` - ${g.section}` : '';
        optionsHtml += `<option value="${val}">${g.name} (${g.code})${secLabel}</option>`;
    });

    gradeSelect.innerHTML = optionsHtml;
    if (gradesList.some(g => (g.name || g.code) === currentVal)) {
        gradeSelect.value = currentVal;
    }
}

function clearDisciplineStudentSearch() {
    const input = document.getElementById('discStudentSearchInput');
    const btn = document.getElementById('discClearSearchBtn');
    if (input) {
        input.value = '';
        input.focus();
    }
    if (btn) btn.style.display = 'none';
    filterDisciplineStudentList();
}

function filterDisciplineStudentList() {
    const gradeFilter = (document.getElementById('discGradeFilter')?.value || 'ALL').trim();
    const sectionFilter = (document.getElementById('discSectionFilter')?.value || 'ALL').trim().toUpperCase();
    const searchInput = document.getElementById('discStudentSearchInput');
    const q = (searchInput?.value || '').trim().toLowerCase();
    const clearBtn = document.getElementById('discClearSearchBtn');
    if (clearBtn) clearBtn.style.display = q ? 'block' : 'none';

    const select = document.getElementById('discStudentSelect');
    const badge = document.getElementById('discStudentCountBadge');
    if (!select) return;

    const isDocente = (STATE.currentRole === 'docente');
    const baseStudents = (isDocente && typeof getAuthorizedStudents === 'function')
        ? getAuthorizedStudents(STATE.currentUser, STATE.currentRole)
        : (STATE.students || []);

    let students = baseStudents.filter(s => isStudentActive(s));

    // Filtro de grado
    if (gradeFilter && gradeFilter !== 'ALL') {
        const gfLower = gradeFilter.toLowerCase();
        students = students.filter(s => {
            const sg = (s.grade || s.gradeCode || '').toLowerCase();
            return sg === gfLower || sg.includes(gfLower) || gfLower.includes(sg);
        });
    }

    // Filtro de sección
    if (sectionFilter && sectionFilter !== 'ALL') {
        students = students.filter(s => {
            const sec = (s.section || '').toUpperCase().trim();
            return sec === sectionFilter || sec === `SECCIÓN ${sectionFilter}` || sec === `SECCION ${sectionFilter}` || sec.endsWith(sectionFilter);
        });
    }

    // Búsqueda en vivo por nombre, apellido, carné o cui
    if (q) {
        students = students.filter(s => {
            const fullName = `${s.lastName || ''} ${s.firstName || ''} ${s.name || ''}`.toLowerCase();
            const carne = (s.carne || '').toLowerCase();
            const cui = (s.cui || '').toLowerCase();
            return fullName.includes(q) || carne.includes(q) || cui.includes(q);
        });
    }

    // Ordenar alfabéticamente por apellidos
    students.sort((a, b) => {
        const nameA = formatStudentDisplayName(a, 'lastFirst');
        const nameB = formatStudentDisplayName(b, 'lastFirst');
        return nameA.localeCompare(nameB, 'es', { sensitivity: 'base' });
    });

    if (badge) {
        badge.textContent = `${students.length} alumno(s) encontrado(s)`;
        badge.style.background = students.length > 0 ? '#e0f2fe' : '#fee2e2';
        badge.style.color = students.length > 0 ? '#0369a1' : '#dc2626';
    }

    if (students.length === 0) {
        select.innerHTML = '<option value="">⚠️ No hay estudiantes con este filtro</option>';
        select.disabled = true;
    } else {
        select.disabled = false;
        select.innerHTML = `<option value="">-- Seleccione Estudiante (${students.length} disponibles) --</option>` + students.map(s => {
            const fullName = formatStudentDisplayName(s, 'lastFirst');
            const gradeDisplay = s.grade || s.gradeCode || 'Grado Oficial';
            const secDisplay = (s.section || 'A').replace(/secci[oó]n\s*/i, '');
            return `<option value="${s.id}">${escapeHtml(fullName)} • [${gradeDisplay} - Sec ${secDisplay}] (Carné: ${s.carne || 'S/C'})</option>`;
        }).join('');

        // Si solo hay un estudiante tras la búsqueda, seleccionarlo automáticamente
        if (students.length === 1 && q) {
            select.value = students[0].id;
        }
    }
}

function openDisciplineModal() {
    if (!checkDisciplineCreatePermission()) {
        showToast('No tiene permisos para registrar reportes disciplinarios.', 'warning');
        return;
    }

    const form = document.querySelector('#disciplineModal form');
    if (form) form.reset();

    // 1. Poblar y reiniciar filtros dinámicos
    populateDisciplineGradeFilter();
    const gradeSelect = document.getElementById('discGradeFilter');
    const secSelect = document.getElementById('discSectionFilter');
    const searchInput = document.getElementById('discStudentSearchInput');

    if (gradeSelect) gradeSelect.value = 'ALL';
    if (secSelect) secSelect.value = 'ALL';
    if (searchInput) searchInput.value = '';

    // 2. Filtrar lista de estudiantes
    filterDisciplineStudentList();

    // 3. Fecha actual por defecto si existe campo
    const dateInput = document.getElementById('discDate');
    if (dateInput) {
        dateInput.value = new Date().toISOString().split('T')[0];
    }

    showModalById('disciplineModal');
}

function closeDisciplineModal() {
    const modal = document.getElementById('disciplineModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function openDisciplineModalForStudent(studentId) {
    if (!studentId) studentId = STATE.selectedStudentId;
    closeStudentProfileModal();
    openDisciplineModal();
    
    if (studentId) {
        const s = (STATE.students || []).find(x => x.id === studentId);
        if (s) {
            const gradeSelect = document.getElementById('discGradeFilter');
            const secSelect = document.getElementById('discSectionFilter');
            if (gradeSelect && s.grade) {
                // Ajustar al grado del alumno
                Array.from(gradeSelect.options).forEach(opt => {
                    if (opt.value && s.grade.toLowerCase().includes(opt.value.toLowerCase())) {
                        gradeSelect.value = opt.value;
                    }
                });
            }
            if (secSelect && s.section) {
                const cleanSec = s.section.replace(/secci[oó]n\s*/i, '').trim().toUpperCase();
                secSelect.value = cleanSec || 'ALL';
            }
            filterDisciplineStudentList();
        }

        setTimeout(() => {
            const studentSelect = document.getElementById('discStudentSelect');
            if (studentSelect && studentId) {
                studentSelect.value = studentId;
            }
        }, 100);
    }
}



function closeDisciplineResolutionModal() {
    const modal = document.getElementById('disciplineResolutionModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}
window.closeDisciplineResolutionModal = closeDisciplineResolutionModal;

async function saveDisciplineForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!checkDisciplineCreatePermission()) {
        showToast('No tiene permisos para registrar reportes disciplinarios.', 'warning');
        return;
    }

    const stuSelect = document.getElementById('discStudentSelect');
    const stuId = stuSelect ? stuSelect.value : '';
    const student = (STATE.students || []).find(s => s.id === stuId);

    const severityInput = document.getElementById('discSeverity');
    const severity = severityInput ? severityInput.value : 'Leve';

    const reasonInput = document.getElementById('discReason');
    const reason = reasonInput ? reasonInput.value.trim() : '';

    const dateInput = document.getElementById('discDate');
    const date = (dateInput && dateInput.value) ? dateInput.value : new Date().toISOString().split('T')[0];

    if (!stuId || !reason) {
        showToast('Seleccione un estudiante e ingrese el motivo del reporte disciplinario.', 'warning');
        return;
    }

    // 🛡️ REGLA ESTRICTA INSTITUCIONAL: Para docentes, restringir a estudiantes de sus cátedras asignadas
    if (STATE.currentRole === 'docente' && student && typeof isStudentAssignedToTeacher === 'function' && !isStudentAssignedToTeacher(student, STATE.currentUser)) {
        showToast('Acceso denegado: No puede registrar reportes disciplinarios para estudiantes no asignados a sus cátedras.', 'error');
        return;
    }

    const stuName = student ? formatStudentDisplayName(student, 'lastFirst') : 'Estudiante';
    const grade = student ? (student.grade || student.gradeCode || 'Perito Contador') : '4to Perito Contador';
    const section = student ? (student.section || 'Sección A') : 'Sección A';
    const teacherName = STATE.currentUser ? (STATE.currentUser.name || STATE.currentUser.username) : 'Docente Catedrático';

    if (!Array.isArray(STATE.disciplineReports)) STATE.disciplineReports = [];

    const activeCycle = String((window.STATE && (window.STATE.activeCycle || window.STATE.academicCycle)) || '2026').trim();

    const newReport = {
        id: 'rep-disc-' + Date.now(),
        studentId: stuId,
        studentName: stuName,
        grade: `${grade} (${section})`,
        academicCycle: activeCycle,
        teacher: teacherName,
        teacherId: STATE.currentUser ? STATE.currentUser.id : '',
        date: date,
        severity: severity,
        reason: reason,
        status: 'Pendiente',
        actionType: 'Pendiente de Resolución por Auxiliatura',
        resolution: '',
        resolvedBy: '',
        resolvedDate: '',
        isLocked: false,
        lockedForTeacher: true
    };

    STATE.disciplineReports.unshift(newReport);
    try {
        const modular = window.FirebaseModular;
        if (modular && modular.db && typeof modular.doc === 'function' && typeof modular.setDoc === 'function') {
            await modular.setDoc(modular.doc(modular.db, 'disciplina', newReport.id), newReport, { merge: true });
        }
    } catch(fsErr) {
        console.warn("Aviso en Firestore al registrar reporte disciplinario:", fsErr);
    }

    if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
        EnccoCloudSync.syncNode('disciplineReports', STATE.disciplineReports);
    }
    if (typeof triggerInstantCloudPush === 'function') triggerInstantCloudPush();

    closeDisciplineModal();
    renderDisciplineTable();
    if (typeof renderDashboard === 'function') renderDashboard();
    const profModalDisc = document.getElementById('studentProfileModal');
    if (profModalDisc && (profModalDisc.classList.contains('active') || profModalDisc.style.display === 'flex') && STATE.selectedStudentId && typeof openStudentProfileModal === 'function') {
        openStudentProfileModal(STATE.selectedStudentId);
    }
    showToast(`Reporte disciplinario registrado correctamente. Ha sido canalizado al Profesor Auxiliar para su resolución y dictamen.`, 'success');

    // Notificación opcional inmediata por WhatsApp al padre/encargado
    if (canRoleUseWhatsApp() && typeof promptIncidentWhatsAppNotification === 'function') {
        promptIncidentWhatsAppNotification({
            studentId: stuId,
            type: 'disciplina',
            reason: `${severity}: ${reason}`,
            date: date,
            authorName: teacherName
        });
    }
}
window.saveDisciplineForm = saveDisciplineForm;

function openDisciplineResolutionModal(reportId) {
    const list = STATE.disciplineReports || STATE.discipline || [];
    const rep = list.find(r => r.id === reportId);
    if (!rep) {
        showToast('Reporte disciplinario no encontrado.', 'warning');
        return;
    }

    const currentRole = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    const isDirector = checkDisciplineDirectorPermission();
    const isAuxiliar = currentRole === 'profesor_auxiliar';
    const isStudent = currentRole === 'estudiante';
    const isDocente = !isDirector && !isAuxiliar && !isStudent;

    const idInput = document.getElementById('discResModalReportId');
    const nameEl = document.getElementById('discResModalStudentName');
    const gradeEl = document.getElementById('discResModalStudentGrade');
    const teacherEl = document.getElementById('discResModalTeacher');
    const dateEl = document.getElementById('discResModalDate');
    const reasonEl = document.getElementById('discResModalReason');
    const severityEl = document.getElementById('discResModalSeverity');

    const metaResolvedInfo = document.getElementById('discResMetaResolvedInfo');
    const resolvedByEl = document.getElementById('discResModalResolvedBy');
    const resolvedDateEl = document.getElementById('discResModalResolvedDate');

    const actionSelect = document.getElementById('discResActionType');
    const statusSelect = document.getElementById('discResStatusSelect');
    const resTextarea = document.getElementById('discResResolutionText');
    const submitBtn = document.getElementById('discResSubmitBtn') || document.querySelector('#disciplineResolutionModal button[type="submit"]');
    const unlockBtn = document.getElementById('discResDirectorUnlockBtn');
    const modalDeleteBtn = document.getElementById('discResDirectorDeleteBtn');
    if (modalDeleteBtn) {
        modalDeleteBtn.style.display = isDirector ? 'inline-block' : 'none';
    }

    if (idInput) idInput.value = rep.id;
    if (nameEl) nameEl.textContent = rep.studentName || 'Estudiante';
    if (gradeEl) gradeEl.textContent = rep.grade || 'Grado no especificado';
    if (teacherEl) teacherEl.textContent = rep.teacher || 'Docente Catedrático';
    if (dateEl) dateEl.textContent = rep.date || 'Fecha actual';
    if (reasonEl) reasonEl.textContent = rep.reason || 'Sin detalles';

    if (severityEl) {
        let badgeColor = '#eab308';
        if (rep.severity === 'Grave') badgeColor = '#ea580c';
        if (rep.severity === 'Muy Grave') badgeColor = '#dc2626';
        severityEl.innerHTML = `<span class="badge" style="background:${badgeColor}; color:#fff; font-weight:700;">Falta ${rep.severity || 'Leve'}</span>`;
    }

    // Información de auditoría de resolución
    if (metaResolvedInfo) {
        if (rep.resolvedBy || rep.resolution) {
            metaResolvedInfo.style.display = 'block';
            if (resolvedByEl) resolvedByEl.textContent = rep.resolvedBy || 'Profesor Auxiliar / Dirección';
            if (resolvedDateEl) resolvedDateEl.textContent = rep.resolvedDate || rep.date || 'Fecha registrada';
        } else {
            metaResolvedInfo.style.display = 'none';
        }
    }

    // Valores en el formulario
    if (actionSelect) {
        actionSelect.value = rep.actionType || 'Citación de Padres de Familia';
    }
    if (statusSelect) {
        statusSelect.value = rep.status || rep.resolutionStatus || 'Pendiente';
    }
    if (resTextarea) {
        resTextarea.value = rep.resolution || rep.resolutionText || '';
    }

    // Banner informativo de seguridad según el rol
    let securityBanner = document.getElementById('discResSecurityBanner');
    if (!securityBanner) {
        const bodyEl = document.querySelector('#disciplineResolutionModal .modal-body');
        if (bodyEl) {
            securityBanner = document.createElement('div');
            securityBanner.id = 'discResSecurityBanner';
            securityBanner.style.cssText = 'padding:10px 14px; border-radius:8px; margin-bottom:14px; font-size:0.83rem; font-weight:600; display:flex; align-items:center; gap:10px; line-height:1.4;';
            bodyEl.insertBefore(securityBanner, bodyEl.firstChild);
        }
    }

    const isResolvedAndLocked = (rep.status === 'Resuelto' || rep.isLocked === true) && Boolean(rep.resolution);

    // GESTIÓN DE PRIVILEGIOS Y ESTADOS
    if (isStudent || isDocente) {
        // --- 1. DOCENTE / ESTUDIANTE: Consulta de solo lectura sin posibilidad de modificar ---
        if (securityBanner) {
            securityBanner.style.background = '#eff6ff';
            securityBanner.style.border = '1px solid #bfdbfe';
            securityBanner.style.color = '#1e40af';
            securityBanner.innerHTML = isStudent
                ? '<i class="fa-solid fa-circle-info" style="font-size:1.1rem; color:#2563eb;"></i> <span><strong>Consulta de Dictamen Oficial:</strong> Vista informativa de solo lectura para el estudiante y tutores.</span>'
                : '<i class="fa-solid fa-lock" style="font-size:1.1rem; color:#2563eb;"></i> <span><strong>Consulta de Dictamen Oficial:</strong> Como catedrático puede revisar la resolución y medidas disciplinarias aplicadas. Por normativa institucional, los dictámenes no pueden ser modificados por docentes.</span>';
        }
        if (actionSelect) { actionSelect.disabled = true; actionSelect.style.backgroundColor = '#f8fafc'; }
        if (statusSelect) { statusSelect.disabled = true; statusSelect.style.backgroundColor = '#f8fafc'; }
        if (resTextarea) {
            resTextarea.disabled = true;
            resTextarea.readOnly = true;
            resTextarea.style.backgroundColor = '#f8fafc';
            resTextarea.placeholder = 'En espera de dictamen oficial emitido por Auxiliatura.';
        }
        if (submitBtn) submitBtn.style.display = 'none';
        if (unlockBtn) unlockBtn.style.display = 'none';

    } else if (isAuxiliar) {
        // --- 2. PROFESOR AUXILIAR ---
        if (isResolvedAndLocked) {
            // Caso ya resuelto y cerrado: Bloqueado. Solo Dirección puede modificar
            if (securityBanner) {
                securityBanner.style.background = '#fefce8';
                securityBanner.style.border = '1px solid #fde047';
                securityBanner.style.color = '#854d0e';
                securityBanner.innerHTML = '<i class="fa-solid fa-lock" style="font-size:1.1rem; color:#d97706;"></i> <span><strong>Caso Resuelto y Cerrado:</strong> El dictamen de esta falta disciplinaria ha sido emitido. De acuerdo a la normativa institucional, una vez ingresada la resolución, <u>únicamente la Dirección</u> puede autorizar modificaciones o reaperturas.</span>';
            }
            if (actionSelect) { actionSelect.disabled = true; actionSelect.style.backgroundColor = '#f8fafc'; }
            if (statusSelect) { statusSelect.disabled = true; statusSelect.style.backgroundColor = '#f8fafc'; }
            if (resTextarea) {
                resTextarea.disabled = true;
                resTextarea.readOnly = true;
                resTextarea.style.backgroundColor = '#f8fafc';
            }
            if (submitBtn) submitBtn.style.display = 'none';
            if (unlockBtn) unlockBtn.style.display = 'none';
        } else {
            // Caso pendiente o en proceso: Auxiliar puede dictaminar
            if (securityBanner) {
                securityBanner.style.background = '#f0fdf4';
                securityBanner.style.border = '1px solid #86efac';
                securityBanner.style.color = '#166534';
                securityBanner.innerHTML = '<i class="fa-solid fa-gavel" style="font-size:1.1rem; color:#16a34a;"></i> <span><strong>Dictamen de Auxiliatura:</strong> Seleccione la medida disciplinaria adoptada y detalle la resolución oficial para el estudiante.</span>';
            }
            if (actionSelect) { actionSelect.disabled = false; actionSelect.style.backgroundColor = '#ffffff'; }
            if (statusSelect) { statusSelect.disabled = false; statusSelect.style.backgroundColor = '#ffffff'; }
            if (resTextarea) {
                resTextarea.disabled = false;
                resTextarea.readOnly = false;
                resTextarea.style.backgroundColor = '#ffffff';
                resTextarea.placeholder = 'Detalle el dictamen, compromisos del estudiante y acuerdos con los padres de familia...';
            }
            if (submitBtn) {
                submitBtn.style.display = 'inline-block';
                submitBtn.innerHTML = '<i class="fa-solid fa-check-double"></i> Guardar Dictamen y Notificar';
            }
            if (unlockBtn) unlockBtn.style.display = 'none';
        }

    } else if (isDirector) {
        // --- 3. DIRECCIÓN Y ADMINISTRACIÓN: Máxima autoridad ---
        if (isResolvedAndLocked) {
            // Caso resuelto: Requiere desbloqueo explícito de Dirección para editar
            if (securityBanner) {
                securityBanner.style.background = '#eff6ff';
                securityBanner.style.border = '1px solid #bfdbfe';
                securityBanner.style.color = '#1e40af';
                securityBanner.innerHTML = '<i class="fa-solid fa-user-shield" style="font-size:1.1rem; color:#2563eb;"></i> <span><strong>Control de Dirección:</strong> Este caso se encuentra resuelto. Como Directivo del establecimiento, usted tiene la facultad exclusiva de autorizar modificaciones o reclasificaciones a este dictamen.</span>';
            }
            if (actionSelect) { actionSelect.disabled = true; actionSelect.style.backgroundColor = '#f8fafc'; }
            if (statusSelect) { statusSelect.disabled = true; statusSelect.style.backgroundColor = '#f8fafc'; }
            if (resTextarea) {
                resTextarea.disabled = true;
                resTextarea.readOnly = true;
                resTextarea.style.backgroundColor = '#f8fafc';
            }
            if (submitBtn) submitBtn.style.display = 'none';
            if (unlockBtn) {
                unlockBtn.style.display = 'inline-block';
                unlockBtn.innerHTML = '<i class="fa-solid fa-unlock-keyhole"></i> Permitir Modificación (Dirección)';
            }
        } else {
            // Caso pendiente: Directivo puede resolver directamente
            if (securityBanner) {
                securityBanner.style.background = '#f0fdf4';
                securityBanner.style.border = '1px solid #86efac';
                securityBanner.style.color = '#166534';
                securityBanner.innerHTML = '<i class="fa-solid fa-user-shield" style="font-size:1.1rem; color:#16a34a;"></i> <span><strong>Gestión de Dirección:</strong> Puede emitir o registrar el dictamen directamente.</span>';
            }
            if (actionSelect) { actionSelect.disabled = false; actionSelect.style.backgroundColor = '#ffffff'; }
            if (statusSelect) { statusSelect.disabled = false; statusSelect.style.backgroundColor = '#ffffff'; }
            if (resTextarea) {
                resTextarea.disabled = false;
                resTextarea.readOnly = false;
                resTextarea.style.backgroundColor = '#ffffff';
            }
            if (submitBtn) {
                submitBtn.style.display = 'inline-block';
                submitBtn.innerHTML = '<i class="fa-solid fa-check-double"></i> Guardar Resolución';
            }
            if (unlockBtn) unlockBtn.style.display = 'none';
        }
    }

    showModalById('disciplineResolutionModal');
}
window.openDisciplineResolutionModal = openDisciplineResolutionModal;

function enableDisciplineDirectorEdit() {
    if (!checkDisciplineDirectorPermission()) {
        showToast('Acceso denegado: Únicamente la Dirección puede autorizar modificaciones a dictámenes emitidos.', 'danger');
        return;
    }

    const actionSelect = document.getElementById('discResActionType');
    const statusSelect = document.getElementById('discResStatusSelect');
    const resTextarea = document.getElementById('discResResolutionText');
    const submitBtn = document.getElementById('discResSubmitBtn') || document.querySelector('#disciplineResolutionModal button[type="submit"]');
    const unlockBtn = document.getElementById('discResDirectorUnlockBtn');
    const securityBanner = document.getElementById('discResSecurityBanner');

    if (actionSelect) { actionSelect.disabled = false; actionSelect.style.backgroundColor = '#ffffff'; }
    if (statusSelect) { statusSelect.disabled = false; statusSelect.style.backgroundColor = '#ffffff'; }
    if (resTextarea) {
        resTextarea.disabled = false;
        resTextarea.readOnly = false;
        resTextarea.style.backgroundColor = '#ffffff';
        resTextarea.focus();
    }
    if (submitBtn) {
        submitBtn.style.display = 'inline-block';
        submitBtn.innerHTML = '<i class="fa-solid fa-floppy-disk"></i> Guardar Cambios Autorizados';
    }
    if (unlockBtn) unlockBtn.style.display = 'none';

    if (securityBanner) {
        securityBanner.style.background = '#fffbeb';
        securityBanner.style.border = '1px solid #fde68a';
        securityBanner.style.color = '#b45309';
        securityBanner.innerHTML = '<i class="fa-solid fa-unlock-keyhole" style="font-size:1.1rem; color:#d97706;"></i> <span><strong>Edición Autorizada por Dirección:</strong> Modificación habilitada. Puede actualizar las medidas disciplinarias, el dictamen oficial o el estado del expediente.</span>';
    }

    showToast('Modificación autorizada por Dirección. Campos habilitados para edición.', 'info');
}
window.enableDisciplineDirectorEdit = enableDisciplineDirectorEdit;

async function saveDisciplineResolutionForm(e) {
    if (e && e.preventDefault) e.preventDefault();

    const currentRole = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    const isDirector = checkDisciplineDirectorPermission();
    const isAuxiliar = currentRole === 'profesor_auxiliar';

    // 1. Docentes NUNCA pueden guardar ni modificar resoluciones
    if (!checkDisciplineResolvePermission() || (!isDirector && !isAuxiliar)) {
        showToast('Acceso denegado: Los docentes no tienen facultades para dictaminar ni modificar resoluciones disciplinarias.', 'danger');
        return;
    }

    const idInput = document.getElementById('discResModalReportId');
    const statusSelect = document.getElementById('discResStatusSelect');
    const actionSelect = document.getElementById('discResActionType');
    const resTextarea = document.getElementById('discResResolutionText');

    const reportId = idInput ? idInput.value : '';
    const status = statusSelect ? statusSelect.value : 'Resuelto';
    const actionType = actionSelect ? actionSelect.value : 'Citación de Padres de Familia';
    const resolutionText = resTextarea ? resTextarea.value.trim() : '';

    if (!resolutionText) {
        showToast('Debe ingresar el dictamen o resolución oficial de la falta disciplinaria.', 'warning');
        return;
    }

    let list = STATE.disciplineReports || STATE.discipline || [];
    const rep = list.find(r => r.id === reportId);
    if (!rep) {
        showToast('Reporte disciplinario no encontrado.', 'warning');
        return;
    }

    // 2. Profesor Auxiliar solo puede dictaminar si NO estaba resuelto previamente (a menos que Dirección lo autorice)
    if (isAuxiliar && rep.status === 'Resuelto' && rep.isLocked === true) {
        showToast('Este caso ya fue resuelto y cerrado. Solo la Dirección del establecimiento puede autorizar modificaciones.', 'danger');
        return;
    }

    const userName = STATE.currentUser ? (STATE.currentUser.name || STATE.currentUser.username) : (isDirector ? 'Dirección' : 'Profesor Auxiliar');
    const roleLabel = isDirector ? 'Dirección' : 'Profesor Auxiliar';

    rep.status = status;
    rep.resolutionStatus = status;
    rep.actionType = actionType;
    rep.resolution = resolutionText;
    rep.resolutionText = resolutionText;
    rep.resolvedBy = `${userName} (${roleLabel})`;
    rep.resolvedDate = new Date().toISOString().split('T')[0];
    if (status === 'Resuelto') {
        rep.isLocked = true;
    } else {
        rep.isLocked = false;
    }

    try {
        const modular = window.FirebaseModular;
        if (modular && modular.db && typeof modular.doc === 'function' && typeof modular.setDoc === 'function') {
            await modular.setDoc(modular.doc(modular.db, 'disciplina', reportId), rep, { merge: true });
        }
    } catch(fsErr) {
        console.warn("Aviso en Firestore al guardar resolución disciplinaria:", fsErr);
    }

    if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
        EnccoCloudSync.syncNode('disciplineReports', STATE.disciplineReports);
    }
    if (typeof triggerInstantCloudPush === 'function') triggerInstantCloudPush();

    closeDisciplineResolutionModal();
    renderDisciplineTable();
    if (typeof renderDashboard === 'function') renderDashboard();
    if (typeof updateUserAlertsUI === 'function') updateUserAlertsUI();
    if (typeof renderCurrentDashboardAlerts === 'function') renderCurrentDashboardAlerts();
    const profModal = document.getElementById('studentProfileModal');
    if (profModal && (profModal.classList.contains('active') || profModal.style.display !== 'none')) {
        if (STATE.selectedStudentId && typeof openStudentProfileModal === 'function') {
            openStudentProfileModal(STATE.selectedStudentId);
        }
    }
    
    if (isDirector) {
        showToast(`Resolución actualizada y validada con éxito por la Dirección.`, 'success');
    } else {
        showToast(`Dictamen emitido y guardado exitosamente por Auxiliatura. Visible para el docente en modo consulta.`, 'success');
    }
}
window.saveDisciplineResolutionForm = saveDisciplineResolutionForm;

async function deleteDisciplineReport(reportId) {
    if (!checkDisciplineDirectorPermission()) {
        showToast("Acceso denegado: Únicamente la Dirección o Administrador del establecimiento tienen autorización de rol y permiso para eliminar reportes disciplinarios.", "danger");
        return;
    }

    const list = STATE.disciplineReports || STATE.discipline || [];
    const rep = list.find(d => d.id === reportId);
    const studentName = rep ? (rep.studentName || 'del estudiante') : '';

    const confirmMsg = studentName
        ? '¿Está seguro de eliminar este reporte disciplinario de "' + studentName + '" del sistema? Esta acción es irreversible y facultad exclusiva de Dirección.'
        : '¿Está seguro de eliminar este reporte disciplinario del sistema? Esta acción es irreversible y solo puede ser autorizada por Dirección.';

    const confirmed = (window.EnccoDialog && typeof window.EnccoDialog.confirm === 'function')
        ? await window.EnccoDialog.confirm({
            title: 'Eliminar Reporte Disciplinario',
            message: confirmMsg,
            confirmText: 'Sí, eliminar reporte',
            cancelText: 'Cancelar',
            type: 'danger'
        })
        : false;

    if (confirmed) {
        STATE.deletedDisciplineIds = STATE.deletedDisciplineIds || [];
        if (!STATE.deletedDisciplineIds.includes(reportId)) {
            STATE.deletedDisciplineIds.push(reportId);
            try {
                if (typeof localStorage !== 'undefined') {
                    localStorage.setItem('ENCCO_DELETED_DISCIPLINE_IDS', JSON.stringify(STATE.deletedDisciplineIds));
                }
            } catch(e) {}
        }

        STATE.disciplineReports = (STATE.disciplineReports || []).filter(d => d.id !== reportId);
        if (STATE.discipline) {
            STATE.discipline = (STATE.discipline || []).filter(d => d.id !== reportId);
        }

        try {
            const modular = window.FirebaseModular;
            if (modular && modular.db && typeof modular.doc === 'function' && typeof modular.deleteDoc === 'function') {
                modular.deleteDoc(modular.doc(modular.db, 'disciplina', reportId)).catch(e => {});
                modular.deleteDoc(modular.doc(modular.db, 'disciplineReports', reportId)).catch(e => {});
            }
        } catch(fsErr) {}

        if (typeof EnccoCloudSync !== 'undefined') {
            if (typeof EnccoCloudSync.deleteNode === 'function') {
                EnccoCloudSync.deleteNode('disciplineReports/' + reportId);
                EnccoCloudSync.deleteNode('disciplina/' + reportId);
            }
            if (typeof EnccoCloudSync.syncNode === 'function') {
                EnccoCloudSync.syncNode('disciplineReports', STATE.disciplineReports);
            }
        }
        if (typeof triggerInstantCloudPush === 'function') triggerInstantCloudPush();
        renderDisciplineTable();

        if (typeof closeDisciplineResolutionModal === 'function') {
            closeDisciplineResolutionModal();
        }

        // Si el modal de perfil de estudiante está abierto, refrescar su historial disciplinario completo
        const profModal = document.getElementById('studentProfileModal');
        if (profModal && (profModal.classList.contains('active') || profModal.style.display !== 'none')) {
            if (STATE.selectedStudentId && typeof openStudentProfileModal === 'function') {
                openStudentProfileModal(STATE.selectedStudentId);
            }
        }

        if (typeof renderDashboard === 'function') renderDashboard();
        if (typeof updateDashboardKPIs === 'function') updateDashboardKPIs();
        if (typeof renderCurrentDashboardAlerts === 'function') renderCurrentDashboardAlerts();

        showToast("Reporte disciplinario eliminado exitosamente por Dirección.", "success");
    }
}

function deleteCurrentDisciplineReportFromModal() {
    const idInput = document.getElementById('discResModalReportId');
    if (!idInput || !idInput.value) return;
    deleteDisciplineReport(idInput.value);
}
window.deleteCurrentDisciplineReportFromModal = deleteCurrentDisciplineReportFromModal;
window.deleteDisciplineReport = deleteDisciplineReport;

function renderDisciplineTable() {
    const tbody = document.getElementById('disciplineTableBody');
    if (!tbody) return;

    let list = (Array.isArray(STATE.disciplineReports) && STATE.disciplineReports.length > 0)
        ? STATE.disciplineReports
        : (STATE.discipline || []);

    const currentRole = STATE.currentRole || (STATE.currentUser ? STATE.currentUser.role : 'docente');
    const isDirector = checkDisciplineDirectorPermission();
    const isAuxiliar = currentRole === 'profesor_auxiliar';
    const isStudent = currentRole === 'estudiante';
    const isDocente = !isDirector && !isAuxiliar && !isStudent;

    // Control de visibilidad de botones superiores de la vista
    const btnNew = document.getElementById('btnNewDisciplineReport');
    if (btnNew) {
        btnNew.style.display = (currentRole !== 'estudiante') ? '' : 'none';
    }
    const btnAuthPerm = document.getElementById('btnAuthPermDisciplineView');
    if (btnAuthPerm) {
        const canAuthPerm = isDirector || isAuxiliar || ['admin', 'direccion', 'secretaria', 'profesor_auxiliar'].includes(currentRole);
        btnAuthPerm.style.display = canAuthPerm ? '' : 'none';
    }

    if (list.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" style="text-align:center; padding:35px; color:var(--text-muted);">
                    <i class="fa-solid fa-shield-halved" style="font-size:2.2rem; margin-bottom:10px; display:block; color:var(--brand-green);"></i>
                    <strong>No hay reportes disciplinarios registrados.</strong><br>
                    <span style="font-size:0.85rem;">Los catedráticos y personal del plantel pueden registrar incidencias con el botón <strong>"Nueva Llamada de Atención"</strong>.</span>
                </td>
            </tr>
        `;
        return;
    }

    tbody.innerHTML = list.map(d => {
        // Formatear badge de estado
        let statusBadge = '';
        if (d.status === 'Resuelto') {
            statusBadge = '<span class="badge" style="background:#15803d; color:#fff; font-weight:700;"><i class="fa-solid fa-circle-check"></i> Resuelto</span>';
        } else if (d.status === 'En Proceso') {
            statusBadge = '<span class="badge" style="background:#0284c7; color:#fff; font-weight:700;"><i class="fa-solid fa-spinner"></i> En Proceso</span>';
        } else {
            statusBadge = '<span class="badge" style="background:#d97706; color:#fff; font-weight:700;"><i class="fa-solid fa-clock"></i> Pendiente Auxiliar</span>';
        }

        // Formatear badge de severidad
        let sevColor = '#eab308';
        if (d.severity === 'Grave') sevColor = '#ea580c';
        if (d.severity === 'Muy Grave') sevColor = '#dc2626';
        const sevBadge = `<span class="badge" style="background:${sevColor}; color:#fff; font-weight:700;">${d.severity || 'Leve'}</span>`;

        // Vista previa de la resolución del maestro auxiliar o dirección
        let resSnippet = '';
        if (d.resolution) {
            const resAuthor = d.resolvedBy || 'Auxiliatura General';
            const resDateStr = d.resolutionDate ? new Date(d.resolutionDate).toLocaleDateString('es-GT') : (d.date || '');
            resSnippet = `
                <div style="font-size:0.8rem; color:#166534; background:#f0fdf4; border-left:3px solid #16a34a; padding:4px 8px; border-radius:3px; margin-top:4px;">
                    <div><i class="fa-solid fa-gavel"></i> <strong>Dictamen:</strong> ${d.actionType || 'Medida aplicada'}</div>
                    <div style="font-size:0.75rem; color:#15803d; margin-top:1px;">
                        <i class="fa-solid fa-user-check"></i> <strong>Resuelto por:</strong> ${resAuthor} ${resDateStr ? `(${resDateStr})` : ''}
                    </div>
                    ${d.resolution ? `<div style="font-size:0.75rem; color:#334155; font-style:italic; margin-top:1px;">"${d.resolution}"</div>` : ''}
                </div>
            `;
        } else {
            resSnippet = `<div style="font-size:0.8rem; color:#94a3b8; font-style:italic; margin-top:2px;">En espera de resolución del Profesor Auxiliar</div>`;
        }

        // Acciones según rol del usuario
        let actionButtonsHtml = '';
        if (isStudent) {
            // Estudiante: Solo puede consultar el dictamen de forma transparente y segura
            if (d.resolution) {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-outline-info" onclick="openDisciplineResolutionModal('${d.id}')" title="Consultar dictamen oficial (Solo Lectura)" style="padding:4px 9px; font-weight:700;">
                        <i class="fa-solid fa-eye"></i> Ver Dictamen
                    </button>
                `;
            } else {
                actionButtonsHtml = `
                    <span class="badge" style="background:#64748b; color:#fff; font-size:0.75rem; padding:5px 8px;"><i class="fa-solid fa-clock"></i> Pendiente</span>
                `;
            }
        } else if (isDocente) {
            // Catedrático: Solo puede consultar la resolución sin modificarla
            if (d.resolution) {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-outline-info" onclick="openDisciplineResolutionModal('${d.id}')" title="Consultar dictamen oficial (Solo Lectura)" style="padding:4px 9px; font-weight:700;">
                        <i class="fa-solid fa-eye"></i> Ver Dictamen
                    </button>
                `;
            } else {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-outline-secondary" onclick="openDisciplineResolutionModal('${d.id}')" title="Ver reporte disciplinario (Pendiente de dictamen)" style="padding:4px 9px; font-weight:600;">
                        <i class="fa-solid fa-clock"></i> Pendiente Auxiliar
                    </button>
                `;
            }
        } else if (isAuxiliar) {
            // Profesor Auxiliar: Puede resolver reportes pendientes. Una vez resuelto, queda en solo lectura
            if (d.status === 'Resuelto') {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-outline-info" onclick="openDisciplineResolutionModal('${d.id}')" title="Ver resolución oficial (Caso cerrado)" style="padding:4px 9px; font-weight:600;">
                        <i class="fa-solid fa-eye"></i> Ver Resolución
                    </button>
                `;
            } else {
                actionButtonsHtml = `
                    <button type="button" class="btn btn-sm btn-primary" onclick="openDisciplineResolutionModal('${d.id}')" title="Emitir dictamen disciplinario oficial" style="padding:4px 9px; font-weight:700; background:#0284c7; border-color:#0284c7;">
                        <i class="fa-solid fa-gavel"></i> Dictaminar
                    </button>
                `;
            }
        } else if (isDirector) {
            // Dirección / Admin: Puede dictaminar, permitir modificaciones y eliminar
            actionButtonsHtml = `
                <button type="button" class="btn btn-sm btn-outline-info" onclick="openDisciplineResolutionModal('${d.id}')" title="${d.resolution ? 'Gestionar o revisar dictamen' : 'Dictaminar reporte'}" style="padding:4px 9px; margin-right:4px; font-weight:700;">
                    <i class="fa-solid ${d.resolution ? 'fa-eye' : 'fa-gavel'}"></i> ${d.resolution ? 'Gestionar Dictamen' : 'Dictaminar'}
                </button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteDisciplineReport('${d.id}')" title="Eliminar reporte (Facultad de Dirección)" style="padding:4px 8px;">
                    <i class="fa-solid fa-trash"></i>
                </button>
            `;
        }

        return `
        <tr>
            <td>${d.date || '2026-08-30'}</td>
            <td>
                <strong>${d.studentName || 'Estudiante'}</strong><br>
                <small style="color:var(--text-muted);">${d.grade || '4to Perito'}</small>
            </td>
            <td>
                <span style="font-weight:600; color:var(--text-primary);"><i class="fa-solid fa-user-tie" style="color:var(--brand-green); margin-right:4px;"></i> ${d.teacher || 'Docente'}</span>
            </td>
            <td>${sevBadge}</td>
            <td>
                <div style="font-size:0.88rem; line-height:1.35; max-width:280px;">${d.reason}</div>
                ${resSnippet}
            </td>
            <td style="text-align:center;">${statusBadge}</td>
            <td style="text-align:center; white-space:nowrap;">
                ${actionButtonsHtml}
            </td>
        </tr>
        `;
    }).join('');
}
window.renderDisciplineTable = renderDisciplineTable;


// ──────────────────────────────────────────────────────────────────────────
// 📊 ANALIZADOR E IMPORTADOR DE ARCHIVOS EXCEL (MAESTROS Y PENSUM)
// ──────────────────────────────────────────────────────────────────────────

function triggerTeachersExcelUpload() {
    const input = document.getElementById('globalTeachersPensumFileInput');
    if (input) input.click();
}

function handleGlobalTeachersPensumExcelUpload(e) {
    if (!checkEnrolmentPermissions()) return;
    const file = e.target.files[0];
    if (!file) return;

    readExcelFileRows(file, function(rawLines) {
        if (!rawLines || rawLines.length === 0) {
            showToast("El archivo seleccionado está vacío.", "warning");
            return;
        }

        let addedTeachers = 0;
        let addedPensum = 0;

        rawLines.forEach(line => {
            const parts = line.split(/[,;\t|]/).map(p => p.replace(/^"|"$/g, '').trim());
            if (parts.length < 1) return;

            const fullLine = parts.join(' ').toLowerCase();
            if (fullLine.includes('maestro') || fullLine.includes('catedratico') || fullLine.includes('docente') || fullLine.includes('materia') || fullLine.includes('curso')) {
                return; // Fila de encabezado
            }

            let teacherName = '';
            let subjectName = '';
            let gradeStr = '6to';
            let sectionStr = 'Sección A';
            let careerStr = 'Perito Contador';

            parts.forEach(cell => {
                const cLower = cell.toLowerCase();
                if (['pem.', 'lic.', 'prof.', 'ing.', 'licda.'].some(t => cLower.includes(t)) || (cell.split(' ').length >= 2 && !teacherName && !/\d/.test(cell) && cell.length > 4)) {
                    if (!teacherName) teacherName = cell;
                }
                if (['contabilidad', 'computacion', 'ingles', 'matematica', 'fisica', 'quimica', 'derecho', 'administracion', 'ortografia', 'redaccion', 'estadistica', 'mecanografia', 'finanzas', 'auditoria'].some(c => cLower.includes(c))) {
                    subjectName = cell;
                }
                if (['4to', '5to', '6to', '4°', '5°', '6°'].some(g => cLower.includes(g))) {
                    gradeStr = cell;
                }
                if (['A', 'B', 'C', 'D'].includes(cell.toUpperCase())) {
                    sectionStr = `Sección ${cell.toUpperCase()}`;
                }
            });

            let existingTeacherObj = null;
            if (teacherName) {
                existingTeacherObj = (STATE.users || []).find(u => u.name.toLowerCase() === teacherName.toLowerCase());
                if (!existingTeacherObj) {
                    const cleanEmail = teacherName.toLowerCase().replace(/[^a-z0-9]/g, '.') + '@encc.edu.gt';
                    existingTeacherObj = {
                        id: 'usr-doc-' + Date.now() + '-' + Math.floor(Math.random() * 100),
                        name: teacherName,
                        email: cleanEmail,
                        password: 'C@rolina1',
                        role: 'docente',
                        title: 'PEM / Catedrático Titular',
                        classes: subjectName ? `${subjectName} (${gradeStr} ${sectionStr.replace('Sección ', '')})` : 'Cursos Varios'
                    };
                    STATE.users.push(existingTeacherObj);
                    addedTeachers++;
                }
            }

            if (subjectName) {
                const gradeObj = (STATE.gradesList || []).find(g => g.name.toLowerCase().includes(gradeStr.toLowerCase()) && g.section === sectionStr) || (STATE.gradesList || [])[0];
                const gradeCode = gradeObj ? gradeObj.code : '6° A';

                const existingPensum = (STATE.pensum || []).find(p => p.subject.toLowerCase() === subjectName.toLowerCase() && p.gradeCode === gradeCode);
                if (!existingPensum) {
                    STATE.pensum.push({
                        id: 'pen-' + Date.now() + '-' + Math.floor(Math.random() * 100),
                        subject: subjectName,
                        gradeCode: gradeCode,
                        grade: gradeObj ? gradeObj.name : '6to Perito Contador',
                        section: sectionStr,
                        career: careerStr,
                        teacher: teacherName || (existingTeacherObj ? existingTeacherObj.name : 'PEM. Nehemias Yalil Salguero'),
                        teacherId: existingTeacherObj ? existingTeacherObj.id : 'usr-doc-01',
                        periodsPerWeek: 4,
                        maxScore: 100
                    });
                    addedPensum++;
                }
            }
        });

        saveStateToLocalStorage();
        renderUsersTable();
        renderPensumCatalogTable();
        renderAssignmentsTable();
        updateGradeSelects();

        showToast(`🎉 ¡ANÁLISIS DE EXCEL COMPLETADO! Se procesaron e importaron ${addedTeachers} maestros y ${addedPensum} materias de pensum.`, "success");
        if (e.target) e.target.value = '';
    });
}

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', async () => { await initApp(); });
    } else {
        initApp();
    }
}





