// 🖨️ INFORME ESTADÍSTICO IMPRIMIBLE DEL CLAUSTRO DOCENTE POR RENGLÓN (011/021) Y GÉNERO
// ──────────────────────────────────────────────────────────────────────────

function printStudentDemographicsReport() {
    const isTeacher = STATE.currentRole === 'docente';
    if (STATE.currentRole !== 'admin' && STATE.currentRole !== 'director' && STATE.currentRole !== 'secretaria' && !isTeacher && STATE.currentUser?.role !== 'admin') {
        showToast("Acceso Restringido: Informe estadístico disponible para Dirección, Secretaría y Catedráticos.", "danger");
        return;
    }

    const h = STATE.schoolHeader || getInitialData().schoolHeader;
    let gradesList = sortGrades(STATE.gradesList || getInitialData().gradesList);
    const students = STATE.students || [];
    let teacherSubtitle = "";

    if (isTeacher && STATE.currentUser) {
        const teacherName = (STATE.currentUser.name || '').toLowerCase();
        const teacherPensum = (STATE.pensum || []).filter(p => (p.teacher || '').toLowerCase().includes(teacherName) || (p.teacherName || '').toLowerCase().includes(teacherName));
        const assignedGradeCodes = Array.from(new Set(teacherPensum.map(p => p.grade || p.gradeCode)));
        
        if (assignedGradeCodes.length > 0) {
            gradesList = gradesList.filter(g => assignedGradeCodes.includes(g.code) || assignedGradeCodes.includes(g.name));
        }
        teacherSubtitle = ` — CATEDRÁTICO(A): ${STATE.currentUser.name || 'Docente Titular'}`;
    }

    const printWin = window.open('', '_blank');
    if (!printWin) {
        showToast("Permita las ventanas emergentes para imprimir el informe de matrícula.", "warning");
        return;
    }

    const dateStr = new Date().toLocaleDateString('es-GT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    const capDate = dateStr.charAt(0).toUpperCase() + dateStr.slice(1);

    // Agrupar estudiantes por Grado y Sección
    let grandTotalMale = 0;
    let grandTotalFemale = 0;
    let grandTotal = 0;

    const sectionMatrix = gradesList.map(g => {
        const rawG = `${g.code || ''} ${g.name || ''} ${g.section || ''}`.toUpperCase();
        let gGradeNum = 0;
        if (rawG.includes('6') || rawG.includes('SEXTO') || rawG.includes('6TO')) gGradeNum = 6;
        else if (rawG.includes('5') || rawG.includes('QUINTO') || rawG.includes('5TO')) gGradeNum = 5;
        else if (rawG.includes('4') || rawG.includes('CUARTO') || rawG.includes('4TO')) gGradeNum = 4;

        const gSec = getCleanSectionLetter(g.section || g.code || rawG);

        const secStudents = students.filter(s => {
            if (!isStudentActive(s)) return false;

            const rawS = `${s.grade || ''} ${s.gradeCode || ''} ${s.gradeLabel || ''}`.toUpperCase();
            let sGradeNum = 0;
            if (rawS.includes('6') || rawS.includes('SEXTO') || rawS.includes('6TO')) sGradeNum = 6;
            else if (rawS.includes('5') || rawS.includes('QUINTO') || rawS.includes('5TO')) sGradeNum = 5;
            else if (rawS.includes('4') || rawS.includes('CUARTO') || rawS.includes('4TO')) sGradeNum = 4;

            const sSec = getCleanSectionLetter(s.section || s.gradeCode || s.gradeLabel || rawS);

            if (gGradeNum > 0 && sGradeNum > 0 && gGradeNum !== sGradeNum) return false;
            if (gSec && sSec && gSec !== sSec) return false;

            return (gGradeNum === sGradeNum) && (gSec === sSec);
        });

        let mCount = 0, fCount = 0;
        secStudents.forEach(s => {
            const gNorm = (s.gender || '').trim().toLowerCase();
            if (gNorm.startsWith('f') || gNorm === 'femenino') fCount++;
            else mCount++;
        });

        const totalSec = secStudents.length;
        grandTotalMale += mCount;
        grandTotalFemale += fCount;
        grandTotal += totalSec;

        return {
            code: g.code,
            name: g.name,
            section: g.section,
            career: g.career,
            guideTeacher: (typeof getGradeGuideTeacher === 'function' ? getGradeGuideTeacher(g).name : (g.guideTeacher || 'Sin asignar')),
            male: mCount,
            female: fCount,
            total: totalSec
        };
    });

    const rowsHtml = sectionMatrix.map((row, idx) => {
        const pct = grandTotal > 0 ? ((row.total / grandTotal) * 100).toFixed(1) : '0';
        return `
            <tr>
                <td style="text-align:center; font-weight:bold;">${idx + 1}</td>
                <td style="font-weight:bold; color:#0369a1;">${row.name} (${row.section})</td>
                <td style="text-align:center;"><span class="badge" style="background:#e0f2fe; color:#0369a1; border:1px solid #7dd3fc; font-weight:900;">${row.code}</span></td>
                <td style="text-align:center;">${row.career}</td>
                <td>${row.guideTeacher}</td>
                <td style="text-align:center; font-weight:bold; color:#0284c7;">${row.male}</td>
                <td style="text-align:center; font-weight:bold; color:#be185d;">${row.female}</td>
                <td style="text-align:center; font-weight:bold; font-size:10pt; background:#f0fdf4;">${row.total}</td>
                <td style="text-align:center; font-weight:bold;">${pct}%</td>
            </tr>
        `;
    }).join('');

    printWin.document.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <title>Informe Estadístico de Matrícula - ${h.schoolName || 'ENCCO JUTIAPA'}</title>
            <style>
                @page { size: 8.5in 13in portrait; margin: 6mm 8mm; }
                body { font-family: 'Segoe UI', Arial, sans-serif; color: #000; background: #fff; line-height: 1.3; font-size: 9.5pt; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
                
                .official-header { border: 2px solid #15803d; border-radius: 6px; overflow: hidden; margin-bottom: 14px; }
                .top-banner { background: linear-gradient(135deg, #0f172a 0%, #15803d 60%, #166534 100%) !important; color: #fff; display: flex; align-items: center; justify-content: space-between; padding: 8px 16px; }
                .top-banner img { height: 48px; width: auto; }
                .top-banner h1 { margin: 0; font-size: 16px; font-weight: 900; color: #fff; text-transform: uppercase; }
                .sub-tag { font-size: 9.5px; font-weight: 700; color: #bbf7d0; }
                
                .report-title-box { background: #f0fdf4 !important; border-top: 2px solid #166534; padding: 8px 16px; text-align: center; }
                .report-title { font-size: 12pt; font-weight: 900; color: #15803d; text-transform: uppercase; margin: 0; }
                
                .stat-table { width: 100%; border-collapse: collapse; margin: 12px 0 16px 0; border: 1.5px solid #0f172a; font-size: 9pt; }
                .stat-table th { background: #15803d !important; color: #ffffff !important; border: 1px solid #0f172a; padding: 6px 8px; text-align: center; font-weight: 900; text-transform: uppercase; }
                .stat-table td { border: 1px solid #64748b; padding: 5px 8px; }
                .stat-table tr:nth-child(even) { background-color: #f8fafc; }
                .stat-table tr.total-row { background: #dcfce7 !important; font-weight: 900; font-size: 10pt; }

                .signatures { margin-top: 40px; display: flex; justify-content: space-around; text-align: center; }
                .sig-box { width: 220px; border-top: 1.5px solid #000; padding-top: 4px; font-size: 9pt; font-weight: bold; }
            </style>
        </head>
        <body>
            <div class="official-header">
                <div class="top-banner">
                    <div style="display:flex; align-items:center; gap:12px;">
                        <img src="logo.png" alt="Logo ENCCO" onerror="this.src='portada-comercio-principal.webp'">
                        <div>
                            <h1>${h.schoolName || 'ESCUELA NACIONAL DE CIENCIAS COMERCIALES'}</h1>
                            <div class="sub-tag">JUTIAPA — FUNDADA EN 1970 | CICLO LECTIVO ${STATE.activeCycle || '2026'}</div>
                        </div>
                    </div>
                    <div style="background:#166534; color:#fff; font-size:10px; font-weight:900; padding:4px 12px; border-radius:12px; border:1px solid #86efac; text-transform:uppercase;">
                        DIRECCIÓN / SECRETARÍA
                    </div>
                </div>
                <div class="report-title-box">
                    <div class="report-title">INFORME ESTADÍSTICO DE MATRÍCULA ESCOLAR POR GRADO, SECCIÓN Y GÉNERO${teacherSubtitle}</div>
                    <div style="font-size:9pt; color:#334155; font-weight:700; margin-top:2px;">Emitido el: ${capDate} — ENCCO Jutiapa</div>
                </div>
            </div>

            <h3 style="margin:10px 0 4px 0; font-size:10.5pt; color:#15803d; text-transform:uppercase;">Resumen Institucional de Estudiantes por Grado, Sección y Género</h3>
            <table class="stat-table">
                <thead>
                    <tr>
                        <th style="width:30px;">#</th>
                        <th style="text-align:left;">Grado y Sección</th>
                        <th style="width:80px;">Código</th>
                        <th>Carrera</th>
                        <th>Maestro(a) Guía Titular</th>
                        <th style="width:75px;">Hombres</th>
                        <th style="width:75px;">Mujeres</th>
                        <th style="width:90px;">Total Sección</th>
                        <th style="width:70px;">% Matrícula</th>
                    </tr>
                </thead>
                <tbody>
                    ${rowsHtml}
                    <tr class="total-row">
                        <td colspan="5" style="text-align:right;">GRAN TOTAL MATRÍCULA INSTITUCIONAL ENCCO:</td>
                        <td style="text-align:center; color:#0369a1;">${grandTotalMale}</td>
                        <td style="text-align:center; color:#be185d;">${grandTotalFemale}</td>
                        <td style="text-align:center; color:#15803d; font-size:11pt;">${grandTotal}</td>
                        <td style="text-align:center;">100.0%</td>
                    </tr>
                </tbody>
            </table>

            <div class="signatures">
                <div class="sig-box">
                    Secretaría Académica<br>
                    Vo.Bo. Control de Matrícula
                </div>
                <div class="sig-box">
                    Licda. Director(a) ENCCO<br>
                    Sello Oficial Institucional
                </div>
            </div>
        </body>
        </html>
    `);
    printWin.document.close();
    setTimeout(() => {
        printWin.focus();
        printWin.print();
    }, 400);
}


// ───────── HELPER GLOBAL DE PERÍODOS SEMANALES VINCULADOS ─────────
function getSubjectPeriodsPerWeek(subjectName, gradeCodeOrName) {
    if (!subjectName) return 4;
    const sLow = subjectName.toLowerCase();
    const gLow = (gradeCodeOrName || '').toLowerCase();
    const item = (STATE.pensum || []).find(p => 
        (p.name?.toLowerCase().includes(sLow) || p.subject?.toLowerCase().includes(sLow) || sLow.includes(p.name?.toLowerCase() || '') || sLow.includes(p.subject?.toLowerCase() || '')) &&
        (!gLow || p.gradeCode?.toLowerCase() === gLow || p.grade?.toLowerCase().includes(gLow))
    );
    return item ? (parseInt(item.periodsPerWeek || item.hours) || 4) : 4;
}


// ──────────────────────────────────────────────────────────────────────────
// 🔢 GESTIÓN Y REORDENAMIENTO DE MATERIAS DEL PENSUM ESCOLAR
// ──────────────────────────────────────────────────────────────────────────

function updatePensumSubjectSortOrder(subjectId, newOrderVal) {
    const newOrder = parseInt(newOrderVal) || 1;
    const item = (STATE.pensumCatalog || []).find(x => x.id === subjectId);
    if (!item) return;

    item.sortOrder = newOrder;

    // Sincronizar en STATE.pensum
    (STATE.pensum || []).forEach(p => {
        if (p.subject === item.subject || p.name === item.subject) {
            p.sortOrder = newOrder;
        }
    });

    const savedGradeFilter = document.getElementById('pensumCatalogGradeFilter')?.value || 'ALL';
    const savedCareerFilter = document.getElementById('pensumCatalogCareerFilter')?.value || 'ALL';
    const savedSearchQuery = document.getElementById('pensumCatalogSearchInput')?.value || '';

    saveStateToLocalStorage();

    if (document.getElementById('pensumCatalogGradeFilter')) document.getElementById('pensumCatalogGradeFilter').value = savedGradeFilter;
    if (document.getElementById('pensumCatalogCareerFilter')) document.getElementById('pensumCatalogCareerFilter').value = savedCareerFilter;
    if (document.getElementById('pensumCatalogSearchInput')) document.getElementById('pensumCatalogSearchInput').value = savedSearchQuery;

    renderPensumCatalogTable(savedSearchQuery);
    showToast(`Orden de la materia "${item.subject}" actualizado a No. ${newOrder}.`, "info");
}

function movePensumSubjectOrder(subjectId, delta) {
    const item = (STATE.pensumCatalog || []).find(x => x.id === subjectId);
    if (!item) return;

    const currentOrder = parseInt(item.sortOrder || 1);
    const newOrder = Math.max(1, currentOrder + delta);

    updatePensumSubjectSortOrder(subjectId, newOrder);
}


