function exportStudentsOfficialCSV() {
    exportStudentsOfficialExcel();
}

function exportStudentsOfficialExcel() {
    try {
        const gradeFilterSel = document.getElementById('gradeFilterSelect');
        const gradeVal = gradeFilterSel ? gradeFilterSel.value : '';
        const cycle = STATE.activeCycle || '2026';
        let students = (STATE.students || []).filter(s => !s.cycle || s.cycle === cycle);

        let reportTitle = "MATRÍCULA GENERAL DE ESTUDIANTES";
        let fileName = `matricula_estudiantes_encc_${cycle}.xlsx`;

        const isDocente = (STATE.currentRole === 'docente');
        const currentDocenteUser = STATE.currentUser || (typeof getCurrentUser === 'function' ? getCurrentUser() : null);

        if (isDocente && currentDocenteUser) {
            if (!gradeVal || gradeVal === 'ALL') {
                showToast("Como docente, debe seleccionar un grado y sección específico de sus cátedras asignadas para exportar la nómina.", "warning");
                return;
            }
        }

        if (gradeVal && gradeVal !== 'ALL') {
            const targetGradeObj = (STATE.gradesList || []).find(g => g.code === gradeVal || g.id === gradeVal || g.name === gradeVal);
            const rawQ = `${gradeVal || ''} ${targetGradeObj ? (targetGradeObj.name + ' ' + targetGradeObj.section) : ''}`.toUpperCase();
            let qGradeNum = 0;
            if (rawQ.includes('6') || rawQ.includes('SEXTO') || rawQ.includes('6TO')) qGradeNum = 6;
            else if (rawQ.includes('5') || rawQ.includes('QUINTO') || rawQ.includes('5TO')) qGradeNum = 5;
            else if (rawQ.includes('4') || rawQ.includes('CUARTO') || rawQ.includes('4TO')) qGradeNum = 4;

            const qSec = typeof getCleanSectionLetter === 'function'
                ? getCleanSectionLetter(targetGradeObj ? targetGradeObj.section : gradeVal)
                : (targetGradeObj ? targetGradeObj.section : gradeVal).replace(/[^A-Za-z]/g, '').slice(0, 1).toUpperCase();

            if (isDocente && currentDocenteUser) {
                const hasAssignedClassInGrade = (STATE.pensum || []).some(a => {
                    if (!isCourseAssignedToTeacher(a, currentDocenteUser)) return false;
                    const rawA = `${a.grade || ''} ${a.gradeCode || ''} ${a.section || ''}`.toUpperCase();
                    let aGradeNum = 0;
                    if (rawA.includes('6') || rawA.includes('SEXTO') || rawA.includes('6TO')) aGradeNum = 6;
                    else if (rawA.includes('5') || rawA.includes('QUINTO') || rawA.includes('5TO')) aGradeNum = 5;
                    else if (rawA.includes('4') || rawA.includes('CUARTO') || rawA.includes('4TO')) aGradeNum = 4;
                    const aSec = typeof getCleanSectionLetter === 'function'
                        ? getCleanSectionLetter(a.section || a.gradeCode || rawA)
                        : (a.section || a.gradeCode || rawA).replace(/[^A-Za-z]/g, '').slice(0, 1).toUpperCase();
                    const isMatchGrade = (qGradeNum === 0 || aGradeNum === 0 || qGradeNum === aGradeNum);
                    const isMatchSec = (!qSec || !aSec || qSec === aSec);
                    return isMatchGrade && isMatchSec;
                });

                if (!hasAssignedClassInGrade) {
                    showToast("Acceso Denegado: Como docente, únicamente tiene autorización para exportar nóminas de los grados y secciones donde imparte clases.", "danger");
                    return;
                }
            }

            students = students.filter(s => {
                const rawS = `${s.grade || ''} ${s.gradeCode || ''} ${s.gradeLabel || ''}`.toUpperCase();
                let sGradeNum = 0;
                if (rawS.includes('6') || rawS.includes('SEXTO') || rawS.includes('6TO')) sGradeNum = 6;
                else if (rawS.includes('5') || rawS.includes('QUINTO') || rawS.includes('5TO')) sGradeNum = 5;
                else if (rawS.includes('4') || rawS.includes('CUARTO') || rawS.includes('4TO')) sGradeNum = 4;

                const sSec = typeof getCleanSectionLetter === 'function'
                    ? getCleanSectionLetter(s.section || s.gradeCode || s.gradeLabel || rawS)
                    : (s.section || s.gradeCode || s.gradeLabel || rawS).replace(/[^A-Za-z]/g, '').slice(0, 1).toUpperCase();

                if (qGradeNum > 0 && sGradeNum > 0 && qGradeNum !== sGradeNum) return false;
                if (qSec && sSec && qSec !== sSec) return false;

                return (qGradeNum === sGradeNum) && (qSec === sSec);
            });

            const gradeName = targetGradeObj ? `${targetGradeObj.name} (${targetGradeObj.section})` : gradeVal;
            reportTitle = `NÓMINA OFICIAL - ${gradeName.toUpperCase()}`;
            const cleanCode = (targetGradeObj ? targetGradeObj.code : gradeVal).replace(/[^a-zA-Z0-9]/g, '_').toLowerCase();
            fileName = `nomina_${cleanCode}_${cycle}.xlsx`;
        }

        // Respetar estado si hay filtro activo (por defecto exporta la nómina completa)
        const statusFilterSel = document.getElementById('statusFilterSelect');
        const statusVal = statusFilterSel ? statusFilterSel.value : 'ALL';
        if (statusVal && statusVal !== 'ALL') {
            const sValLower = statusVal.toLowerCase();
            if (sValLower === 'retirado' || sValLower === 'inactivo') {
                students = students.filter(s => s.status === 'Retirado' || (s.status === 'Inactivo' && s.retireReason));
            } else if (sValLower === 'ausente') {
                students = students.filter(s => s.status === 'Ausente');
            } else if (sValLower === 'activo' || sValLower === 'inscrito') {
                students = students.filter(s => s.status === 'Activo' || s.status === 'Inscrito' || s.statusSire === 'INSCRITO' || s.active !== false || !s.status);
            } else {
                students = students.filter(s => s.status && s.status.toLowerCase() === sValLower);
            }
        }

        if (!students || students.length === 0) {
            showToast("No hay estudiantes matriculados para exportar con los filtros seleccionados.", "warning");
            return;
        }

        // Ordenar alfabéticamente
        students.sort((a, b) => {
            const nameA = formatStudentDisplayName(a, 'lastFirst');
            const nameB = formatStudentDisplayName(b, 'lastFirst');
            return nameA.localeCompare(nameB, 'es', { sensitivity: 'base' });
        });

        const headers = [
            "No.",
            "Carné",
            "Código Personal",
            "CUI / DPI",
            "Apellidos",
            "Nombres",
            "Género",
            "Grado y Sección",
            "Padre / Encargado",
            "Teléfono",
            "Estado"
        ];

        const activeBim = parseInt(STATE.config?.activeBimestre) || 1;
        const dataRows = students.map((s, idx) => {
            let lName = (s.lastName || s.apellidos || '').trim();
            let fName = (s.firstName || s.nombres || '').trim();
            if (!lName && !fName && (s.name || s.fullName)) {
                const raw = (s.name || s.fullName).trim();
                if (raw.includes(',')) {
                    const parts = raw.split(',');
                    lName = parts[0].trim();
                    fName = parts.slice(1).join(' ').trim();
                } else {
                    const parts = raw.split(/\s+/);
                    if (parts.length > 2) {
                        lName = parts.slice(-2).join(' ');
                        fName = parts.slice(0, -2).join(' ');
                    } else if (parts.length === 2) {
                        lName = parts[1];
                        fName = parts[0];
                    } else {
                        lName = raw;
                        fName = '-';
                    }
                }
            }

            const isRet = (s.status === 'Retirado' || s.status === 'Inactivo') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(s, activeBim) : true);
            const isAus = (s.status === 'Ausente') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(s, activeBim) : true);
            const isExon = !isRet && !isAus && (typeof isStudentExonerated === 'function' ? isStudentExonerated(s, activeBim) : false);

            let statusTxt = 'ACTIVO';
            let nameTag = '';
            if (isRet) {
                statusTxt = 'RETIRADO';
                nameTag = ' [RETIRADO]';
            } else if (isAus) {
                statusTxt = 'AUSENTE';
                nameTag = ' [AUSENTE]';
            } else if (isExon) {
                statusTxt = `EXONERADO (B${activeBim})`;
                nameTag = ` [EXONERADO B${activeBim}]`;
            } else if (s.status && s.status !== 'Activo') {
                statusTxt = String(s.status).toUpperCase();
            }

            const row = [
                idx + 1,
                s.carne || '-',
                s.personalCode || '-',
                s.cui || '-',
                (lName || '-').toUpperCase() + nameTag,
                (fName || '-').toUpperCase(),
                s.gender || 'Masculino',
                formatStudentGradeAndSection(s),
                s.tutorName || s.tutor || '-',
                s.tutorPhone || s.phone || '-',
                statusTxt
            ];
            row._meta = { isRet, isAus, isExon };
            return row;
        });

        const colWidths = [6, 15, 18, 18, 25, 25, 12, 20, 25, 14, 18];
        exportDataToExcelFile(fileName, reportTitle, `CICLO ESCOLAR ${cycle}`, headers, dataRows, colWidths);
    } catch (err) {
        console.error("Error al exportar estudiantes:", err);
        showToast("Error al exportar nómina de estudiantes.", "danger");
    }
}



// ──────────────────────────────────────────────────────────────────────────
// 🖨️ MOTOR UNIVERSAL DE VISTA PREVIA E IMPRESIÓN DIRECTA EN PANTALLA
// ──────────────────────────────────────────────────────────────────────────

function closePrintDocumentModal() {
    const modal = document.getElementById('printDocumentModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

function renderAndShowPrintDocument(title, htmlContent, orientation = 'portrait') {
    const modal = document.getElementById('printDocumentModal');
    const titleEl = document.getElementById('printModalTitle');
    const contentEl = document.getElementById('printDocumentContent');
    const paperEl = document.getElementById('printDocumentPaper');

    if (!modal || !contentEl) {
        console.warn("No se encontró el contenedor modal de impresión.");
        return;
    }

    if (titleEl) titleEl.textContent = title;
    contentEl.innerHTML = htmlContent;
    window._currentPrintModalOrientation = orientation;

    if (paperEl) {
        if (orientation === 'landscape') {
            paperEl.style.maxWidth = '1050px';
        } else {
            paperEl.style.maxWidth = '900px';
        }
    }

    showModalById(modal.id || 'careerModal');
    modal.style.setProperty('display', 'flex', 'important');
}

function executeNativeDocumentPrint() {
    const content = document.getElementById('printDocumentContent');
    if (!content) return;

    let iframe = document.getElementById('enccPrintIframe');
    if (!iframe) {
        iframe = document.createElement('iframe');
        iframe.id = 'enccPrintIframe';
        iframe.style.position = 'fixed';
        iframe.style.right = '0';
        iframe.style.bottom = '0';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';
        document.body.appendChild(iframe);
    }

    const printOrientation = window._currentPrintModalOrientation || 'portrait';
    const pageSizeRule = (printOrientation === 'landscape') ? '8.5in 13in landscape' : '8.5in 13in portrait';

    const doc = iframe.contentWindow.document;
    doc.open();
    doc.write(`
        <!DOCTYPE html>
        <html lang="es">
        <head>
            <meta charset="UTF-8">
            <title>Impresión Oficial - ENCCO</title>
            <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
            <style>
                @page { size: ${pageSizeRule}; margin: 5mm; }
                body { font-family: 'Segoe UI', Arial, sans-serif; color: #000; margin: 0; padding: 0; background: #fff; font-size: 11px; }
                table { width: 100%; border-collapse: collapse; margin-top: 6px; }
                th, td { border: 1px solid #334155; padding: 5px 6px; }
                th { background-color: #0369a1 !important; color: #ffffff !important; font-weight: bold; text-align: center; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .row-retirado, .row-retirado td, tr.row-retirado td { background-color: #fee2e2 !important; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color: #b91c1c !important; }
                .row-ausente, .row-ausente td, tr.row-ausente td { background-color: #fef3c7 !important; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color: #b45309 !important; }
                .row-exonerado, .row-exonerado td, tr.row-exonerado td { background-color: #e0f2fe !important; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color: #0284c7 !important; }
                .encc-top-banner { background-color: #99b958 !important; border-bottom: 1.5px solid #000; display: flex; justify-content: space-between; align-items: center; padding: 6px 12px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                .badge { padding: 3px 6px; border-radius: 4px; font-weight: bold; font-size: 10px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                @media print {
                    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
                }
            </style>
        </head>
        <body>
            ${content.innerHTML}
        </body>
        </html>
    `);
    doc.close();

    setTimeout(() => {
        iframe.contentWindow.focus();
        iframe.contentWindow.print();
    }, 400);
}

