function filterGradesTable(query = '') {
    renderGradesTable(query);
}

function renderGradesTable(searchQuery = '') {
    const tbody = document.getElementById('gradesTableBody');
    if (!tbody) return;

    const careerFilterEl = document.getElementById('gradesCareerFilter');
    const careerFilter = (careerFilterEl && careerFilterEl.value) ? careerFilterEl.value : 'ALL';
    const q = (typeof searchQuery === 'string' ? searchQuery : (document.getElementById('gradesSearchInput') ? document.getElementById('gradesSearchInput').value : '')).toLowerCase().trim();

    // Ordenar rigurosamente por Grado y Sección
    let list = sortGrades(STATE.gradesList || []);

    // Actualizar KPIs de Secciones y Estudiantes
    const totalSections = list.length;
    let totalAssignedStudents = 0;
    list.forEach(g => {
        const count = typeof getStudentCountByGradeAndSection === 'function' ? getStudentCountByGradeAndSection(g.code, g.name, g.section) : 0;
        totalAssignedStudents += count;
    });

    const avgPerSection = totalSections > 0 ? (totalAssignedStudents / totalSections).toFixed(1) : '0';

    const kpiSec = document.getElementById('gradesKpiTotalSections');
    const kpiStu = document.getElementById('gradesKpiTotalStudents');
    const kpiAvg = document.getElementById('gradesKpiAvgStudents');
    if (kpiSec) kpiSec.textContent = totalSections;
    if (kpiStu) kpiStu.textContent = totalAssignedStudents;
    if (kpiAvg) kpiAvg.textContent = avgPerSection;

    if (careerFilter && careerFilter !== 'ALL') {
        list = list.filter(g => (g.career || '').toLowerCase() === careerFilter.toLowerCase());
    }
    if (q) {
        list = list.filter(g => 
            (g.name || '').toLowerCase().includes(q) ||
            (g.section || '').toLowerCase().includes(q) ||
            (g.code || '').toLowerCase().includes(q) ||
            (g.career && g.career.toLowerCase().includes(q)) ||
            (g.guideTeacher && g.guideTeacher.toLowerCase().includes(q))
        );
    }

    if (list.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" style="text-align:center; padding:35px; color:var(--text-muted);">
                    <i class="fa-solid fa-graduation-cap" style="font-size:2.2rem; margin-bottom:10px; display:block; color:var(--brand-green);"></i>
                    <strong>No hay grados o secciones que coincidan con los filtros.</strong><br>
                    <span style="font-size:0.85rem;">Haga clic en <strong>"Registrar Nuevo Grado y Sección"</strong> para agregar.</span>
                </td>
            </tr>
        `;
        return;
    }

        tbody.innerHTML = list.map(g => {
        const count = typeof getStudentCountByGradeAndSection === 'function' ? getStudentCountByGradeAndSection(g.code, g.name, g.section) : 0;
        const guideInfo = typeof getGradeGuideTeacher === 'function' ? getGradeGuideTeacher(g) : { name: (g.guideTeacher || 'Sin asignar') };
        const guideUser = guideInfo.user;
        const isAssigned = (guideInfo.name && guideInfo.name !== 'Sin asignar');

        const guideDisplay = isAssigned
            ? `<div style="display:flex; flex-direction:column; gap:2px;">
                 <strong style="color:#0f172a; font-size:0.88rem; display:flex; align-items:center; gap:5px;">
                   <i class="fa-solid fa-chalkboard-user" style="color:#15803d; font-size:0.85rem;"></i>
                   ${escapeHtml(guideInfo.name)}
                 </strong>
                 ${guideUser?.telefono ? `<div style="font-size:0.72rem; font-weight:600; color:#047857; display:flex; align-items:center; gap:4px; margin-left:18px;" title="Teléfono: ${guideUser.telefono}"><i class="fa-solid fa-phone" style="font-size:0.65rem;"></i> ${guideUser.telefono}</div>` : ''}
               </div>`
            : `<span style="color:var(--text-muted); font-style:italic;">Sin asignar</span>`;

        return `
        <tr>
            <td><span class="badge badge-info" style="font-weight:700;">${g.career || 'Perito Contador'}</span></td>
            <td><strong>${g.name}</strong></td>
            <td><code style="font-weight:800; color:var(--brand-green-dark);">${g.code}</code></td>
            <td><span class="badge badge-success" style="font-weight:700;">${g.section}</span></td>
            <td><span class="badge" style="background:#f1f5f9; color:#334155; font-weight:700;">${g.shift || 'Matutina'}</span></td>
            <td>${guideDisplay}</td>
            <td style="text-align:center;">
                <span class="badge badge-primary" style="font-weight:800; cursor:pointer;" onclick="openSectionStudentsModal('${g.code}')" title="Ver estudiantes de esta sección">
                    <i class="fa-solid fa-users"></i> ${count} alumnos
                </span>
            </td>
            <td style="text-align:center; white-space:nowrap;">
                <button type="button" class="btn btn-sm btn-outline-primary" onclick="openEditGradeModal('${g.id}')" title="Editar grado" style="padding:3px 8px; margin-right:4px;"><i class="fa-solid fa-pen-to-square"></i></button>
                <button type="button" class="btn btn-sm btn-outline-danger" onclick="deleteGrade('${g.id}')" title="Eliminar grado" style="padding:3px 8px;"><i class="fa-solid fa-trash"></i></button>
            </td>
        </tr>
        `;
    }).join('');
}

function updatePensumCatalogSelects() {
    const careerSelect = document.getElementById('pensumSubjectFormCareer') || document.getElementById('pensumSubjectCareer');
    const gradeSelect = document.getElementById('pensumSubjectFormGrade') || document.getElementById('pensumSubjectGrade');
    const careerFilter = document.getElementById('pensumCatalogCareerFilter');
    const gradeFilter = document.getElementById('pensumCatalogGradeFilter');

    const careers = STATE.careers || [];
    const careerOptions = careers.map(c => `<option value="${c.name}">${c.name}</option>`).join('');

    if (careerSelect) {
        const curVal = careerSelect.value;
        careerSelect.innerHTML = careerOptions || '<option value="Perito Contador">Perito Contador</option>';
        if (curVal && Array.from(careerSelect.options).some(o => o.value === curVal)) {
            careerSelect.value = curVal;
        }
    }

    if (careerFilter) {
        const curVal = careerFilter.value;
        careerFilter.innerHTML = '<option value="ALL">Todas las Carreras</option>' + careerOptions;
        if (curVal && Array.from(careerFilter.options).some(o => o.value === curVal)) {
            careerFilter.value = curVal;
        }
    }

    const gradeNames = [
        { code: '4TO', label: '4to Grado (4to Perito)' },
        { code: '5TO', label: '5to Grado (5to Perito)' },
        { code: '6TO', label: '6to Grado (6to Perito)' }
    ];

    const gradeOptions = gradeNames.map(g => `<option value="${g.code}">${g.label}</option>`).join('');

    if (gradeSelect) {
        const curVal = gradeSelect.value;
        gradeSelect.innerHTML = '<option value="">-- Seleccione Grado --</option>' + gradeOptions;
        if (curVal && Array.from(gradeSelect.options).some(o => o.value === curVal)) {
            gradeSelect.value = curVal;
        }
    }

    if (gradeFilter) {
        const curVal = gradeFilter.value;
        gradeFilter.innerHTML = '<option value="ALL">Todos los Grados</option>' + gradeOptions;
        if (curVal && Array.from(gradeFilter.options).some(o => o.value === curVal)) {
            gradeFilter.value = curVal;
        }
    }
}

