function openPensumSubjectModal(defaultGrade = null) {
    if (!checkEnrolmentPermissions()) return;
    const form = document.querySelector('#pensumSubjectModal form') || document.getElementById('pensumSubjectForm');
    if (form && typeof form.reset === 'function') form.reset();

    const idInput = document.getElementById('pensumSubjectFormId') || document.getElementById('pensumSubjectModalId');
    if (idInput) idInput.value = '';

    const titleEl = document.getElementById('pensumSubjectModalTitle');
    if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-book-open-reader"></i> Registrar Asignatura en Pensum';

    updatePensumCatalogSelects();

    const gradeSelect = document.getElementById('pensumSubjectFormGrade') || document.getElementById('pensumSubjectGrade');
    if (gradeSelect) {
        const targetG = defaultGrade || (typeof currentPensumActiveGradeTab !== 'undefined' && currentPensumActiveGradeTab !== 'all' ? currentPensumActiveGradeTab : null);
        if (targetG) {
            const rawG = String(targetG).toUpperCase();
            if (rawG.includes('4') || rawG.includes('CUARTO')) gradeSelect.value = '4TO';
            else if (rawG.includes('5') || rawG.includes('QUINTO')) gradeSelect.value = '5TO';
            else if (rawG.includes('6') || rawG.includes('SEXTO')) gradeSelect.value = '6TO';
            else gradeSelect.value = targetG;
        }
    }

    const career = document.getElementById('pensumSubjectFormCareer')?.value || 'Perito Contador';
    const grade = document.getElementById('pensumSubjectFormGrade')?.value || '4to Perito Contador';
    const codeInput = document.getElementById('pensumSubjectFormCode');
    if (codeInput) {
        codeInput.value = suggestNextPensumCourseCode(career, grade);
    }

    showModalById('pensumSubjectModal');
}

function openEditPensumSubjectModal(subjectId) {
    if (!checkEnrolmentPermissions()) return;
    const s = (STATE.pensumCatalog || []).find(x => x.id === subjectId);
    if (!s) {
        showToast('Asignatura no encontrada.', 'warning');
        return;
    }

    updatePensumCatalogSelects();

    const idInput = document.getElementById('pensumSubjectFormId') || document.getElementById('pensumSubjectModalId');
    const codeInput = document.getElementById('pensumSubjectFormCode');
    const nameInput = document.getElementById('pensumSubjectFormName') || document.getElementById('pensumSubjectName');
    const careerSelect = document.getElementById('pensumSubjectFormCareer') || document.getElementById('pensumSubjectCareer');
    const gradeSelect = document.getElementById('pensumSubjectFormGrade') || document.getElementById('pensumSubjectGrade');
    const orderInput = document.getElementById('pensumSubjectFormSortOrder') || document.getElementById('pensumSubjectOrder');
    const hoursInput = document.getElementById('pensumSubjectFormHours');

    const subjectName = s.name || s.subject || '';

    if (idInput) idInput.value = s.id;
    if (codeInput) codeInput.value = (s.code || '').trim().toUpperCase() || suggestNextPensumCourseCode(s.career, s.grade);
    if (nameInput) nameInput.value = subjectName;
    if (careerSelect && s.career) careerSelect.value = s.career;
    if (gradeSelect && s.grade) gradeSelect.value = s.grade;
    if (orderInput) orderInput.value = s.order || s.sortOrder || 1;
    if (hoursInput) hoursInput.value = s.hours || s.periods || 4;

    const titleEl = document.getElementById('pensumSubjectModalTitle');
    if (titleEl) titleEl.innerHTML = `<i class="fa-solid fa-pen-to-square"></i> Editar Asignatura "${subjectName}"`;

    const submitBtn = document.getElementById('pensumSubjectSubmitBtn') || (document.getElementById('pensumSubjectModal') ? document.getElementById('pensumSubjectModal').querySelector('button[type="submit"]') : null);
    if (submitBtn) {
        submitBtn.disabled = false;
        if (submitBtn.getAttribute('data-orig-html')) {
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html');
        }
    }

    showModalById('pensumSubjectModal');
}

function closePensumSubjectModal() {
    const modal = document.getElementById('pensumSubjectModal');
    if (modal) {
        modal.classList.remove('active');
        modal.style.setProperty('display', 'none', 'important');
    }
}

async function savePensumSubjectForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    if (!checkEnrolmentPermissions()) return;

    const submitBtn = document.getElementById('pensumSubjectSubmitBtn') || document.querySelector('#pensumSubjectModal form button[type="submit"]');
    const origBtnHtml = submitBtn ? (submitBtn.getAttribute('data-orig-html') || submitBtn.innerHTML) : '<i class="fa-solid fa-save"></i> Guardar en Pensum';
    if (submitBtn && !submitBtn.getAttribute('data-orig-html')) {
        submitBtn.setAttribute('data-orig-html', origBtnHtml);
    }

    const idInput = document.getElementById('pensumSubjectFormId') || document.getElementById('pensumSubjectModalId');
    const codeInput = document.getElementById('pensumSubjectFormCode');
    const nameInput = document.getElementById('pensumSubjectFormName') || document.getElementById('pensumSubjectName');
    const careerSelect = document.getElementById('pensumSubjectFormCareer') || document.getElementById('pensumSubjectCareer');
    const gradeSelect = document.getElementById('pensumSubjectFormGrade') || document.getElementById('pensumSubjectGrade');
    const orderInput = document.getElementById('pensumSubjectFormSortOrder') || document.getElementById('pensumSubjectOrder');
    const hoursInput = document.getElementById('pensumSubjectFormHours');

    const titleEl = document.getElementById('pensumSubjectModalTitle');
    const asignaturaId = idInput ? (idInput.value || '').trim() : '';
    const isEditing = Boolean(asignaturaId) || (titleEl && titleEl.textContent && titleEl.textContent.includes('Editar Asignatura'));

    // 🚨 2. Verificación de Referencia e ID de Documento en Firebase
    if (isEditing) {
        if (!asignaturaId || asignaturaId === 'undefined' || asignaturaId === 'null') {
            console.error("Error: ID de la asignatura no encontrado o indefinido.");
            if (typeof Swal !== 'undefined' && Swal.fire) {
                Swal.fire({
                    icon: 'error',
                    title: 'ID no encontrado',
                    text: 'Error: ID de la asignatura no encontrado o indefinido.'
                });
            } else {
                showToast("Error: ID de la asignatura no encontrado o indefinido.", "danger");
            }
            return;
        }
    }

    const code = codeInput ? codeInput.value.trim().toUpperCase() : '';
    const name = nameInput ? nameInput.value.trim() : '';
    const career = careerSelect ? careerSelect.value : '';
    const grade = gradeSelect ? gradeSelect.value : '';
    const order = orderInput ? parseInt(orderInput.value) || 1 : 1;
    const hours = hoursInput ? parseInt(hoursInput.value) || 4 : 4;

    if (!name || !career || !grade) {
        if (typeof Swal !== 'undefined' && Swal.fire) {
            Swal.fire({
                icon: 'warning',
                title: 'Campos requeridos',
                text: 'Complete todos los campos obligatorios (Nombre, Carrera y Grado).'
            });
        } else {
            showToast('Complete todos los campos obligatorios (Nombre, Carrera y Grado).', 'warning');
        }
        return;
    }

    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    try {
        if (!Array.isArray(STATE.pensumCatalog)) STATE.pensumCatalog = [];

        let targetId = asignaturaId;

        if (isEditing || targetId) {
            let idx = STATE.pensumCatalog.findIndex(x => x && x.id === targetId);
            if (idx === -1 && targetId) {
                idx = STATE.pensumCatalog.findIndex(x => x && (x.code === code || (x.name || x.subject) === name));
            }

            if (idx !== -1) {
                targetId = STATE.pensumCatalog[idx].id || targetId;
                STATE.pensumCatalog[idx].id = targetId;
                STATE.pensumCatalog[idx].code = code;
                STATE.pensumCatalog[idx].name = name;
                STATE.pensumCatalog[idx].subject = name;
                STATE.pensumCatalog[idx].career = career;
                STATE.pensumCatalog[idx].grade = grade;
                STATE.pensumCatalog[idx].order = order;
                STATE.pensumCatalog[idx].sortOrder = order;
                STATE.pensumCatalog[idx].hours = hours;
                STATE.pensumCatalog[idx].periods = hours;
                STATE.pensumCatalog[idx].weeklyHours = hours;
                STATE.pensumCatalog[idx].lastModified = Date.now();
            } else {
                throw new Error(`No se encontró la asignatura con ID "${targetId}" para actualizar en el catálogo.`);
            }
        } else {
            targetId = code ? ('pen-' + code.toLowerCase().replace(/[^a-z0-9]/g, '')) : ('pen-' + Date.now() + '-' + Math.floor(Math.random()*1000));
            STATE.pensumCatalog.push({
                id: targetId,
                code: code,
                name: name,
                subject: name,
                career: career,
                grade: grade,
                order: order,
                sortOrder: order,
                hours: hours,
                periods: hours,
                weeklyHours: hours,
                lastModified: Date.now()
            });
        }

        // Cascada en STATE.pensum (clases asignadas a docentes)
        (STATE.pensum || []).forEach(asg => {
            if ((asg.subject === name || asg.name === name) && (asg.grade === grade || asg.gradeCode === grade)) {
                asg.code = code;
                asg.hours = hours;
                asg.periodsPerWeek = hours;
            }
        });

        // 0ms Optimistic UI: Persistencia inmediata en caché local y actualización visual
        saveStateToLocalStorage();
        closePensumSubjectModal();
        renderPensumCatalogTable();
        if (typeof renderAssignmentsTable === 'function') renderAssignmentsTable();
        if (typeof updateClassAssignmentSelects === 'function') updateClassAssignmentSelects();
        if (typeof renderDashboard === 'function') renderDashboard();

        const codeLabel = code ? ` [${code}]` : '';
        showToast(`Asignatura "${name}"${codeLabel} guardada exitosamente.`, 'success');

        // 🌟 Sincronización atómica en segundo plano con Firestore y Realtime Database
        (async () => {
            const nowTime = Date.now();
            if (window.FirebaseModular && window.FirebaseModular.db) {
                try {
                    const { db, doc, setDoc } = window.FirebaseModular;
                    const targetSubject = (STATE.pensumCatalog || []).find(x => x.id === targetId);
                    if (targetSubject && targetSubject.id && typeof setDoc === 'function') {
                        const subRef = doc(db, 'pensumCatalog', targetSubject.id);
                        const subData = { ...targetSubject, lastModified: nowTime };
                        await setDoc(subRef, subData, { merge: true });
                    }
                } catch(fsErr) {
                    console.warn("Aviso al guardar asignatura en Firestore en segundo plano:", fsErr);
                }
            }

            try {
                if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
                    await Promise.all([
                        EnccoCloudSync.syncNode('pensumCatalog', STATE.pensumCatalog),
                        EnccoCloudSync.syncNode('pensum', STATE.pensum)
                    ]);
                }
            } catch(rtErr) {
                console.warn("Aviso al sincronizar pensum en Realtime Database:", rtErr);
            }
        })();
    } catch(err) {
        console.error("❌ Error al procesar asignatura:", err);
        showToast(`Error al procesar asignatura: ${err.message || err}`, 'danger');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html') || origBtnHtml || '<i class="fa-solid fa-save"></i> Guardar en Pensum';
        }
    }
}

function applyUserRole(role = STATE.currentRole) {
    // 🛡️ Principio de Menor Privilegio: NUNCA elevar a 'admin' si el rol es undefined
    if (!role) {
        role = (window.EnccoAuthStore ? window.EnccoAuthStore.getRole() : (window.STATE ? STATE.currentRole : null)) || 'guest';
    }
    STATE.currentRole = role;

    const user = STATE.currentUser || (STATE.users || []).find(u => u.role === role) || { name: 'Usuario', role: role };
    const initials = (user.name || 'US').split(' ').map(n => n[0]).join('').slice(0, 2);

    const avatarEl = document.getElementById('userAvatar');
    const nameEl = document.getElementById('userName');
    const badgeEl = document.getElementById('userRoleBadge');
    const currentRoleTextEl = document.getElementById('currentRoleText');
    const loggedDisplayEl = document.getElementById('loggedUserDisplay');

    if (avatarEl) avatarEl.textContent = initials;
    if (nameEl) nameEl.textContent = user.name;
    if (badgeEl) badgeEl.className = 'user-role-badge role-' + role;

    const roles = STATE.rolesConfig || (typeof getInitialData === 'function' && getInitialData().rolesConfig) || [];
    const matchedRoleObj = roles.find(r => r.key === role);
    const isDirUser = (typeof isDirectorRole === 'function' && isDirectorRole(role)) || role === 'director';
    const isSuperUser = (typeof isSuperUserRole === 'function' && isSuperUserRole(role)) || role === 'admin';
    const activeTitle = matchedRoleObj ? matchedRoleObj.name : (isDirUser ? 'Director de la Escuela' : (isSuperUser ? 'Super Administrador' : (role === 'docente' ? 'Catedrático Titular' : role)));

    if (badgeEl) badgeEl.textContent = activeTitle;
    if (currentRoleTextEl) currentRoleTextEl.textContent = `Acceso: ${activeTitle}`;
    if (loggedDisplayEl) loggedDisplayEl.textContent = `${user.name} (${activeTitle})`;

    // Aplicar visibilidad granular estricta según la configuración de roles del administrador
    normalizeRolesConfig();

    const isSuper = (typeof isSuperUserRole === 'function' && isSuperUserRole(role)) || 
                    (typeof isDirectorRole === 'function' && isDirectorRole(role)) || 
                    ['admin', 'super_usuario', 'superadmin', 'director', 'direccion', 'directora'].includes(role);

    // 1. Renderizado Dinámico e Interactivo del Menú Lateral por RBAC
    if (typeof renderDynamicSidebarRBAC === 'function') {
        renderDynamicSidebarRBAC(role);
    }

    // 3. Otros elementos restringidos de la interfaz
    document.querySelectorAll('.role-restricted, [data-perm]').forEach(el => {
        if (el.classList.contains('nav-item') || el.classList.contains('nav-section-label')) return;

        const permKey = el.dataset.perm || el.dataset.view;
        const allowed = el.dataset.allowed ? el.dataset.allowed.split(',').map(r => r.trim().toLowerCase()) : null;

        let hasPerm = false;
        if (isSuper) {
            hasPerm = true;
        } else if (permKey) {
            hasPerm = hasRolePermission(permKey, role);
            if (hasPerm && allowed && !allowed.includes('*')) {
                hasPerm = allowed.includes(role.toLowerCase());
            }
        } else if (allowed) {
            hasPerm = allowed.includes('*') || allowed.includes(role.toLowerCase());
        }

        if (hasPerm) {
            el.style.removeProperty('display');
            el.classList.remove('hidden');
        } else {
            el.style.setProperty('display', 'none', 'important');
            el.classList.add('hidden');
        }
    });

    // 4. Redirigir al inicio si la vista activa actual está bloqueada para el rol
    if (!isSuper && STATE.activeView && STATE.activeView !== 'dashboard' && !hasRolePermission(STATE.activeView, role)) {
        if (typeof navigateTo === 'function') {
            navigateTo('dashboard');
        }
    }

    // Actualizar los selectores de roles en modales y filtros
    if (typeof updateUserRoleSelectOptions === 'function') updateUserRoleSelectOptions();

    if (typeof updateTopRoleBar === 'function') updateTopRoleBar();
    if (typeof updateUserAlertsUI === 'function') updateUserAlertsUI();
    if (typeof renderTeacherCourseCards === 'function') renderTeacherCourseCards();
}
window.applyUserRole = applyUserRole;



function updateUserRoleSelectOptions() {
    const userFormRole = document.getElementById('userFormRole');
    const userRoleFilterSelect = document.getElementById('userRoleFilterSelect');
    const userRole = document.getElementById('userRole');
    const roles = STATE.rolesConfig || (typeof getInitialData === 'function' && getInitialData().rolesConfig) || [];

    const optionsHtml = roles.map(r => `<option value="${r.key}">${r.name}</option>`).join('');

    if (userFormRole) {
        const cur = userFormRole.value;
        userFormRole.innerHTML = optionsHtml;
        if (cur && roles.some(r => r.key === cur)) userFormRole.value = cur;
    }

    if (userRole) {
        const cur = userRole.value;
        userRole.innerHTML = optionsHtml;
        if (cur && roles.some(r => r.key === cur)) userRole.value = cur;
    }

    if (userRoleFilterSelect) {
        const cur = userRoleFilterSelect.value;
        const quickOptions = `
            <option value="ALL">⭐ Todos los Roles</option>
            <option value="docente">👨‍🏫 Solo Catedráticos</option>
            <option value="admin,director,secretaria">🏛️ Directivos / Admin</option>
            <option value="profesor_auxiliar">🛡️ Auxiliares / Disciplina</option>
        `;
        const extraRoles = roles.filter(r => !['docente', 'admin', 'director', 'secretaria', 'profesor_auxiliar'].includes(r.key))
            .map(r => `<option value="${r.key}">${r.name}</option>`).join('');
        userRoleFilterSelect.innerHTML = quickOptions + extraRoles;
        if (cur && (cur === 'ALL' || cur === 'admin,director,secretaria' || roles.some(r => r.key === cur))) {
            userRoleFilterSelect.value = cur;
        }
    }
}



