async function deleteUser(userId) {
    const isSuperOrDir = (typeof isSuperUserRole === 'function' && isSuperUserRole()) || (typeof isDirectorRole === 'function' && isDirectorRole());
    if (!isSuperOrDir && typeof EnccoSecurityShield !== 'undefined' && !EnccoSecurityShield.isAuthorizedRole('admin')) {
        if (typeof showToast === 'function') showToast('Acceso denegado: Eliminación de usuarios restringida a Administrador o Dirección.', 'danger');
        return;
    }
    const user = (STATE.users || []).find(u => u.id === userId);
    if (!user) {
        showToast("Usuario no encontrado.", "warning");
        return;
    }

    const oldName = user.name;
    const confirmed = (window.EnccoDialog && typeof window.EnccoDialog.confirm === 'function')
        ? await window.EnccoDialog.confirm({
            title: 'Eliminar Usuario / Docente',
            message: `¿Está seguro de eliminar al docente o usuario "${oldName}"? Esta acción desvinculará sus cátedras asignadas.`,
            confirmText: 'Sí, eliminar usuario',
            cancelText: 'Cancelar',
            type: 'danger'
        })
        : false;

    if (confirmed) {
        STATE.deletedUserIds = STATE.deletedUserIds || [];
        if (!STATE.deletedUserIds.includes(userId)) {
            STATE.deletedUserIds.push(userId);
        }

        STATE.users = (STATE.users || []).filter(u => u.id !== userId);
        
        // Desvincular en cátedras
        (STATE.pensum || []).forEach(a => {
            if (a.teacherId === userId || a.teacher === oldName) {
                a.teacher = 'Sin asignar';
                a.teacherId = null;
            }
        });

        // Desvincular en grados guías
        (STATE.gradesList || []).forEach(g => {
            if (g.guideTeacherId === userId || g.guideTeacher === oldName) {
                g.guideTeacher = 'Sin asignar';
                g.guideTeacherId = null;
            }
        });

        // 1. Guardar localmente
        STATE.lastModified = Date.now();
        saveStateToLocalStorage();

        // 2. Refrescar la tabla en pantalla
        renderUsersTable();

        // 3. Sincronizar UI global y Dashboard
        try {
            if (typeof synchronizeGlobalDynamicUI === 'function') synchronizeGlobalDynamicUI();
            if (typeof renderDashboard === 'function') renderDashboard();
        } catch(uiErr) {}

        // 4. Sincronizar de inmediato con Firebase (Firestore + Realtime DB) en segundo plano
        (async () => {
            if (window.FirebaseModular && window.FirebaseModular.db) {
                try {
                    const { db, doc, deleteDoc } = window.FirebaseModular;
                    if (typeof deleteDoc === 'function') {
                        deleteDoc(doc(db, 'users', userId)).catch(e => console.warn("Aviso Firestore users delete:", e));
                        deleteDoc(doc(db, 'docentes', userId)).catch(e => console.warn("Aviso Firestore docentes delete:", e));
                    }
                } catch(fsErr) {
                    console.warn("Aviso al eliminar usuario en Firestore:", fsErr);
                }
            }

            if (typeof EnccoCloudSync !== 'undefined') {
                try {
                    if (typeof EnccoCloudSync.deleteNode === 'function') {
                        EnccoCloudSync.deleteNode('users/' + userId);
                        EnccoCloudSync.deleteNode('docentes/' + userId);
                    }
                    if (typeof EnccoCloudSync.syncNode === 'function') {
                        EnccoCloudSync.syncNode('users', STATE.users);
                        EnccoCloudSync.syncNode('pensum', STATE.pensum);
                        EnccoCloudSync.syncNode('gradesList', STATE.gradesList);
                    }
                } catch(rtdbErr) {
                    console.warn("Aviso al sincronizar en RTDB:", rtdbErr);
                }
            } else if (typeof syncUsersToDatabaseImmediate === 'function') {
                syncUsersToDatabaseImmediate(false);
            }
        })();

        showToast(`Usuario "${oldName}" eliminado exitosamente.`, "success");
    }
}


