function openGradeModal() {
    if (STATE.currentRole === 'docente' || STATE.currentRole === 'estudiante') {
        showToast('Acceso denegado: El personal docente no tiene acceso al Editor de Grados y Secciones.', 'warning');
        return;
    }
    if (!checkEnrolmentPermissions()) return;
    const form = document.querySelector('#gradeModal form');
    if (form) form.reset();

    const idInput = document.getElementById('gradeFormId') || document.getElementById('gradeModalId');
    if (idInput) idInput.value = '';

    const titleEl = document.getElementById('gradeModalTitle');
    if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-graduation-cap"></i> Registrar Grado y Sección';

    const multiBox = document.getElementById('multiSectionContainer');
    const singleBox = document.getElementById('singleSectionContainer');
    if (multiBox) multiBox.style.display = 'block';
    if (singleBox) singleBox.style.display = 'none';

    // Restablecer pills de secciones activas (por defecto Sección A activada)
    document.querySelectorAll('#quickSectionBadges .section-pill').forEach((btn, i) => {
        if (i === 0) btn.classList.add('active');
        else btn.classList.remove('active');
    });

    // Poblar select de carreras
    updateCareerSelects();
    const careerSelect = document.getElementById('gradeFormCareer') || document.getElementById('gradeModalCareer');
    if (careerSelect) {
        const careers = STATE.careers || [];
        careerSelect.innerHTML = careers.map(c => `<option value="${c.name}">${c.name}</option>`).join('') || '<option value="Perito Contador">Perito Contador</option>';
    }

    // Poblar select de Maestro Guía
    const guideSelect = document.getElementById('gradeFormGuideTeacher');
    if (guideSelect) {
        const teachers = (STATE.users || []).filter(u => u.role === 'docente' || u.id.startsWith('usr-doc-'));
        guideSelect.innerHTML = '<option value="">-- Sin Maestro Guía Asignado --</option>' + teachers.map(t => `<option value="${t.name}">${t.name}</option>`).join('');
    }

    showModalById('gradeModal');
}

