async function saveGradeForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    if (STATE.currentRole === 'docente' || STATE.currentRole === 'estudiante') {
        showToast('Acceso denegado: No tiene permisos para guardar grados ni secciones.', 'danger');
        return;
    }
    if (!checkEnrolmentPermissions()) return;

    const idInput = document.getElementById('gradeFormId') || document.getElementById('gradeModalId');
    const nameInput = document.getElementById('gradeFormName') || document.getElementById('gradeModalName');
    const careerSelect = document.getElementById('gradeFormCareer') || document.getElementById('gradeModalCareer');
    const shiftSelect = document.getElementById('gradeFormShift');
    const sectionInput = document.getElementById('gradeFormSection') || document.getElementById('gradeModalSection');
    const codeInput = document.getElementById('gradeFormCode') || document.getElementById('gradeModalCode');
    const guideSelect = document.getElementById('gradeFormGuideTeacher');
    const customSectionsInput = document.getElementById('gradeFormCustomSections');

    const id = idInput ? idInput.value.trim() : '';
    const name = nameInput ? nameInput.value.trim() : '';
    const career = careerSelect ? careerSelect.value : 'Perito Contador';
    const shift = shiftSelect ? shiftSelect.value : 'Matutina';
    const guideTeacher = guideSelect ? guideSelect.value : '';

    const titleEl = document.getElementById('gradeModalTitle');
    const isEditing = Boolean(id) || (titleEl && titleEl.textContent && titleEl.textContent.includes('Editar'));

    // 🚨 2. Verificación de Referencia e ID de Documento en Firebase
    if (isEditing) {
        if (!id || id === 'undefined' || id === 'null') {
            console.error("Error: ID del grado no encontrado o indefinido.");
            showToast("Error: ID del grado no encontrado o indefinido.", "danger");
            return;
        }
    }

    if (!name || !career) {
        showToast('Complete el nombre del grado y seleccione la carrera.', 'warning');
        return;
    }

    if (!Array.isArray(STATE.gradesList)) STATE.gradesList = [];

    const submitBtn = document.getElementById('gradeSubmitBtn') || document.querySelector('#gradeModal form button[type="submit"]');
    const origBtnHtml = submitBtn ? (submitBtn.getAttribute('data-orig-html') || submitBtn.innerHTML) : 'Guardar Grado(s)';
    if (submitBtn && !submitBtn.getAttribute('data-orig-html')) {
        submitBtn.setAttribute('data-orig-html', origBtnHtml);
    }

    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> Guardando en Firebase...';
    }

    try {
        if (id) {
            // Modo edición de grado existente
            const idx = STATE.gradesList.findIndex(x => x.id === id);
            if (idx !== -1) {
                const secVal = sectionInput ? sectionInput.value.trim() : STATE.gradesList[idx].section;
                const codeVal = codeInput ? codeInput.value.trim() : STATE.gradesList[idx].code;
                STATE.gradesList[idx].name = name;
                STATE.gradesList[idx].career = career;
                STATE.gradesList[idx].shift = shift;
                STATE.gradesList[idx].section = secVal;
                STATE.gradesList[idx].code = codeVal || `${name} ${secVal}`;
                const guideUserObj = (STATE.users || []).find(u => u.id === guideTeacher || u.name === guideTeacher);
                STATE.gradesList[idx].guideTeacherId = guideUserObj ? guideUserObj.id : (guideTeacher || null);
                STATE.gradesList[idx].guideTeacher = guideUserObj ? guideUserObj.name : (guideTeacher || 'Sin asignar');
            } else {
                throw new Error(`Grado con ID "${id}" no encontrado en memoria.`);
            }
        } else {
            // Modo creación: recopilar secciones seleccionadas
            let selectedSections = [];
            document.querySelectorAll('#quickSectionBadges .section-pill.active').forEach(b => {
                selectedSections.push(b.textContent.trim());
            });

            if (customSectionsInput && customSectionsInput.value.trim()) {
                const customs = customSectionsInput.value.split(',').map(s => s.trim()).filter(Boolean);
                customs.forEach(c => {
                    const sName = c.toLowerCase().startsWith('sección') ? c : `Sección ${c}`;
                    if (!selectedSections.includes(sName)) selectedSections.push(sName);
                });
            }

            if (selectedSections.length === 0) selectedSections = ['Sección A'];

            // Crear cada grado/sección
            selectedSections.forEach(sec => {
                const shortSec = sec.replace('Sección', '').trim();
                const code = `${name.replace('Perito Contador', 'PC').trim()} ${shortSec}`;
                const guideUserObj = (STATE.users || []).find(u => u.id === guideTeacher || u.name === guideTeacher);
                STATE.gradesList.push({
                    id: 'grd-' + Date.now() + '-' + Math.floor(Math.random()*1000),
                    name: name,
                    career: career,
                    shift: shift,
                    section: sec,
                    code: code,
                    guideTeacherId: guideUserObj ? guideUserObj.id : (guideTeacher || null),
                    guideTeacher: guideUserObj ? guideUserObj.name : (guideTeacher || 'Sin asignar')
                });
            });
        }

        STATE.gradesList = sortGrades(STATE.gradesList);
        const nowTime = Date.now();
        STATE.lastModified = nowTime;

        // 🌟 A. Persistencia Atómica en Firestore
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, updateDoc, setDoc } = window.FirebaseModular;
                const targetGrades = id ? [STATE.gradesList.find(x => x.id === id)].filter(Boolean) : STATE.gradesList.filter(g => g.name === name);
                for (const grd of targetGrades) {
                    if (!grd) continue;
                    const gRef = doc(db, 'gradesList', grd.id || grd.code);
                    const gsRef = doc(db, 'grados_secciones', grd.id || grd.code);
                    const gPayload = { ...grd, lastModified: nowTime };
                    const fsAction = (typeof setDoc === 'function')
                    ? setDoc(gRef, gPayload, { merge: true })
                    : ((typeof updateDoc === 'function')
                        ? updateDoc(gRef, gPayload).catch(e => {
                            if (typeof setDoc === 'function') return setDoc(gRef, gPayload, { merge: true });
                            throw e;
                        })
                        : Promise.resolve());
                    await withTimeout(fsAction, 8000, 'Tiempo de espera en Firestore agotado.');
                    if (typeof setDoc === 'function') {
                        await setDoc(gsRef, gPayload, { merge: true });
                    }
                }
            } catch(fsErr) {
                console.warn("Aviso al persistir grados en Firestore:", fsErr);
            }
        }

        // 🌟 B. Sincronización Atómica y Aislada en Realtime Database
        let ok = false;
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            ok = await withTimeout(EnccoCloudSync.syncNode('gradesList', STATE.gradesList), 8000, 'Tiempo de espera agotado en Realtime Database.');
        } else {
            ok = true;
        }

        if (!ok) {
            throw new Error("El servidor de Firebase no confirmó la escritura de grados y secciones.");
        }

        saveStateToLocalStorage();
        closeGradeModal();
        updateGradeSelects();
        renderGradesTable();
        if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
        if (typeof renderDashboard === 'function') renderDashboard();

        showToast(`Grado "${name}" guardado y confirmado en Firebase con éxito.`, 'success');
    } catch(err) {
        console.error("❌ Error al guardar grado:", err);
        showToast(`Error al guardar en Firebase: ${err.message || err}`, 'danger');
    } finally {
        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = submitBtn.getAttribute('data-orig-html') || origBtnHtml;
        }
    }
}

async function deleteGrade(gradeId) {
    const isSuperOrDir = (typeof isSuperUserRole === 'function' && isSuperUserRole()) || (typeof isDirectorRole === 'function' && isDirectorRole());
    if (!isSuperOrDir && (STATE.currentRole === 'docente' || STATE.currentRole === 'estudiante')) {
        showToast('Acceso denegado: No tiene permisos para eliminar grados.', 'danger');
        return;
    }
    if (!checkEnrolmentPermissions()) return;
    const g = (STATE.gradesList || []).find(x => x.id === gradeId);
    if (!g) return;

    const confirmed = (window.EnccoDialog && typeof window.EnccoDialog.confirm === 'function')
        ? await window.EnccoDialog.confirm({
            title: 'Eliminar Grado / Sección',
            message: `¿Está seguro de eliminar el grado "${g.name} (${g.section})"? Esta acción no se puede deshacer.`,
            confirmText: 'Sí, eliminar grado',
            cancelText: 'Cancelar',
            type: 'danger'
        })
        : false;

    if (confirmed) {
        STATE.gradesList = (STATE.gradesList || []).filter(x => x.id !== gradeId);
        saveStateToLocalStorage();

        // 🌟 A. Eliminación Quirúrgica en Firestore
        if (window.FirebaseModular && window.FirebaseModular.db) {
            try {
                const { db, doc, deleteDoc } = window.FirebaseModular;
                if (typeof deleteDoc === 'function') {
                    deleteDoc(doc(db, 'gradesList', gradeId));
                    deleteDoc(doc(db, 'grados_secciones', gradeId));
                    deleteDoc(doc(db, 'maestros_guias', gradeId));
                }
            } catch(e) {
                console.warn("Aviso al eliminar grado en Firestore:", e);
            }
        }

        // 🌟 B. Sincronización Atómica en RTDB
        if (typeof EnccoCloudSync !== 'undefined' && EnccoCloudSync.syncNode) {
            EnccoCloudSync.syncNode('gradesList', STATE.gradesList);
        }

        updateGradeSelects();
        renderGradesTable();
        if (typeof renderGuideTeachersView === 'function') renderGuideTeachersView();
        if (typeof renderDashboard === 'function') renderDashboard();
        showToast(`Grado "${g.name} (${g.section})" eliminado.`, 'info');
    }
}





// ==========================================================================
// 🎛️ CONTROLADOR INTEGRAL Y VISUAL DE ASIGNACIÓN DE CÁTEDRAS A DOCENTES (OPCIÓN 1)
// ==========================================================================

let currentAssignmentsViewMode = 'matrix'; // Opción 1: Matriz Curricular por Grado por defecto
let currentActiveGradeTab = '4to';
let currentAssignmentQuickFilter = 'ALL';

function escapeHtmlAttr(str) {
    if (!str) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/'/g, '&#39;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

function isGradeMatch(gradeStr, gradeKey) {
    if (!gradeStr || !gradeKey) return false;
    const g = String(gradeStr).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const k = String(gradeKey).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    if (k.includes('4') || k.includes('cuarto')) return g.includes('4') || g.includes('cuarto');
    if (k.includes('5') || k.includes('quinto')) return g.includes('5') || g.includes('quinto');
    if (k.includes('6') || k.includes('sexto')) return g.includes('6') || g.includes('sexto');
    return g.includes(k) || k.includes(g);
}

function isSectionMatch(secStr, targetSec) {
    if (!secStr || !targetSec) return false;
    const s1 = String(secStr).trim().toLowerCase();
    const s2 = String(targetSec).trim().toLowerCase();
    if (s1 === s2) return true;
    const letter1 = s1.replace(/[^a-z]/gi, '').slice(-1);
    const letter2 = s2.replace(/[^a-z]/gi, '').slice(-1);
    return letter1 && letter2 && letter1 === letter2;
}

function isSubjectMatch(sub1, sub2, gradeNum = 0) {
    if (!sub1 || !sub2) return false;
    const n1 = getFullOfficialSubjectName(sub1, gradeNum).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const n2 = getFullOfficialSubjectName(sub2, gradeNum).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return n1 === n2 || n1.includes(n2) || n2.includes(n1);
}

function printGradeAssignmentsDirect(gradeName) {
    if (typeof printClassAssignmentsReport === 'function') {
        printClassAssignmentsReport('BY_GRADE', gradeName);
    }
}
window.printGradeAssignmentsDirect = printGradeAssignmentsDirect;

function openClassAssignmentModalForGrade(gradeName) {
    openClassAssignmentModal();
    const gradeSelect = document.getElementById('classAssignmentFormGrade');
    if (gradeSelect && gradeName) {
        for (let i = 0; i < gradeSelect.options.length; i++) {
            if (isGradeMatch(gradeSelect.options[i].value, gradeName)) {
                gradeSelect.selectedIndex = i;
                onClassAssignmentGradeChange(gradeSelect.value);
                break;
            }
        }
    }
}
window.openClassAssignmentModalForGrade = openClassAssignmentModalForGrade;

function openQuickAssignMatrixModal(gradeName, sectionName, subjectName, periods) {
    openClassAssignmentModal();
    const gradeSelect = document.getElementById('classAssignmentFormGrade');
    if (gradeSelect && gradeName) {
        for (let i = 0; i < gradeSelect.options.length; i++) {
            if (isGradeMatch(gradeSelect.options[i].value, gradeName)) {
                gradeSelect.selectedIndex = i;
                onClassAssignmentGradeChange(gradeSelect.value);
                break;
            }
        }
    }
    setTimeout(() => {
        const pills = document.querySelectorAll('#classAssignmentSectionsPillsContainer .asg-section-pill');
        pills.forEach(p => {
            const pSec = p.dataset.section || p.textContent.trim();
            const pCode = p.dataset.code || '';
            if (isSectionMatch(pSec, sectionName) || isSectionMatch(pCode, sectionName)) {
                p.classList.add('active');
                const icon = p.querySelector('i');
                if (icon) icon.className = 'fa-solid fa-circle-check';
            } else {
                p.classList.remove('active');
                const icon = p.querySelector('i');
                if (icon) icon.className = 'fa-regular fa-circle';
            }
        });

        const subjectSelect = document.getElementById('classAssignmentFormSubject');
        if (subjectSelect && subjectName) {
            for (let i = 0; i < subjectSelect.options.length; i++) {
                if (subjectSelect.options[i].value.toLowerCase().includes(subjectName.toLowerCase()) || subjectName.toLowerCase().includes(subjectSelect.options[i].value.toLowerCase())) {
                    subjectSelect.selectedIndex = i;
                    break;
                }
            }
            onClassAssignmentSubjectChange(subjectSelect);
        }

        if (periods) {
            const hoursInput = document.getElementById('classAssignmentFormHours') || document.getElementById('classAssignmentFormPeriods');
            if (hoursInput) hoursInput.value = periods;
        }

        checkClassAssignmentConflict();
    }, 50);
}
window.openQuickAssignMatrixModal = openQuickAssignMatrixModal;

