// Helper para normalizar cualquier fecha a formato YYYY-MM-DD estándar
function normalizePermissionDateStr(val) {
    if (!val) return '';
    const s = String(val).trim();
    if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
    if (/^\d{1,2}\/\d{1,2}\/\d{4}/.test(s)) {
        const parts = s.split('/');
        return `${parts[2]}-${String(parts[1]).padStart(2, '0')}-${String(parts[0]).padStart(2, '0')}`;
    }
    const d = new Date(s);
    if (!isNaN(d.getTime())) {
        const pad = n => String(n).padStart(2, '0');
        return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
    }
    return s.slice(0, 10);
}

function setPermissionsDateRange(mode) {
    const fromInput = document.getElementById('permissionsLogDateFrom');
    const toInput = document.getElementById('permissionsLogDateTo');
    const btnAll = document.getElementById('btnQuickPermAll');
    const btnToday = document.getElementById('btnQuickPermToday');
    const btnWeek = document.getElementById('btnQuickPermWeek');
    const btnMonth = document.getElementById('btnQuickPermMonth');

    const buttons = [
        { id: 'all', btn: btnAll },
        { id: 'today', btn: btnToday },
        { id: 'week', btn: btnWeek },
        { id: 'month', btn: btnMonth }
    ];

    buttons.forEach(b => {
        if (!b.btn) return;
        if (b.id === mode) {
            b.btn.className = 'btn btn-xs btn-warning';
            b.btn.style.color = '#ffffff';
            b.btn.style.borderColor = '#d97706';
            b.btn.style.background = '#f59e0b';
        } else {
            b.btn.className = 'btn btn-xs btn-outline-warning';
            b.btn.style.color = '#b45309';
            b.btn.style.borderColor = '#f59e0b';
            b.btn.style.background = 'transparent';
        }
    });

    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const formatYMD = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

    if (mode === 'all') {
        if (fromInput) fromInput.value = '';
        if (toInput) toInput.value = '';
    } else if (mode === 'today') {
        const todayStr = formatYMD(now);
        if (fromInput) fromInput.value = todayStr;
        if (toInput) toInput.value = todayStr;
    } else if (mode === 'week') {
        // Lunes a Viernes de la semana actual
        const dayOfWeek = now.getDay(); // 0 Dom, 1 Lun, ... 6 Sab
        const diffToMonday = (dayOfWeek === 0 ? -6 : 1 - dayOfWeek);
        const monday = new Date(now);
        monday.setDate(now.getDate() + diffToMonday);
        const friday = new Date(monday);
        friday.setDate(monday.getDate() + 4);
        if (fromInput) fromInput.value = formatYMD(monday);
        if (toInput) toInput.value = formatYMD(friday);
    } else if (mode === 'month') {
        const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
        const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
        if (fromInput) fromInput.value = formatYMD(firstDay);
        if (toInput) toInput.value = formatYMD(lastDay);
    }

    renderPermissionsHistoryView(false);
}
window.setPermissionsDateRange = setPermissionsDateRange;

function onPermissionsDateInputChange() {
    const fromInput = document.getElementById('permissionsLogDateFrom');
    const toInput = document.getElementById('permissionsLogDateTo');
    const btnAll = document.getElementById('btnQuickPermAll');
    const btnToday = document.getElementById('btnQuickPermToday');
    const btnWeek = document.getElementById('btnQuickPermWeek');
    const btnMonth = document.getElementById('btnQuickPermMonth');

    const fromVal = fromInput ? (fromInput.value || '').trim() : '';
    const toVal = toInput ? (toInput.value || '').trim() : '';

    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const formatYMD = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
    const todayStr = formatYMD(now);

    const dayOfWeek = now.getDay();
    const diffToMonday = (dayOfWeek === 0 ? -6 : 1 - dayOfWeek);
    const monday = new Date(now);
    monday.setDate(now.getDate() + diffToMonday);
    const friday = new Date(monday);
    friday.setDate(monday.getDate() + 4);
    const mondayStr = formatYMD(monday);
    const fridayStr = formatYMD(friday);

    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    const monthStartStr = formatYMD(firstDay);
    const monthEndStr = formatYMD(lastDay);

    let activeMode = null;
    if (!fromVal && !toVal) {
        activeMode = 'all';
    } else if (fromVal === todayStr && toVal === todayStr) {
        activeMode = 'today';
    } else if (fromVal === mondayStr && toVal === fridayStr) {
        activeMode = 'week';
    } else if (fromVal === monthStartStr && toVal === monthEndStr) {
        activeMode = 'month';
    }

    [
        { id: 'all', btn: btnAll },
        { id: 'today', btn: btnToday },
        { id: 'week', btn: btnWeek },
        { id: 'month', btn: btnMonth }
    ].forEach(item => {
        if (!item.btn) return;
        if (item.id === activeMode) {
            item.btn.className = 'btn btn-xs btn-warning';
            item.btn.style.color = '#ffffff';
            item.btn.style.borderColor = '#d97706';
            item.btn.style.background = '#f59e0b';
        } else {
            item.btn.className = 'btn btn-xs btn-outline-warning';
            item.btn.style.color = '#b45309';
            item.btn.style.borderColor = '#f59e0b';
            item.btn.style.background = 'transparent';
        }
    });

    renderPermissionsHistoryView(false);
}
window.onPermissionsDateInputChange = onPermissionsDateInputChange;

function clearPermissionsFilters() {
    const gradeSelect = document.getElementById('permissionsLogGradeFilter');
    const catSelect = document.getElementById('permissionsLogCategoryFilter');
    const searchInput = document.getElementById('permissionsLogSearchInput');

    if (gradeSelect) gradeSelect.value = 'ALL';
    if (catSelect) catSelect.value = 'ALL';
    if (searchInput) searchInput.value = '';

    setPermissionsDateRange('all');
    if (typeof showToast === 'function') {
        showToast("Filtros restablecidos. Mostrando listado completo.", "info");
    }
}
window.clearPermissionsFilters = clearPermissionsFilters;

function renderPermissionsHistoryView(forceReset = false) {
    const gradeSelect = document.getElementById('permissionsLogGradeFilter');
    const catSelect = document.getElementById('permissionsLogCategoryFilter');
    const fromInput = document.getElementById('permissionsLogDateFrom');
    const toInput = document.getElementById('permissionsLogDateTo');
    const searchInput = document.getElementById('permissionsLogSearchInput');
    const tbody = document.getElementById('permissionsLogTableBody');
    const counterBadge = document.getElementById('permissionsLogCounterBadge');

    if (!tbody) return;

    // Si se invoca con forceReset (al ingresar a la vista), asegurar que por defecto se muestre el listado completo
    if (forceReset) {
        if (fromInput) fromInput.value = '';
        if (toInput) toInput.value = '';
        if (gradeSelect) gradeSelect.value = 'ALL';
        if (catSelect) catSelect.value = 'ALL';
        if (searchInput) searchInput.value = '';

        const btnAll = document.getElementById('btnQuickPermAll');
        const btnToday = document.getElementById('btnQuickPermToday');
        const btnWeek = document.getElementById('btnQuickPermWeek');
        const btnMonth = document.getElementById('btnQuickPermMonth');
        [btnAll, btnToday, btnWeek, btnMonth].forEach(b => {
            if (!b) return;
            if (b === btnAll) {
                b.className = 'btn btn-xs btn-warning';
                b.style.color = '#ffffff';
                b.style.borderColor = '#d97706';
                b.style.background = '#f59e0b';
            } else {
                b.className = 'btn btn-xs btn-outline-warning';
                b.style.color = '#b45309';
                b.style.borderColor = '#f59e0b';
                b.style.background = 'transparent';
            }
        });
    }

    // Vincular listeners reactivos a los controladores de fecha para garantizar filtrado dinámico en cualquier navegador
    if (fromInput && !fromInput._permListenersAttached) {
        ['input', 'change', 'keyup'].forEach(evtName => {
            fromInput.addEventListener(evtName, () => onPermissionsDateInputChange());
        });
        fromInput._permListenersAttached = true;
    }
    if (toInput && !toInput._permListenersAttached) {
        ['input', 'change', 'keyup'].forEach(evtName => {
            toInput.addEventListener(evtName, () => onPermissionsDateInputChange());
        });
        toInput._permListenersAttached = true;
    }

    // Control de visibilidad del botón + Nuevo Permiso en la barra superior
    const curRole = (window.EnccoAuthStore ? window.EnccoAuthStore.getRole() : (window.STATE ? STATE.currentRole : 'guest')) || 'guest';
    const canManagePerms = ['director', 'secretaria', 'profesor_auxiliar', 'auxiliar', 'auxiliatura', 'admin', 'super_usuario'].includes(curRole.toLowerCase());
    const btnNewPerm = document.getElementById('btnNewPermViewToolbar');
    if (btnNewPerm) {
        btnNewPerm.style.display = canManagePerms ? 'inline-flex' : 'none';
    }

    // Poblar select de grados si solo tiene la opción por defecto
    if (gradeSelect && gradeSelect.options.length <= 1) {
        let optHtml = '<option value="ALL">-- Todos los Grados --</option>';
        (STATE.gradesList || []).forEach(g => {
            optHtml += `<option value="${escapeHtml(g.code)}">${escapeHtml(g.name)} - Sección ${escapeHtml(g.section || '')}</option>`;
        });
        gradeSelect.innerHTML = optHtml;
    }

    const selGrade = gradeSelect ? gradeSelect.value : 'ALL';
    const selCat = catSelect ? catSelect.value : 'ALL';
    const dateFromRaw = fromInput ? (fromInput.value || '').trim() : '';
    const dateToRaw = toInput ? (toInput.value || '').trim() : '';
    const searchQuery = (searchInput ? searchInput.value : '').toLowerCase().trim();

    let dateFrom = normalizePermissionDateStr(dateFromRaw);
    let dateTo = normalizePermissionDateStr(dateToRaw);

    // Si el usuario seleccionó fechas invertidas, ordenarlas de forma tolerante y fluida
    let effectiveFrom = dateFrom;
    let effectiveTo = dateTo;
    if (effectiveFrom && effectiveTo && effectiveFrom > effectiveTo) {
        effectiveFrom = dateTo;
        effectiveTo = dateFrom;
    }

    let perms = Array.isArray(STATE.studentPermissions) ? [...STATE.studentPermissions] : [];
    const totalCount = perms.length;

    // Filtro por rango de fechas dinámico (intersección exacta de intervalos)
    if (effectiveFrom || effectiveTo) {
        perms = perms.filter(p => {
            const pStart = normalizePermissionDateStr(p.startDate || p.date || (p.createdAt ? p.createdAt.slice(0, 10) : ''));
            const pEnd = normalizePermissionDateStr(p.endDate || pStart);
            if (!pStart && !pEnd) return true;
            if (effectiveFrom && effectiveTo) {
                return (pStart <= effectiveTo && pEnd >= effectiveFrom);
            } else if (effectiveFrom) {
                return pEnd >= effectiveFrom;
            } else if (effectiveTo) {
                return pStart <= effectiveTo;
            }
            return true;
        });
    }

    // Filtro por grado
    if (selGrade !== 'ALL') {
        perms = perms.filter(p => {
            const pGrade = (p.grade || '').toLowerCase();
            const pSec = (p.section || '').toLowerCase();
            return pGrade.includes(selGrade.toLowerCase()) || `${pGrade} ${pSec}`.includes(selGrade.toLowerCase());
        });
    }

    // Filtro por categoría/motivo
    if (selCat !== 'ALL') {
        perms = perms.filter(p => (p.reasonCategory || '').toLowerCase() === selCat.toLowerCase());
    }

    // Filtro por búsqueda
    if (searchQuery) {
        perms = perms.filter(p => {
            const text = `${p.studentName || ''} ${p.personalCode || ''} ${p.reasonCategory || ''} ${p.reasonDetail || ''} ${p.authorizedBy || ''} ${p.startDate || ''} ${p.endDate || ''}`.toLowerCase();
            return text.includes(searchQuery);
        });
    }

    // Ordenar de más reciente a más antiguo
    perms.sort((a, b) => new Date(b.createdAt || b.startDate) - new Date(a.createdAt || a.startDate));

    // Actualizar badge contador dinámico en tiempo real
    if (counterBadge) {
        const isFiltered = (effectiveFrom || effectiveTo || selGrade !== 'ALL' || selCat !== 'ALL' || searchQuery);
        if (isFiltered) {
            let labelFilter = '';
            if (effectiveFrom && effectiveTo) {
                labelFilter = effectiveFrom === effectiveTo ? ` (${effectiveFrom})` : ` (${effectiveFrom} al ${effectiveTo})`;
            } else if (effectiveFrom) {
                labelFilter = ` (desde ${effectiveFrom})`;
            } else if (effectiveTo) {
                labelFilter = ` (hasta ${effectiveTo})`;
            }
            counterBadge.innerHTML = `<i class="fa-solid fa-filter"></i> Mostrando <strong>${perms.length}</strong> de <strong>${totalCount}</strong> permisos${escapeHtml(labelFilter)}`;
            counterBadge.style.background = '#fef3c7';
            counterBadge.style.color = '#92400e';
            counterBadge.style.borderColor = '#fde68a';
        } else {
            counterBadge.innerHTML = `<i class="fa-solid fa-list-check"></i> Mostrando listado completo: <strong>${perms.length}</strong> permisos`;
            counterBadge.style.background = '#ecfdf5';
            counterBadge.style.color = '#065f46';
            counterBadge.style.borderColor = '#a7f3d0';
        }
    }

    if (perms.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="7" style="text-align:center; padding:35px 20px; color:#64748b;">
                    <i class="fa-solid fa-clipboard-check" style="font-size:2.2rem; color:#fde68a; display:block; margin-bottom:8px;"></i>
                    <strong style="color:#0f172a; font-size:1rem;">Sin registros de permisos de ausencia</strong>
                    <div style="font-size:0.84rem; margin-top:4px;">No se encontraron registros de estudiantes con permisos autorizados bajo los filtros seleccionados.</div>
                    <button type="button" class="btn btn-xs btn-outline-secondary" onclick="clearPermissionsFilters()" style="margin-top:12px; font-weight:700;">
                        <i class="fa-solid fa-rotate-left"></i> Restablecer filtros y ver listado completo
                    </button>
                </td>
            </tr>
        `;
        return;
    }

    tbody.innerHTML = perms.map((p, idx) => {
        const isSingleDay = !p.endDate || p.endDate === p.startDate;
        const dateDisplay = isSingleDay 
            ? `<strong style="color:#0f172a;">${escapeHtml(p.startDate)}</strong>` 
            : `<strong style="color:#0f172a;">${escapeHtml(p.startDate)}</strong><br><small style="color:#64748b;">al ${escapeHtml(p.endDate)}</small>`;
        const refTag = p.docRef ? `<br><small style="color:#64748b;"><i class="fa-solid fa-paperclip"></i> ${escapeHtml(p.docRef)}</small>` : '';

        const isSusp = (typeof isSuspensionPermission === 'function') ? isSuspensionPermission(p) : (p.attendanceCode === 'S' || String(p.reasonCategory || '').toLowerCase().includes('suspens'));
        const isUnjust = !isSusp && isUnjustifiedPermission(p);
        let catBadgeHtml = '';
        if (isSusp) {
            catBadgeHtml = `<span class="badge" style="background:#faf5ff; color:#6b21a8; font-weight:800; font-size:0.75rem; border:1px solid #d8b4fe;"><i class="fa-solid fa-gavel"></i> ${escapeHtml(p.reasonCategory)} (S - Con Derecho a Examen)</span>`;
        } else if (isUnjust) {
            catBadgeHtml = `<span class="badge" style="background:#fee2e2; color:#b91c1c; font-weight:800; font-size:0.75rem; border:1px solid #fca5a5;"><i class="fa-solid fa-lock"></i> ${escapeHtml(p.reasonCategory)} (A Blindada)</span>`;
        } else {
            catBadgeHtml = `<span class="badge" style="background:#ffedd5; color:#c2410c; font-weight:800; font-size:0.75rem; border:1px solid #fed7aa;"><i class="fa-solid fa-check"></i> ${escapeHtml(p.reasonCategory)}</span>`;
        }

        const dateIconColor = isSusp ? '#7c3aed' : (isUnjust ? '#dc2626' : '#d97706');

        return `
            <tr style="border-bottom:1px solid #f1f5f9;">
                <td style="text-align:center; font-weight:700; color:#64748b;">${idx + 1}</td>
                <td style="white-space:nowrap;">
                    <div style="font-size:0.84rem; display:flex; align-items:center; gap:6px;">
                        <i class="fa-solid fa-calendar-check" style="color:${dateIconColor};"></i>
                        <div>${dateDisplay}</div>
                    </div>
                </td>
                <td>
                    <strong style="color:#0f172a; font-size:0.9rem;">${escapeHtml(p.studentName)}</strong>
                    <div style="font-size:0.76rem; color:#64748b;">Código / Carné: <code>${escapeHtml(p.personalCode || 'S/C')}</code></div>
                </td>
                <td>
                    <span style="font-weight:600; color:#334155;">${escapeHtml(p.grade || 'Grado Oficial')} (${escapeHtml(p.section || 'A')})</span>
                </td>
                <td>
                    ${catBadgeHtml}
                    <div style="font-size:0.83rem; margin-top:3px; color:#334155; line-height:1.35;">${escapeHtml(p.reasonDetail)}</div>
                    ${refTag}
                </td>
                <td>
                    <div style="font-size:0.82rem; font-weight:600; color:#0f172a; display:flex; align-items:center; gap:5px;">
                        <i class="fa-solid fa-user-shield" style="color:#10b981;"></i>
                        <span>${escapeHtml(p.authorizedBy || 'Auxiliatura')}</span>
                    </div>
                </td>
                <td style="text-align:center; white-space:nowrap;">
                    <div style="display:flex; gap:4px; justify-content:center; flex-wrap:wrap;">
                        <button type="button" class="btn btn-xs btn-outline-primary" onclick="printStudentPermissionPass('${p.id}')" title="Imprimir Comprobante Oficial de Permiso" style="padding:3px 8px; font-size:0.75rem; font-weight:700;">
                            <i class="fa-solid fa-print"></i> Pase
                        </button>
                        ${canManageStudentPermissions() ? `
                        <button type="button" class="btn btn-xs btn-outline-warning" onclick="openEditStudentPermissionModal('${p.id}')" title="Editar este permiso de ausencia" style="padding:3px 8px; font-size:0.75rem; font-weight:700; color:#b45309; border-color:#f59e0b; background:#fffbeb;">
                            <i class="fa-solid fa-pen-to-square"></i> Editar
                        </button>
                        <button type="button" class="btn btn-xs btn-outline-danger" onclick="revokeStudentPermission('${p.id}')" title="Anular este permiso de ausencia" style="padding:3px 8px; font-size:0.75rem; font-weight:700;">
                            <i class="fa-solid fa-trash"></i>
                        </button>` : ''}
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}
window.renderPermissionsHistoryView = renderPermissionsHistoryView;

function printPermissionsLog() {
    const gradeSelect = document.getElementById('permissionsLogGradeFilter');
    const catSelect = document.getElementById('permissionsLogCategoryFilter');
    const fromInput = document.getElementById('permissionsLogDateFrom');
    const toInput = document.getElementById('permissionsLogDateTo');
    const targetGrade = gradeSelect ? gradeSelect.value : 'ALL';
    const targetCat = catSelect ? catSelect.value : 'ALL';
    const dateFromRaw = fromInput ? (fromInput.value || '').trim() : '';
    const dateToRaw = toInput ? (toInput.value || '').trim() : '';
    const cycle = STATE.activeCycle || '2026';

    const dateFrom = normalizePermissionDateStr(dateFromRaw);
    const dateTo = normalizePermissionDateStr(dateToRaw);
    let effectiveFrom = dateFrom;
    let effectiveTo = dateTo;
    if (effectiveFrom && effectiveTo && effectiveFrom > effectiveTo) {
        effectiveFrom = dateTo;
        effectiveTo = dateFrom;
    }

    let perms = Array.isArray(STATE.studentPermissions) ? [...STATE.studentPermissions] : [];

    // Filtro por fecha en impresión
    if (effectiveFrom || effectiveTo) {
        perms = perms.filter(p => {
            const pStart = normalizePermissionDateStr(p.startDate || p.date || (p.createdAt ? p.createdAt.slice(0, 10) : ''));
            const pEnd = normalizePermissionDateStr(p.endDate || pStart);
            if (!pStart && !pEnd) return true;
            if (effectiveFrom && effectiveTo) {
                return (pStart <= effectiveTo && pEnd >= effectiveFrom);
            } else if (effectiveFrom) {
                return pEnd >= effectiveFrom;
            } else if (effectiveTo) {
                return pStart <= effectiveTo;
            }
            return true;
        });
    }

    if (targetGrade !== 'ALL') {
        perms = perms.filter(p => {
            const pGrade = (p.grade || '').toLowerCase();
            const pSec = (p.section || '').toLowerCase();
            return pGrade.includes(targetGrade.toLowerCase()) || `${pGrade} ${pSec}`.includes(targetGrade.toLowerCase());
        });
    }

    if (targetCat !== 'ALL') {
        perms = perms.filter(p => (p.reasonCategory || '').toLowerCase() === targetCat.toLowerCase());
    }

    perms.sort((a, b) => new Date(b.createdAt || b.startDate) - new Date(a.createdAt || a.startDate));

    // Período para encabezado oficial
    let periodText = `Historial Oficial General - Ciclo Escolar ${cycle}`;
    if (effectiveFrom && effectiveTo) {
        periodText = effectiveFrom === effectiveTo ? `Fecha Oficial: ${effectiveFrom}` : `Período: Del ${effectiveFrom} al ${effectiveTo}`;
    } else if (effectiveFrom) {
        periodText = `Período: Desde ${effectiveFrom}`;
    } else if (effectiveTo) {
        periodText = `Período: Hasta ${effectiveTo}`;
    }

    const activeBim = parseInt(STATE.config?.activeBimestre) || 1;
    let rowsHtml = '';
    if (perms.length === 0) {
        rowsHtml = '<tr><td colspan="6" style="text-align:center; padding:25px; color:#64748b;">No se registran permisos de ausencia autorizados bajo los criterios seleccionados.</td></tr>';
    } else {
        rowsHtml = perms.map((p, idx) => {
            const isSingleDay = !p.endDate || p.endDate === p.startDate;
            const dateStr = isSingleDay ? p.startDate : `${p.startDate} al ${p.endDate}`;
            const sObj = (STATE.students || []).find(s => s && (s.id === p.studentId || (s.carne && s.carne === p.personalCode) || (s.personalCode && s.personalCode === p.personalCode)));
            let isRet = false, isAus = false, isExon = false;
            if (sObj) {
                isRet = (sObj.status === 'Retirado' || sObj.status === 'Inactivo') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(sObj, activeBim) : true);
                isAus = (sObj.status === 'Ausente') && (typeof isStudentRetiredInBimestre === 'function' ? isStudentRetiredInBimestre(sObj, activeBim) : true);
                isExon = !isRet && !isAus && (typeof isStudentExonerated === 'function' ? isStudentExonerated(sObj, activeBim) : false);
            }

            let rowBg = '';
            let tagHtml = '';
            if (isRet) {
                rowBg = 'background-color:#fef2f2; color:#b91c1c;';
                tagHtml = ' <span style="background:#fee2e2; color:#b91c1c; font-size:7.5pt; font-weight:800; padding:1px 5px; border-radius:3px; border:1px solid #fca5a5;">RETIRADO</span>';
            } else if (isAus) {
                rowBg = 'background-color:#fffbeb; color:#b45309;';
                tagHtml = ' <span style="background:#fef3c7; color:#b45309; font-size:7.5pt; font-weight:800; padding:1px 5px; border-radius:3px; border:1px solid #fde68a;">AUSENTE</span>';
            } else if (isExon) {
                rowBg = 'background-color:#f0f9ff; color:#0369a1;';
                tagHtml = ` <span style="background:#e0f2fe; color:#0369a1; font-size:7.5pt; font-weight:800; padding:1px 5px; border-radius:3px; border:1px solid #7dd3fc;">EXONERADO (B${activeBim})</span>`;
            }

            return `
                <tr style="${rowBg}">
                    <td style="text-align:center; font-weight:700;">${idx + 1}</td>
                    <td style="text-align:center;">${escapeHtml(dateStr)}</td>
                    <td>
                        <strong>${escapeHtml(p.studentName)}</strong>${tagHtml}<br>
                        <small>Cód: ${escapeHtml(p.personalCode || 'S/C')}</small>
                    </td>
                    <td>${escapeHtml(p.grade || '')} ${escapeHtml(p.section || '')}</td>
                    <td>
                        <strong>[${escapeHtml(p.reasonCategory)}]</strong> ${escapeHtml(p.reasonDetail)}
                        ${p.docRef ? `<br><small>Ref: ${escapeHtml(p.docRef)}</small>` : ''}
                    </td>
                    <td style="text-align:center;"><small>${escapeHtml(p.authorizedBy || 'Auxiliatura')}</small></td>
                </tr>
            `;
        }).join('');
    }

    const printContent = `<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <title>Libro Oficial de Permisos de Ausencia - ENCCO - ${cycle}</title>
    <style>
        @page { size: letter landscape; margin: 12mm 15mm; }
        body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 9pt; color: #1e293b; margin: 0; padding: 0; line-height: 1.35; }
        .header { display: flex; align-items: center; justify-content: space-between; border-bottom: 2.5px solid #d97706; padding-bottom: 10px; margin-bottom: 14px; }
        .header-logo { width: 65px; height: auto; }
        .header-center { text-align: center; flex: 1; margin: 0 15px; }
        .header-center h1 { font-size: 13pt; margin: 0; font-weight: 800; text-transform: uppercase; color: #0f172a; }
        .header-center h2 { font-size: 11pt; margin: 3px 0 0 0; color: #d97706; font-weight: 700; text-transform: uppercase; }
        .header-center p { font-size: 8.5pt; margin: 2px 0 0 0; color: #475569; }
        
        table { width: 100%; border-collapse: collapse; margin-bottom: 25px; font-size: 8.5pt; }
        th, td { border: 1px solid #cbd5e1; padding: 6px 8px; text-align: left; vertical-align: top; }
        th { background: #fffbeb; font-weight: 700; color: #b45309; text-transform: uppercase; font-size: 8pt; text-align: center; }
        
        .signatures { display: flex; justify-content: space-around; margin-top: 40px; page-break-inside: avoid; }
        .sign-box { width: 35%; text-align: center; font-size: 8.5pt; }
        .sign-line { border-top: 1.5px solid #334155; margin-bottom: 5px; }
        
        .footer-note { font-size: 7.5pt; color: #64748b; text-align: center; border-top: 1px solid #e2e8f0; padding-top: 6px; margin-top: 15px; }
        @media print {
            .no-print { display: none !important; }
        }
    </style>
</head>
<body>
    <div class="header">
        <img src="logo.png" alt="Logo ENCCO" class="header-logo" onerror="this.style.display='none'">
        <div class="header-center">
            <h1>Escuela Nacional de Ciencias Comerciales</h1>
            <h2>Libro de Registro Oficial de Permisos de Ausencia</h2>
            <p>Jutiapa, Guatemala &bull; Ciclo Escolar Oficial ${escapeHtml(cycle)} &bull; <strong>${escapeHtml(periodText)}</strong> &bull; Emisión: ${new Date().toLocaleDateString('es-GT')}</p>
        </div>
        <div style="width:65px; text-align:right; font-size:8pt; color:#64748b;">
            Control de<br>Asistencia
        </div>
    </div>

    <table>
        <thead>
            <tr>
                <th style="width:25px;">No.</th>
                <th style="width:110px;">Fecha(s)</th>
                <th>Estudiante</th>
                <th>Grado y Sección</th>
                <th>Motivo y Justificación</th>
                <th style="width:130px;">Autorizado por</th>
            </tr>
        </thead>
        <tbody>
            ${rowsHtml}
        </tbody>
    </table>

    <div class="signatures">
        <div class="sign-box">
            <div class="sign-line"></div>
            <strong>Profesor(a) Auxiliar de Disciplina</strong><br>
            ENCCO Jutiapa
        </div>
        <div class="sign-box">
            <div class="sign-line"></div>
            <strong>Dirección del Plantel</strong><br>
            Vo.Bo. Institucional
        </div>
    </div>

    <div class="footer-note">
        Documento oficial generado por la Plataforma Digital ENCCO &bull; Emitido: ${new Date().toLocaleDateString('es-GT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' })} &bull; Página 1 de 1
    </div>

    <script>
        window.onload = function() {
            window.print();
        };
    </script>
</body>
</html>`;

    const printWin = (typeof window !== 'undefined' && window.open) ? window.open('', '_blank') : null;
    if (printWin) {
        printWin.document.open();
        printWin.document.write(printContent);
        printWin.document.close();
        setTimeout(() => {
            try {
                printWin.focus();
                printWin.print();
            } catch(e) {}
        }, 400);
    } else {
        renderAndShowPrintDocument('Libro Oficial de Permisos de Ausencia', printContent, 'landscape');
    }
}
window.printPermissionsLog = printPermissionsLog;


// ==========================================================================
// SIDEBAR COLAPSABLE — Funciones de toggle y persistencia
// ==========================================================================
function toggleNavGroup(groupId) {
    const group = document.getElementById(groupId);
    if (!group) return;
    group.classList.toggle('collapsed');
    saveSidebarState();
}
window.toggleNavGroup = toggleNavGroup;

function saveSidebarState() {
    const groups = document.querySelectorAll('.nav-group');
    const state = {};
    groups.forEach(g => {
        state[g.id] = g.classList.contains('collapsed');
    });
    try { localStorage.setItem('encco_sidebar_state', JSON.stringify(state)); } catch(e) {}
}

function restoreSidebarState() {
    try {
        const saved = JSON.parse(localStorage.getItem('encco_sidebar_state') || '{}');
        Object.keys(saved).forEach(id => {
            const g = document.getElementById(id);
            if (g && saved[id]) g.classList.add('collapsed');
        });
    } catch(e) {}
}

function expandGroupForView(viewName) {
    if (!viewName) return;
    const navItem = document.querySelector('.nav-item[data-view="' + viewName + '"]');
    if (!navItem) return;
    const group = navItem.closest('.nav-group');
    if (group && group.classList.contains('collapsed')) {
        group.classList.remove('collapsed');
        saveSidebarState();
    }
}

function initSidebarGroups() {
    restoreSidebarState();
    if (STATE && STATE.activeView) {
        expandGroupForView(STATE.activeView);
    }
    // Asegurar títulos de grupo visibles solo si tienen items
    document.querySelectorAll('.nav-group-header .nav-section-label, .nav-group-title').forEach(el => {
        el.style.removeProperty('display');
        el.style.setProperty('display', 'block', 'important');
        el.classList.remove('hidden');
    });
    if (STATE && STATE.currentRole && typeof applyUserRole === 'function') {
        applyUserRole(STATE.currentRole);
    }
}
window.initSidebarGroups = initSidebarGroups;

// Auto-expand group upon navigation
const _origNavigateTo = window.navigateTo || (typeof navigateTo === 'function' ? navigateTo : null);
if (typeof _origNavigateTo === 'function') {
    window.navigateTo = function(viewName, event) {
        expandGroupForView(viewName);
        return _origNavigateTo.call(this, viewName, event);
    };
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initSidebarGroups);
} else {
    setTimeout(initSidebarGroups, 100);
}

// ==========================================================================
// UTILIDAD DE RESPALDO Y PRESERVACIÓN DE BASE DE DATOS EN FORMATO JSON
// ==========================================================================
async function exportDatabaseBackupJSON() {
    const currentRole = (STATE.currentRole || (STATE.currentUser && STATE.currentUser.role) || '').toLowerCase();
    const isDirectorOrAdmin = ['director', 'admin', 'super_usuario'].includes(currentRole);
    if (!isDirectorOrAdmin) {
        if (typeof showToast === 'function') {
            showToast('Acceso restringido: La copia de seguridad es exclusiva para Dirección.', 'danger');
        }
        return;
    }

    if (typeof showToast === 'function') {
        showToast('Generando copia de seguridad completa de la base de datos...', 'info');
    }

    try {
        const backupData = {
            metadata: {
                appName: 'ENCCO Jutiapa Plataforma Oficial',
                version: '2026.09',
                exportTimestamp: new Date().toISOString(),
                exportedBy: (STATE.currentUser && STATE.currentUser.username) || 'admin',
                activeCycleKey: STATE.activeCycleKey || (new Date().getFullYear().toString())
            },
            encc_school_state: null,
            exoneraciones: null,
            permissions: null,
            localCacheSummary: {
                studentsCount: (STATE.students && STATE.students.length) || 0,
                gradesCount: (STATE.grades && STATE.grades.length) || 0,
                usersCount: (STATE.users && STATE.users.length) || 0,
                activeCycle: STATE.activeCycleKey || '2026'
            }
        };

        if (typeof firebase !== 'undefined' && firebase.database) {
            const db = firebase.database();
            const [stateSnap, exonSnap, permSnap] = await Promise.all([
                db.ref('encc_school_state').once('value').catch(() => null),
                db.ref('exoneraciones').once('value').catch(() => null),
                db.ref('permissions').once('value').catch(() => null)
            ]);

            if (stateSnap && stateSnap.exists()) backupData.encc_school_state = stateSnap.val();
            if (exonSnap && exonSnap.exists()) backupData.exoneraciones = exonSnap.val();
            if (permSnap && permSnap.exists()) backupData.permissions = permSnap.val();
        }

        const jsonStr = JSON.stringify(backupData, null, 2);
        const blob = new Blob([jsonStr], { type: 'application/json;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        const dateStr = new Date().toISOString().slice(0, 10);
        link.download = `Copia_Seguridad_ENCCO_${STATE.activeCycleKey || '2026'}_${dateStr}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        if (typeof showToast === 'function') {
            showToast('Copia de seguridad JSON generada y descargada exitosamente.', 'success');
        }
    } catch (err) {
        console.error('Error al exportar respaldo JSON:', err);
        if (typeof showToast === 'function') {
            showToast('Error al exportar respaldo: ' + (err.message || ''), 'danger');
        }
    }
}
window.exportDatabaseBackupJSON = exportDatabaseBackupJSON;
